// Helpers for the per-provider element accordion shown on collection feeds.
// No element catalog yet — every provider section reuses the one shared
// postElements list (['author','rating','text','media']). Future work can give
// providers their own lists; this file is where that mapping would live.

// Distinct provider types configured on the feed, in the order their sources
// appear. The accordion gate (>1 type) and the render both read this from the
// same feedData so they can never diverge.
export const getConfiguredProviderTypes = ( feedData ) => {
    const sources = feedData?.sourcesList || [];
    const types = [];
    sources.forEach( ( source ) => {
        if( source.provider && !types.includes( source.provider ) ){
            types.push( source.provider );
        }
    } );
    return types;
};

// Display name for a provider type, from the localized providers catalog.
export const getProviderLabel = ( sbCustomizer, type ) => {
    const match = ( sbCustomizer?.providers || [] ).find( ( provider ) => provider.type === type );
    if( match?.name ){
        return match.name;
    }
    return type.charAt( 0 ).toUpperCase() + type.slice( 1 );
};
