import * as RadixAccordion from '@radix-ui/react-accordion';

/**
 * Canonical Accordion primitive for sb-customizer.
 *
 * Wraps @radix-ui/react-accordion and provides:
 *   - role="region" on content
 *   - aria-expanded on trigger
 *   - Trigger becomes a real <button> when not using asChild,
 *     or attaches button behavior to your element when using asChild
 *   - Enter/Space to toggle
 *   - data-state="open"|"closed" attribute for CSS animations
 *
 * Use the `asChild` prop on AccordionItem/Trigger/Content to attach Radix
 * behavior to existing markup. Example:
 *
 *   <AccordionRoot>
 *     <AccordionItem value="basic" asChild>
 *       <div className="sb-control-group">
 *         <AccordionTrigger asChild>
 *           <div className="sb-control-group__heading">{label}</div>
 *         </AccordionTrigger>
 *         <AccordionContent asChild>
 *           <div className="sb-control-group__body">{children}</div>
 *         </AccordionContent>
 *       </div>
 *     </AccordionItem>
 *   </AccordionRoot>
 *
 * For collapse animations, target `[data-state="open"]` / `[data-state="closed"]`
 * on the AccordionContent element.
 *
 * Reference: .pitch/wcag-accessibility-audit/react-canonical-pattern.md (PR 1).
 */
export function AccordionRoot({ type = 'single', collapsible = true, ...rest }) {
    return <RadixAccordion.Root type={type} collapsible={collapsible} {...rest} />;
}

export const AccordionItem = RadixAccordion.Item;
export const AccordionHeader = RadixAccordion.Header;
export const AccordionTrigger = RadixAccordion.Trigger;
export const AccordionContent = RadixAccordion.Content;
