import SbUtils from '../../Utils/SbUtils'
const parse = require('html-react-parser');

const Button = ( props ) => {

    const   slug = 'sb-btn',
            classesList =  [ 'type', 'size' ],
            actionsList =  [ 'onClick' ],
            attributesList = [
                { 'icon-position' : props?.iconPosition || 'right'},
                'full-width',
                'boxshadow',
                'disabled',
                'loading'
            ];

    const createMarkup = ( ) => {
        return { __html: 'text' };
    }

    const isIconOnly = ! props?.text && Boolean( props?.icon );

    if ( process.env.NODE_ENV !== 'production' && isIconOnly && ! props?.ariaLabel ) {
        // eslint-disable-next-line no-console
        console.warn( '[sb-customizer] Icon-only Button is missing aria-label.' );
    }

    return (
        <button
            type="button"
            className={ SbUtils.getClassNames( props, slug, classesList ) }
           { ...SbUtils.getElementActions( props, actionsList ) }
           { ...SbUtils.getElementAttributes( props, attributesList ) }
           data-onlyicon={ isIconOnly ? 'true' : undefined }
           data-icon-position={ props?.iconPosition || 'right' }
           aria-label={ isIconOnly ? props?.ariaLabel : undefined }
        >
            { SbUtils.printIcon( props.icon, 'sb-btn-icon', false, props?.iconSize ) }
            { ( props?.text !== undefined ) &&
                // nosemgrep: react-dangerouslysetinnerhtml -- Safe: text comes from WordPress i18n translations
                <span
                    dangerouslySetInnerHTML={{__html: props?.text.replace(/\s/g, '&nbsp;') }}
                >
                </span>
            }

            {
                props?.tooltip !== undefined &&
                SbUtils.printTooltip( props.tooltip, {
                    type : props?.tooltipType,
                    position : props?.tooltipPosition
                } )
            }

        </button>
    )
}

export default Button;
