/**
 * PopupSectionHeader Component
 *
 * Reusable header for Review Alert sidebar sections with BACK button navigation.
 * Used in: Review Alert, Review Feed, Filters, Visibility, Sources sections.
 *
 * @param {string} title - Section title to display
 * @param {function} onBack - Callback function when BACK button is clicked
 */
import { useRef, useEffect } from 'react';
import { __ } from '@wordpress/i18n';
import SbUtils from '../../Utils/SbUtils';

const PopupSectionHeader = ( { title, onBack } ) => {
	// a11y (SMASH-1377 v2): the Review Alert sidebar is a multi-view flow; on
	// section change a fresh header renders but focus stayed on the old
	// (now-removed) control. Move focus to this section's heading whenever the
	// title changes so keyboard/SR users land in—and hear—the new section. The
	// <h2> is tabIndex=-1 (programmatically focusable, not in the tab order);
	// its focus ring is suppressed in a11y.css.
	const headingRef = useRef( null );
	useEffect( () => {
		if ( headingRef.current ) {
			headingRef.current.focus();
		}
	}, [ title ] );

	return (
		<div className="sb-popup-section-header sb-fs">
			<button
				className="sb-popup-back-btn"
				onClick={ onBack }
			>
				{ SbUtils.printIcon( 'chevron-left' ) }
				<span>{ __( 'BACK', 'reviews-feed' ) }</span>
			</button>
			<h2 className="sb-popup-section-title" tabIndex={ -1 } ref={ headingRef }>{ title }</h2>
		</div>
	);
};

export default PopupSectionHeader;
