import { useEffect, useRef, useState } from 'react';
import { ICONS, emphasise, Section, signatureHTML } from './EmbedShared';
import EmailEmbedView from './EmailEmbedView';
import { __, sprintf } from '@wordpress/i18n';
import EmbedTargetPicker from './EmbedTargetPicker';

/**
 * The embed modal, shared by feeds and badges (SBR-163).
 *
 * Destinations get equal billing, as the design draws them: flat sections all
 * visible at once. Which ones appear is config, not a fork — a badge adds email
 * and image over the feed's page/post and shortcode.
 *
 * Textdomain is `reviews-feed`. This package is shared, so `sb-customizer` reads
 * like the right answer — but the plugin registers exactly one domain
 * (`wp_set_script_translations( 'sb-customizer-app', 'reviews-feed', … )`) and
 * extracts exactly one (`make-pot --domain="reviews-feed"`), so a string tagged
 * anything else is never extracted and never loaded. It renders in English in every
 * locale and nothing fails. See i18n-text-domain.test.js, which pins this.
 *
 * Nothing here fetches. The caller passes `targets` (from SBR_Embed_Targets), the
 * shortcode and the handlers.
 *
 * @param {string} props.previewHtml Server-rendered, server-escaped markup. It reaches
 *   `dangerouslySetInnerHTML` in EmailEmbedView unchanged, so a caller passing anything
 *   it has not escaped opens an HTML-injection sink. This package is vendored by other
 *   plugins, so the contract is stated here rather than left to the one consumer that
 *   happens to satisfy it; embed-modal-innerhtml-callers.test.js pins the caller set.
 */


const EmbedModal = ( {
    // 'feed' | 'badge' — decides which sections exist, nothing else.
    kind = 'feed',
    targets = [],
    shortcode = '',
    saved = true,
    onEmbedToTarget,
    onCreatePage,
    // Forwarded to the picker, which owns the create row. Defaults OFF: the row needs
    // an onCreatePage the caller may not have, and a control that opens nothing is
    // worse than no control. Reviews Feed opts in for saved badges.
    allowCreate = false,
    onCopy,
    /* Told when a copy did NOT happen, so the caller can say so. Optional: a
       consumer that omits it simply shows no toast, which is still better than
       the success toast this used to show unconditionally. */
    onCopyFailed,
    imageURL,
    siteEditorURL,
    widgetsPageURL = '',
    blockTitle,
    previewHtml,
    emailSnippet,
    emailBlocked,
    siteURL,
    badgeName,
} ) => {
    const [ target, setTarget ] = useState( null );

    // What the picker is typing into its "new page" field, so the CTA below can
    // become that field's submit. The picker owns the state; this mirrors it.
    const [ newPage, setNewPage ] = useState( { creating: false, title: '' } );
    // 'main' | 'email'. The email set-up is a second VIEW of this modal, not a
    // separate dialog — the design keeps the frame and swaps the body, with a
    // back arrow in the header.
    const [ view, setView ] = useState( 'main' );

    /* The heading is retitled per view (embed-modal-v2.html:1439) and takes focus
       on the swap, skipping the first render where the dialog already does it
       (CustomizerEmbedModal.js:12-21, SMASH-1377). Without the move, a keyboard
       user gets no announcement that the view changed. */
    const headingRef = useRef( null );
    const firstViewRender = useRef( true );

    useEffect( () => {
        if ( firstViewRender.current ) {
            firstViewRender.current = false;

            return;
        }

        if ( headingRef.current ) {
            headingRef.current.focus();
        }
    }, [ view ] );

    const heading = view === 'email'
        ? __( 'Embed in an Email', 'reviews-feed' )
        : ( kind === 'badge'
            ? __( 'Embed Badge', 'reviews-feed' )
            : __( 'Embed Feed', 'reviews-feed' ) );

    const copyViaTextarea = ( text, label ) => {
        const scratch = document.createElement( 'textarea' );
        scratch.value = text;
        scratch.style.position = 'fixed';
        scratch.style.opacity = '0';
        document.body.appendChild( scratch );
        scratch.select();

        // execCommand answers false when nothing was copied — and can THROW in a
        // sandboxed or permission-restricted context, which left the textarea
        // appended to the body and took the error out through the click handler.
        // try/finally so the node goes either way and the failure reaches onCopyFailed.
        let copied = false;

        try {
            copied = document.execCommand( 'copy' );
        } catch ( e ) {
            copied = false;
        } finally {
            scratch.remove();
        }

        if ( copied ) {
            onCopy?.( label );
        } else {
            onCopyFailed?.();
        }
    };

    const copy = ( text, label ) => {
        // navigator.clipboard needs a secure context, which plain http is not.
        // The fallback hangs off the REJECTION as well as the missing API — the
        // write also rejects on an unfocused document and a denied permission.
        if ( navigator.clipboard?.writeText ) {
            navigator.clipboard.writeText( text )
                .then( () => onCopy?.( label ) )
                .catch( () => copyViaTextarea( text, label ) );
            return;
        }

        copyViaTextarea( text, label );
    };

    /* Two clipboard flavours from one press: text/html so a signature editor
       pastes the rendered badge, and text/plain set to the image URL so an
       editor that only takes text still gets something live. A plain-text
       rating sentence would freeze the moment it landed. */
    const copyForSignature = async () => {
        const html = signatureHTML( { href: siteURL, src: imageURL, alt: badgeName } );

        try {
            if ( window.ClipboardItem && navigator.clipboard?.write ) {
                await navigator.clipboard.write( [ new window.ClipboardItem( {
                    'text/html': new Blob( [ html ], { type: 'text/html' } ),
                    'text/plain': new Blob( [ imageURL ], { type: 'text/plain' } ),
                } ) ] );
                onCopy?.( __( 'Badge copied — paste it into your signature', 'reviews-feed' ) );
                return;
            }
        } catch ( e ) {
            // Falls through: Firefox has no ClipboardItem for text/html, and a
            // rejected write here should still leave the user with the URL.
        }

        copy( imageURL, __( 'Image URL copied', 'reviews-feed' ) );
    };

    if ( view === 'email' ) {
        return (
            <EmailEmbedView
                heading={ heading }
                emailSnippet={ emailSnippet }
                emailBlocked={ emailBlocked }
                imageURL={ imageURL }
                previewHtml={ previewHtml }
                headingRef={ headingRef }
                onBack={ () => setView( 'main' ) }
                copy={ copy }
                copyForSignature={ copyForSignature }
            />
        );
    }

    return (
        <div className="sb-embed-modal">
            <h4
                className="sb-h4 sb-modal-view-heading"
                tabIndex={ -1 }
                ref={ headingRef }
            >
                { heading }
            </h4>

            { ! saved && (
                <p className="sb-embed-notice">
                    { ICONS.info }
                    <span>
                        { __( 'Save first — the shortcode and links become available once this exists on the site.', 'reviews-feed' ) }
                    </span>
                </p>
            ) }

            { /* Titles, descriptions and button labels are the design's, verbatim
                 rather than paraphrased. */ }
            <Section
                icon="page"
                title={ __( 'Post or a Page', 'reviews-feed' ) }
                description={ __( 'We will redirect you to Gutenberg editor', 'reviews-feed' ) }
            >
                <EmbedTargetPicker
                    targets={ targets }
                    value={ target }
                    onChange={ setTarget }
                    onCreate={ onCreatePage }
                    onDraftChange={ setNewPage }
                    allowCreate={ allowCreate }
                    // Same gate as the CTA below. Without it the picker's own
                    // Enter-to-create path bypassed it.
                    saved={ saved }
                />

                { /* One button, two jobs, as the design's cta() does it
                     (embed-modal-v2.html:1223-1232): naming an existing page, or
                     naming one that does not exist yet.
                     Gated on `saved` like the other two CTAs — the wizard param
                     carries the id, so firing this unsaved sends an empty one and
                     the block lands without a feed. */ }
                <button
                    type="button"
                    className="sb-embed-cta"
                    disabled={ ! saved || ( newPage.creating ? newPage.title.trim() === '' : ! target ) }
                    onClick={ () => {
                        if ( newPage.creating ) {
                            if ( newPage.title.trim() !== '' ) {
                                onCreatePage?.( newPage.title.trim() );
                            }

                            return;
                        }

                        if ( target ) {
                            onEmbedToTarget?.( target );
                        }
                    } }
                >
                    <span className="lb">
                        { newPage.creating
                            ? __( 'Create Page and Go', 'reviews-feed' )
                            : __( 'Add and Go to Page', 'reviews-feed' ) }
                    </span>
                    { ICONS.arrow }
                </button>

                { target?.status === 'draft' && (
                    <p className="sb-embed-help">
                        { emphasise(
                            __( 'Saved as a %s — nothing is public until you publish it.', 'reviews-feed' ),
                            __( 'draft', 'reviews-feed' )
                        ) }
                    </p>
                ) }
            </Section>

            { /* Block themes can place this once and have it appear everywhere,
                 which is a different answer from "put it on this page". The
                 design offers it as its own row, and it applies to feeds and
                 badges alike. */ }
            { siteEditorURL && (
                <Section
                    icon="layout"
                    title={ __( 'Show this on every page', 'reviews-feed' ) }
                    description={ blockTitle
                        // One sentence with one %s, not three fragments: concatenation
                        // freezes word order and ships "and drop it in." alone.
                        // translators: %s: block name, e.g. "Trust Badge".
                        ? sprintf( __( 'Search \u201C%s\u201D and drop it in.', 'reviews-feed' ), blockTitle )
                        : __( 'Add it once in the Site Editor.', 'reviews-feed' ) }
                    action={
                        <button
                            type="button"
                            className="sb-embed-mini"
                            onClick={ () => window.open( siteEditorURL, '_blank', 'noopener,noreferrer' ) }
                        >
                            { __( 'Open Site Editor', 'reviews-feed' ) }
                            { ICONS.arrow }
                        </button>
                    }
                />
            ) }

            { /* The widget route, as the shipped modal offered it. A classic theme
                 has no Site Editor, so without this it has no site-wide option. */ }
            { widgetsPageURL && (
                <Section
                    icon="layout"
                    title={ __( 'Add to a Widget', 'reviews-feed' ) }
                    description={ __( 'Drop it into a sidebar or footer area.', 'reviews-feed' ) }
                    action={
                        <button
                            type="button"
                            className="sb-embed-mini"
                            onClick={ () => window.open( widgetsPageURL, '_blank', 'noopener,noreferrer' ) }
                        >
                            { __( 'Open Widgets', 'reviews-feed' ) }
                            { ICONS.arrow }
                        </button>
                    }
                />
            ) }

            { /* Badges only. A feed cannot be an email signature or a PNG —
                 offering the rows greyed out would advertise a capability that
                 does not exist for it. */ }
            { kind === 'badge' && (
                <Section
                    icon="mail"
                    title={ __( 'Embed in an Email', 'reviews-feed' ) }
                    description={ __( 'Dynamic Image that updates automatically', 'reviews-feed' ) }
                    action={
                        <button
                            type="button"
                            className="sb-embed-mini"
                            disabled={ ! saved }
                            onClick={ () => setView( 'email' ) }
                        >
                            { __( 'Set up', 'reviews-feed' ) }
                            { ICONS.chevron }
                        </button>
                    }
                />
            ) }


            <Section
                icon="code"
                title={ __( 'Use a shortcode', 'reviews-feed' ) }

                action={
                    <button
                        type="button"
                        className="sb-embed-mini"
                        disabled={ ! saved }
                        onClick={ () => copy( shortcode, __( 'Shortcode copied', 'reviews-feed' ) ) }
                    >
                        { ICONS.copy }
                        { __( 'Copy', 'reviews-feed' ) }
                    </button>
                }
            >
                { saved
                    ? <code className="sb-embed-code">{ shortcode }</code>
                    : <span className="sb-embed-code empty">{ __( 'Available once you save', 'reviews-feed' ) }</span> }
            </Section>
        </div>
    );
};

export default EmbedModal;
