import { useId, useState, useRef, useEffect } from 'react';

/**
 * Hover tooltip listing where something appears, on the same markup and CSS as
 * ReviewAlertsList's DisplayedOnTooltip (review-alert-settings.css owns
 * .sb-displayed-on-*).
 *
 * Presentation only: the caller supplies the items and the header, so "displayed
 * on 3 pages" and "used in 3 places" both fit.
 *
 * TODO(SBR-163): this is a deliberate COPY of that hover shell, not a shared one —
 * DisplayedOnTooltip also derives visibility from a popup's settings, so pointing
 * Review Alerts here means splitting its derivation from its presentation first.
 * Until that happens the shell exists twice.
 *
 * @param {Object}   props
 * @param {string}   props.trigger     Text the user hovers.
 * @param {string}   props.header      Sentence before the bolded count.
 * @param {string}   props.headerCount Bolded count phrase.
 * @param {Array}    props.items       { name, meta, typeLabel, type }.
 * @param {Object}   props.icons       Map of type → node.
 * @param {string}   props.ariaLabel   Label for the trigger.
 * @param {string}   props.triggerClass Extra classes on the trigger.
 */
const LocationsTooltip = ( {
    trigger,
    header,
    headerCount,
    items = [],
    icons = {},
    ariaLabel,
    triggerClass = ''
} ) => {
    const [ isOpen, setIsOpen ] = useState( false );
    const timeoutRef = useRef( null );

    // Small delays either way: opening instantly makes the table twitchy as the
    // pointer crosses rows, and closing instantly makes the panel unreachable.
    const handleMouseEnter = () => {
        if ( timeoutRef.current ) {
            clearTimeout( timeoutRef.current );
        }
        timeoutRef.current = setTimeout( () => setIsOpen( true ), 150 );
    };

    const handleMouseLeave = () => {
        if ( timeoutRef.current ) {
            clearTimeout( timeoutRef.current );
        }
        timeoutRef.current = setTimeout( () => setIsOpen( false ), 100 );
    };

    useEffect( () => {
        return () => {
            if ( timeoutRef.current ) {
                clearTimeout( timeoutRef.current );
            }
        };
    }, [] );

    const tooltipId = useId();

    return (
        // Hover on the wrapper, delayed both edges, so a pointer can cross from
        // trigger to panel without closing it. No role or tab stop here — focus
        // and keys belong to the trigger below.
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions
        <span
            className="sb-displayed-on-tooltip-wrapper"
            onMouseEnter={ handleMouseEnter }
            onMouseLeave={ handleMouseLeave }
        >
            <span
                className={ `sb-displayed-on-trigger ${ triggerClass }`.trim() }
                tabIndex={ 0 }
                role="button"
                aria-label={ ariaLabel }
                aria-expanded={ isOpen }
                // Both conditions: the tooltip renders on `isOpen && items.length > 0`,
                // so on isOpen alone this pointed at an id not in the document.
                aria-describedby={ isOpen && items.length > 0 ? tooltipId : undefined }
                onFocus={ () => setIsOpen( true ) }
                onBlur={ () => setIsOpen( false ) }
                onKeyDown={ ( event ) => {
                    if ( event.key === 'Enter' || event.key === ' ' ) {
                        event.preventDefault();
                        setIsOpen( ( open ) => ! open );

                        return;
                    }

                    // Escape dismisses without moving focus, so the panel
                    // cannot sit over what someone is reading.
                    if ( event.key === 'Escape' ) {
                        setIsOpen( false );
                    }
                } }
            >
                { trigger }
            </span>
            { isOpen && items.length > 0 && (
                <div className="sb-displayed-on-tooltip" role="tooltip" id={ tooltipId }>
                    <div className="sb-displayed-on-tooltip-arrow" />
                    <div className="sb-displayed-on-tooltip-header">
                        <span>{ header } </span>
                        <strong>{ headerCount }</strong>
                    </div>
                    <div className="sb-displayed-on-tooltip-list">
                        { items.map( ( item, index ) => (
                            // name+type rather than the index: a stable identity
                            // survives reordering, with the index only as a last
                            // resort for a row carrying neither.
                            <div
                                key={ `${ item.name || '' }-${ item.type || '' }`.replace( /^-$/, String( index ) ) }
                                className="sb-displayed-on-tooltip-item"
                            >
                                <div className="sb-displayed-on-item-icon">
                                    { icons[ item.type ] || icons.page || null }
                                </div>
                                <div className="sb-displayed-on-item-content">
                                    <div className="sb-displayed-on-item-name">{ item.name }</div>
                                    { item.meta && (
                                        <div className="sb-displayed-on-item-meta">{ item.meta }</div>
                                    ) }
                                </div>
                                { item.typeLabel && (
                                    <div className="sb-displayed-on-item-badge">{ item.typeLabel }</div>
                                ) }
                            </div>
                        ) ) }
                    </div>
                </div>
            ) }
        </span>
    );
};

export default LocationsTooltip;
