import { useState } from 'react';
import SbUtils from '../../../Utils/SbUtils'

const getLightboxImageUrl = (photo) => photo['1280_900'] || photo['500_500'] || photo['90_90'];

// Module scope so it isn't redefined on every PostMedia render — an inline
// component definition is a fresh type each render, which remounts it and
// resets the current-image index mid-navigation.
const Lightbox = ({ photos, currentIndex, onClose }) => {
	const [index, setIndex] = useState(currentIndex);
	const handlePrev = (e) => { e.stopPropagation(); setIndex((index - 1 + photos.length) % photos.length); };
	const handleNext = (e) => { e.stopPropagation(); setIndex((index + 1) % photos.length); };

	return (
		<div
			className="sbr-lightbox-overlay"
			onClick={onClose}
			style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0, 0, 0, 0.9)', zIndex: 99999, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
		>
			<button onClick={handlePrev} style={{ position: 'absolute', left: '20px', background: 'rgba(255,255,255,0.9)', border: 'none', borderRadius: '50%', width: '50px', height: '50px', fontSize: '24px', cursor: 'pointer', zIndex: 100000 }}>‹</button>
			<img src={getLightboxImageUrl(photos[index])} alt="Review photo" style={{ maxWidth: '90%', maxHeight: '90%', objectFit: 'contain' }} onClick={(e) => e.stopPropagation()} />
			<button onClick={handleNext} style={{ position: 'absolute', right: '20px', background: 'rgba(255,255,255,0.9)', border: 'none', borderRadius: '50%', width: '50px', height: '50px', fontSize: '24px', cursor: 'pointer', zIndex: 100000 }}>›</button>
			<button onClick={onClose} style={{ position: 'absolute', top: '20px', right: '20px', background: 'rgba(255,255,255,0.9)', border: 'none', borderRadius: '50%', width: '40px', height: '40px', fontSize: '24px', cursor: 'pointer', zIndex: 100000 }}>×</button>
		</div>
	);
};

const PostMedia = ( { post, postIndex, feedSettings } ) => {
	const [lightboxOpen, setLightboxOpen] = useState(false);
	const [lightboxIndex, setLightboxIndex] = useState(0);

	// Booking review images arrive as reviewer_photos (not post.media). They
	// render as the media element so the "Images or Videos" toggle controls
	// them, independent of the text element.
	const reviewerPhotos = post?.provider?.name?.toLowerCase() === 'booking'
		? ( post?.reviewer_photos || [] )
		: [];

	const printPostMedia = () => {
		if ( post?.media && post?.media.length > 0 ) {
			const mediaSectionClass = ['aliexpress', 'airbnb'].includes( post?.provider?.name?.toLowerCase() ) ? ' sbr-review-horizontal-element' : '';
			return <div className={ 'sbr-media-list sb-fs' + mediaSectionClass }>
				{
					post?.media.map((sMedia, medIndex) => {
						if (sMedia?.type === 'image' && sMedia?.url !== undefined) {
							return (
								<div
									className='sbr-media-item'
									key={medIndex}
									style={{backgroundImage: 'url(' + sMedia?.url + ')'}}
								>
								</div>
							)
						}
					})
				}
			</div>
		}

		if ( reviewerPhotos.length > 0 ) {
			return (
				<>
					<div className='sb-reviewer-photos sbr-review-horizontal-element' style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, 80px)', gap: '10px' }}>
						{reviewerPhotos.map((photo, idx) => (
							<div
								key={idx}
								onClick={() => { setLightboxIndex(idx); setLightboxOpen(true); }}
								style={{ width: '80px', height: '80px', cursor: 'pointer', overflow: 'hidden', borderRadius: '4px' }}
							>
								<img src={photo['90_90']} alt={`Review photo ${idx + 1}`} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
							</div>
						))}
					</div>
					{lightboxOpen && (
						<Lightbox photos={reviewerPhotos} currentIndex={lightboxIndex} onClose={() => setLightboxOpen(false)} />
					)}
				</>
			);
		}

		return null;
	}

	return (
		printPostMedia()
	)
}

export default PostMedia;
