import { useState, useMemo, useRef, useEffect, useCallback } from 'react';
import { __ } from '@wordpress/i18n';
import SbUtils from '../../Utils/SbUtils';
import { isPreviewFailure, BADGE_ACTIONS, FALLBACK_LIST_URL, PREVIEW_DEBOUNCE_MS } from '../../Utils/BadgeSettings';
import TrustBadgeEditorContext from '../Context/TrustBadgeEditorContext';
import TrustBadgeSidebar from '../TrustBadge/TrustBadgeSidebar';
import TrustBadgePreview from '../TrustBadge/TrustBadgePreview';
import CustomizerHeader from '../Global/Headers/CustomizerHeader';

/**
 * Trust Badge editor (SBR-163). ReviewAlertEditor's shell: CustomizerHeader in
 * props mode above a sidebar/preview pair.
 *
 * The preview markup is not built here — PHP renders it through
 * SBR_Badge_Renderer and it is injected, so the editor and the site cannot
 * disagree. See SBR_Trust_Badge_Builder::ajax_preview().
 */



const TrustBadgeEditor = ( {
    editorTopLoader,
    editorNotification,
    editorConfirmDialog,
    isPro,
    isProPlus,
    upsellModal,
    sources,
    sourcesCount,
    // One prop for everything this screen only FORWARDS. The modals below —
    // CustomizerSourcesModal, and AddSourceModal one level under it — destructure
    // these from context and call them unguarded, so a missing one throws when
    // "Add another Source" opens; that is why the set is passed whole rather than
    // trimmed to what the editor reads. Grouping them keeps the component's own
    // contract legible without changing what reaches the modals.
    //
    // Shrinking it further means guarding those modals' reads, which is a change to
    // them rather than to this call site.
    sourceModals = {},
    // Read here, on the non-Pro branch only, so its absence white-screens free
    // sites and never Pro ones.
    allowedTiers,
} ) => {
    const sbCustomizer = window.sb_customizer;
    const config = sbCustomizer?.trustBadges || {};
    const defaults = config.defaults || {};

    const current = config.current || null;

    const [ badge, setBadge ] = useState( () => ( {
        id: current?.id || 0,
        name: current?.name || __( 'New Trust Badge', 'reviews-feed' ),
        settings: { ...defaults, ...( current?.settings || {} ) },
    } ) );

    /**
     * Serialise so key order cannot register as a change: the baseline comes back
     * from PHP, which has no reason to preserve the client's order.
     *
     * @param {Object} value
     * @return {string} Stable JSON.
     */
    const stableJson = ( value ) =>
        JSON.stringify( value, ( key, val ) =>
            ( val && typeof val === 'object' && ! Array.isArray( val ) )
                ? Object.keys( val ).sort().reduce( ( out, k ) => {
                    out[ k ] = val[ k ];
                    return out;
                }, {} )
                : val
        );

    // Baseline for "has unsaved changes". State, not a ref: the memo below has to
    // recompute when a save moves it forward.
    const [ savedSnapshot, setSavedSnapshot ] = useState( () => stableJson( {
        name: current?.name || __( 'New Trust Badge', 'reviews-feed' ),
        settings: { ...defaults, ...( current?.settings || {} ) },
    } ) );

    const [ headerCustomClasses, setHeaderCustomClasses ] = useState( [] );
    const headerClasses = useMemo(
        () => ( { headerCustomClasses, setHeaderCustomClasses } ),
        [ headerCustomClasses ]
    );

    const [ device, setDevice ] = useState( 'desktop' );
    // Seeded from PHP's page-load render of the saved badge, which the payload
    // already carries. Starting empty meant every editor open drew a placeholder
    // for the length of one AJAX round trip over a cold aggregate, for a badge
    // whose markup was sitting in the page the whole time. The AJAX preview still
    // fires and replaces this; on an unedited badge it renders the same thing.
    const [ previewHtml, setPreviewHtml ] = useState( config.previewHtml || '' );
    // The snippet the last save returned. The global is PHP's page-load copy, and its
    // declared width/height are measured off the rendered PNG, so they move with the
    // elements — logos off narrows it, stars or footer off shortens it.
    const [ emailSnippet, setEmailSnippet ] = useState( null );
    const [ emailBlocked, setEmailBlocked ] = useState( null );
    const [ imageURL, setImageURL ] = useState( sbCustomizer?.trustBadges?.imageURL || '' );
    const [ isLoadingPreview, setIsLoadingPreview ] = useState( true );

    // Which of the badge's own sources contributed nothing to the rating. The
    // badge now renders from the ones that DID, so this is the only place the
    // author is told about the gap — it is deliberately editor-only and never
    // reaches the badge markup.
    const [ unreported, setUnreported ] = useState(
        sbCustomizer?.trustBadges?.unreported || []
    );

    // A refused or dropped preview is a different answer from "this badge renders
    // nothing", and the empty state's copy explains the second. Without this the
    // first failed preview told the author their sources had no reviews.
    const [ previewFailed, setPreviewFailed ] = useState( false );
    const previewSeq = useRef( 0 );
    const previewTimeout = useRef( null );

    // A source added or removed changes the RATING, not just the paint, so the badge
    // on screen is wrong rather than merely stale and the placeholder goes back up
    // until the new number arrives. Every other setting is paint, and keeps its badge.
    // Seeded with the badge's own sources so the first load is not counted as a change.
    const lastSourcesKey = useRef( JSON.stringify( badge.settings?.sources ?? [] ) );
    const [ isRecalculating, setIsRecalculating ] = useState( false );

    const settingsJson = JSON.stringify( badge.settings );

    const hasUnsavedChanges = useMemo(
        () => savedSnapshot !== stableJson( { name: badge.name, settings: badge.settings } ),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [ savedSnapshot, badge.name, settingsJson ]
    );

    /**
     * Ask PHP what this badge looks like. Debounced: the hue slider fires on every
     * pixel of a drag, so one sweep would queue a few hundred renders.
     */
    const fetchPreview = useCallback( ( settings ) => {
        // Every fetch, not just the first — TrustBadgeSources reads this to
        // disable its controls mid-fetch.
        setIsLoadingPreview( true );

        // ajaxPost cannot be aborted, so an earlier slow render can answer after
        // a faster one and put the previous badge back. Only the newest may write.
        previewSeq.current += 1;
        const seq = previewSeq.current;

        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            {
                action: BADGE_ACTIONS.preview,
                nonce: sbCustomizer.nonce,
                settings: JSON.stringify( settings ),
            },
            ( data ) => {
                if ( seq !== previewSeq.current ) {
                    return;
                }

                setIsLoadingPreview( false );
                // Cleared before the failure branch: a refused recalculation still
                // ends the recalculation, and leaving this set holds the placeholder
                // over a badge that is never coming back.
                setIsRecalculating( false );

                if ( isPreviewFailure( data ) ) {
                    // Keep the last good preview: blanking makes a transient
                    // failure look like a deleted badge. On the FIRST preview
                    // there is no last good one, so the flag is what stops the
                    // empty state explaining a network error as "no reviews".
                    setPreviewFailed( true );
                    return;
                }

                setPreviewFailed( false );
                setPreviewHtml( data?.data?.html ?? '' );
                // Same response, so the list can never describe a different
                // render than the one on screen.
                setUnreported( data?.data?.unreported ?? [] );
            }
        );
    }, [ sbCustomizer ] );

    useEffect( () => {
        // Set here rather than inside fetchPreview, so the placeholder goes up on the
        // click instead of a debounce later — the gap showed a stale rating for the
        // sources the author had just changed.
        const sourcesKey = JSON.stringify( badge.settings?.sources ?? [] );

        if ( sourcesKey !== lastSourcesKey.current ) {
            lastSourcesKey.current = sourcesKey;
            setIsRecalculating( true );
        }

        if ( previewTimeout.current ) {
            clearTimeout( previewTimeout.current );
        }

        previewTimeout.current = setTimeout( () => fetchPreview( badge.settings ), PREVIEW_DEBOUNCE_MS );

        return () => {
            if ( previewTimeout.current ) {
                clearTimeout( previewTimeout.current );
            }
        };
        // badge.settings is compared by value through settingsJson; adding the
        // object itself would refire on every render.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [ settingsJson, fetchPreview ] );

    const updateSetting = ( key, value ) => {
        setBadge( ( prev ) => ( {
            ...prev,
            settings: { ...prev.settings, [ key ]: value },
        } ) );
    };

    const updateSettings = ( patch ) => {
        setBadge( ( prev ) => ( {
            ...prev,
            settings: { ...prev.settings, ...patch },
        } ) );
    };

    const handleNameChange = ( name ) => {
        setBadge( ( prev ) => ( { ...prev, name } ) );
    };

    const goBackToList = () => {
        // A missing key would navigate to the string "undefined". The badges
        // screen is the honest fallback: it is where this button means to go,
        // and it is reachable without the localised object.
        window.location.href = config.listURL || FALLBACK_LIST_URL;
    };

    const saveBadge = ( exit = false ) => {
        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            {
                action: BADGE_ACTIONS.save,
                nonce: sbCustomizer.nonce,
                id: badge.id,
                name: badge.name,
                settings: JSON.stringify( badge.settings ),
            },
            ( data ) => {
                // Bail without notifying: ajaxPost raises the server's message
                // itself now. The `! data?.data` half stays — a 200 with no payload
                // is not a refusal ajaxPost will report, and continuing past it
                // left a new badge with no id, so the next save created a second.
                if ( data?.success === false ) {
                    return;
                }

                if ( ! data?.data ) {
                    editorNotification && SbUtils.applyNotification( {
                        type: 'error',
                        icon: 'info',
                        text: __( 'The badge could not be saved. Please try again.', 'reviews-feed' ) }, editorNotification );

                    return;
                }

                const saved = data.data;

                if ( typeof saved.emailSnippet === 'string' ) {
                    setEmailSnippet( saved.emailSnippet );
                }

                // Why the email route is off, when it is. Same additive shape as the
                // two above, so an older server that sends neither key changes nothing.
                if ( typeof saved.emailBlocked === 'string' ) {
                    setEmailBlocked( saved.emailBlocked );
                }

                // Same reason as the snippet: the page-load payload only carries
                // `imageURL` for a badge that already existed, so one created here
                // had none and the email step offered an empty image.
                if ( typeof saved.imageURL === 'string' ) {
                    setImageURL( saved.imageURL );
                }

                // A new badge gets its id here; rewrite the URL so the next save
                // updates instead of creating a second badge.
                if ( ! badge.id && saved.id ) {
                    setBadge( ( prev ) => ( { ...prev, id: saved.id } ) );

                    // Guarded: without editURL this rewrote the address bar to
                    // "undefined42", and a reload then went nowhere.
                    if ( config.editURL ) {
                        window.history.replaceState( {}, '', config.editURL + saved.id );
                    }
                }

                // From what was SENT, not the server's echo, as Review Alerts does
                // it (ReviewAlertEditor.js:308): the store answers with defaults
                // filled in, which never equals the client's object.
                setSavedSnapshot( stableJson( {
                    name: badge.name,
                    settings: badge.settings,
                } ) );

                editorNotification && SbUtils.applyNotification( {
                    type: 'success',
                    icon: 'success',
                    text: __( 'Trust badge saved', 'reviews-feed' ) }, editorNotification );

                if ( exit ) {
                    goBackToList();
                }
            },
            editorTopLoader,
            editorNotification,
            {
                // No `success` entry — see the callback. `error` stays, so a
                // dropped connection or a non-JSON response still says something.
                error: {
                    icon: 'info',
                    text: __( 'The badge could not be saved. Please try again.', 'reviews-feed' ),
                },
            }
        );
    };

    return (
        <TrustBadgeEditorContext.Provider
            value={ {
                sbCustomizer,
                config,
                badge,
                setBadge,
                updateSetting,
                updateSettings,
                saveBadge,
                goBackToList,
                device,
                setDevice,
                previewHtml,
                isLoadingPreview,
                isRecalculating,
                previewFailed,
                isPro,
                isProPlus,
                upsellModal,
                unreported,
                sources,
                sourcesCount,
                // Spread, so every key the modals read arrives exactly as before
                // — bulkModal included, which is why it has no line of its own.
                ...sourceModals,
                allowedTiers,
                // Explicitly null, as ReviewAlertsScreen.js:220 provides it.
                globalNotices: null,
                editorTopLoader,
                editorNotification,
                editorConfirmDialog,
                // FeedSources reads this off the context to disable its controls
                // mid-fetch; the badge preview's own loading state feeds it.
                isLoadingReviews: isLoadingPreview,
            } }
        >
            <section className={
                'sb-customizer-header sb-header sb-fs ' +
                ( headerCustomClasses.length > 0 ? headerCustomClasses.join( ' ' ) : '' )
            }>
                <div className="sb-header-content sb-fs">
                    <CustomizerHeader
                        editorTopLoader={ editorTopLoader }
                        itemName={ badge.name }
                        onNameChange={ handleNameChange }
                        onSave={ saveBadge }
                        onBack={ goBackToList }
                        hasChanges={ hasUnsavedChanges }
                        editorConfirmDialog={ editorConfirmDialog }
                        editorNotification={ editorNotification }
                        sbCustomizer={ sbCustomizer }
                        headerClasses={ headerClasses }
                        embedData={ { id: badge.id, type: 'badge' } }
                        // The badge as edited. The header's fallback is PHP's
                        // page-load snapshot, stale after the first change — and
                        // the email stage tells the user to paste this.
                        // `?? undefined` and not `||`: '' is the renderer refusing,
                        // which must not fall back to the page-load snippet.
                        embedPreview={ { previewHtml, emailSnippet: emailSnippet ?? undefined, emailBlocked: emailBlocked ?? undefined, imageURL: imageURL || undefined } }
                        hideEmbed={ ! badge.id }
                    />
                </div>
                { editorTopLoader?.loader && <div className="sb-loadingbar-ctn"></div> }
            </section>

            { /* sb-trust-badge-editor is a scope, not a style: trust-badges.css
                 keys its accent-picker overrides on it so they never reach the
                 Review Alerts picker, which shares .sb-accent-color-custom. */ }
            <section className="sb-cutomizer-ctn sb-fs sb-trust-badge-editor">
                <TrustBadgeSidebar />
                <TrustBadgePreview />
            </section>
        </TrustBadgeEditorContext.Provider>
    );
};

export default TrustBadgeEditor;
