import { useEffect } from 'react'
import { __ } from '@wordpress/i18n'
import SbUtils from '../../Utils/SbUtils'
import { useAnnouncer } from '../../a11y/Announcer'

const FullScreenLoader = () => {
    const announce = useAnnouncer();

    // Long-running operations (popup creation, feed creation flows) mount
    // this loader. Sighted users see the spinner; announce to AT users that
    // a load is in progress so they have parity. Completion is announced
    // separately by the Notification component when the operation finishes.
    useEffect(() => {
        announce( __( 'Loading, please wait', 'sb-customizer' ) );
    }, [ announce ]);

    return (
        <div className='sb-fs-loader'>
            <div className='sb-fs-loader-logo'>
                <div className='sb-fs-loader-spinner'></div>
                { SbUtils.printIcon( 'logo', 'sb-fs-loader-img') }
            </div>
            <div className='sb-fs-loader-txt'>
                Loading...
            </div>
        </div>
    )
}

export default FullScreenLoader;