import { __ } from '@wordpress/i18n'
import SbUtils from '../../Utils/SbUtils'
import {
    DialogRoot,
    DialogPortal,
    DialogOverlay,
    DialogContent,
    DialogTitle,
    DialogClose,
} from '../../a11y'

/**
 * ModalContainer
 *
 * Backwards-compatible wrapper around the canonical Dialog primitive.
 *
 * Public API (unchanged):
 *   - onClose:      callback invoked on Escape / outside-click / close-button
 *   - closebutton:  if truthy, renders the X close affordance
 *   - size:         'tiny' | 'small' | 'medium' | 'large' | 'full'  (-> data-size)
 *   - type:         arbitrary string label                          (-> data-type)
 *   - title:        optional accessible name. If omitted, an SR-only label
 *                   derived from `type` (or a generic fallback) is used so the
 *                   dialog always has an accessible name (WCAG 2.2 / Radix req).
 *   - className:    optional extra class on `.sb-modal-insider` (passthrough)
 *   - describedBy:  optional id of an element describing the dialog. Callers
 *                   can pass `describedBy={'some-id'}` to associate a longer
 *                   description. Silences Radix's dev warning about missing
 *                   `aria-describedby` via explicit opt-out when omitted.
 *   - children:     rendered inside `.sb-modal-insider` (existing slot)
 *
 * Internally swaps the bespoke `<section>` + `useOutsideClick` + bare-div close
 * for a Radix-backed Dialog that provides role="dialog", aria-modal, focus
 * trap, focus restore, Escape-to-close, scroll-lock, and aria-labelledby.
 *
 * Visual DOM classes are preserved (`sb-modal-ctn`, `sb-modal-insider`,
 * `sb-modal-cls`, `sb-cls-ctn`) plus `data-size`/`data-type` so existing CSS
 * rules in sb-common.css / global.css continue to apply unchanged.
 *
 * Closes findings: v2 SBC-1, v2 SBC-2, v3 C1, v3 S5, v3 SBC-3.
 */
const ModalContainer = ( props ) => {
    const attributesList = [
        { 'size': 'medium' },
        'type'
    ];

    const dataAttrs = SbUtils.getElementAttributes( props, attributesList );

    const handleOpenChange = ( open ) => {
        if ( ! open && typeof props.onClose === 'function' ) {
            props.onClose();
        }
    };

    // `ariaLabel` first: `type` is a slug that also feeds data-type, so using it as
    // the accessible name announces untranslated English in every locale. Additive —
    // no existing caller passes it, so their name is unchanged.
    const accessibleTitle = props.ariaLabel
        || props.title
        || ( props.type ? props.type.toString().replace(/-/g, ' ') : __( 'Dialog', 'sb-customizer' ) );

    const insiderClassName = `sb-modal-insider${ props.className ? ' ' + props.className : '' }`;

    return (
        <DialogRoot open={ true } onOpenChange={ handleOpenChange }>
            <DialogPortal>
                <DialogOverlay
                    className='sb-modal-ctn'
                    { ...dataAttrs }
                >
                    <DialogContent
                        className={ insiderClassName }
                        aria-describedby={ props.describedBy }
                        tabIndex={ -1 }
                        onInteractOutside={ props.dismissOnOutsideClick ? undefined : ( event ) => {
                            // a11y/UX (SMASH-1377): an aria-modal dialog should NOT
                            // light-dismiss on outside-click by default — a stray click
                            // must not discard a confirm decision or in-progress input
                            // (the Radix migration enabled this implicitly; the pre-Radix
                            // base was X-button-only). Escape still closes (onEscapeKeyDown
                            // is left to Radix's default). Transient/no-loss modals (e.g.
                            // upsell) opt back in via dismissOnOutsideClick.
                            event.preventDefault();
                        } }
                        onOpenAutoFocus={ ( event ) => {
                            // Preserve legacy behaviour: do not drop focus
                            // into the first focusable child (often an
                            // input). But we MUST move focus into the
                            // dialog itself, otherwise Radix's focus trap
                            // never engages and Tab cycles through the
                            // underlying page. Focusing the Content
                            // container (tabIndex=-1) keeps focus inside
                            // the dialog so Tab moves to its first
                            // interactive descendant. SMASH-1377 v2-r2.
                            event.preventDefault();
                            event.currentTarget.focus();
                        } }
                    >
                        { props.title ? (
                            <DialogTitle className='sb-modal-title'>
                                { props.title }
                            </DialogTitle>
                        ) : (
                            <DialogTitle className='sb-visually-hidden'>
                                { accessibleTitle }
                            </DialogTitle>
                        ) }
                        { props.closebutton && (
                            <DialogClose asChild>
                                <button
                                    type='button'
                                    className='sb-cls-ctn sb-modal-cls sb-button-reset'
                                    aria-label={ __( 'Close', 'sb-customizer' ) }
                                />
                            </DialogClose>
                        ) }
                        { props.children }
                    </DialogContent>
                </DialogOverlay>
            </DialogPortal>
        </DialogRoot>
    );
};

export default ModalContainer;
