import { __ } from '@wordpress/i18n';
import SbUtils from '../../../Utils/SbUtils'

const PostRating = ( { post, postIndex, feedSettings } ) => {
    const halfStarIcon = ( i ) => {
        const icons = [SbUtils.printIcon( 'star', 'sb-item-rating-icon sb-item-rating-icon-dimmed' , i ) , SbUtils.printIcon( 'star', ' sb-item-rating-icon-halfdimmed')];
        return (
            <span className='sb-item-rating-icon sb-feed-item-icon-half' key={i}>
                { icons }
            </span>
        )
    }

    const isCollectionPost = (post) => {
        return post?.provider_id !== undefined && post?.provider_id.includes('collection')
    }

    // SMASH-782 Phase 2 — Booking score badge replaces the star rating.
    //
    // THIS reviewer's own score, on Booking's 0-10 scale. Not the property's:
    // metadata.review_score / review_score_word are the HOTEL's general rating and the
    // relay stamps the same pair onto every card, so reading them here showed every
    // review as "9.5 Exceptional" whatever the guest actually gave. The property score
    // belongs in the header only (Header.js / get_booking_header_rating()).
    //
    // Score and thresholds come from SbUtils so this preview, the review-alert preview
    // and the two PHP helpers (sbr_booking_review_score / sbr_booking_score_word) all
    // agree; only the words are local, in this tree's text domain.
    const bookingWord = ( score ) => ( {
        exceptional: __( 'Exceptional', 'sb-customizer' ),
        superb: __( 'Superb', 'sb-customizer' ),
        veryGood: __( 'Very good', 'sb-customizer' ),
        good: __( 'Good', 'sb-customizer' ),
        pleasant: __( 'Pleasant', 'sb-customizer' ),
    }[ SbUtils.bookingScoreBand( score ) ] || '' );

    const renderBookingScore = () => {
        const score = SbUtils.bookingReviewScore( post );
        if ( score <= 0 ) return null;
        const label = bookingWord( score );

        return (
            <div className='sb-item-rating-score'>
                <span className='sb-item-rating-score-badge'>{score.toFixed(1)}</span>
                {label !== '' && (
                    <span className='sb-item-rating-score-label'>{label}</span>
                )}
            </div>
        );
    };

    const providerName = post?.provider?.name?.toLowerCase();
    const isBooking = providerName === 'booking';
    // Coerce to a number so an absent/non-numeric rating never leaves the star fill
    // as NaN — `NaN < 1` is false, which would light all five stars. 0 → all dimmed.
    // Booking posts do carry their own rating: the relay converts average_score to the
    // 0-5 scale (RapidRemoteBookingReviewsRepository.php:97-99).
    const rating = Number( post?.rating ) || 0;

    return (
        <div className='sb-item-rating sb-fs'>
            <span className='sb-relative'>
                <div className='sb-item-rating-ctn'>
                    {
                        Array.from({ length: 5} , (ic, i) => {
                            const iconClass = rating - i < 1 ? ' sb-item-rating-icon-dimmed' : '';
                            if( rating - i === 0.5 ){
                                return halfStarIcon( i )
                            }
                            return SbUtils.printIcon( 'star', 'sb-item-rating-icon' + iconClass, i )
                        })
                    }
                    {
                        post?.provider?.name === 'facebook' && !isCollectionPost(post) &&
                        <span className='sb-facbook-rating-notice'>
                            {
                                SbUtils.printTooltip(
                                    __( 'Facebook reviews are only based upon a positive or negative recommendation','sb-customizer')
                                    , {
                                            type : 'white',
                                            textAlign : 'center',
                                            replaceText : false
                                        } )
                            }
                            {
                                SbUtils.printIcon( 'info', 'sb-facbook-rating-notice-icon' )
                            }
                        </span>
                    }
                </div>
                { SbUtils.addHighlighter( 'post-rating-icon', 'Rating' , postIndex ) }
            </span>
            { isBooking && renderBookingScore() }
        </div>
    )
}

export default PostRating;