import { useContext, useState } from 'react';
import { __, _n, sprintf } from '@wordpress/i18n';
import TrustBadgesScreenContext from '../../Context/TrustBadgesScreenContext';
import SbUtils from '../../../Utils/SbUtils';
import { BADGE_ACTIONS, COPY_FLASH_MS, DEFAULT_PER_PAGE } from '../../../Utils/BadgeSettings';
import { shortcodeFor } from '../../../Utils/EmbedContract';
import Checkbox from '../../Common/Checkbox';
import Button from '../../Common/Button';
import Select from '../../Common/Select';
import Pagination from '../../Common/Pagination';
import LocationsTooltip from '../../Common/LocationsTooltip';
import LocationTypeIcons from '../../Common/LocationTypeIcons';

/**
 * All Badges — the table. ReviewAlertsList's shell (sb-feedslist-*, bulk bar,
 * tfoot, icon-only actions); only the columns differ, and those follow the
 * design's all-badges list.
 */
/** Shown when a request fails with nothing usable to quote — a dropped
 *  connection, a 500, or an HTML error page where JSON was expected. */
const GENERIC_ERROR = __( 'Something went wrong. Please try again.', 'reviews-feed' );

const TrustBadgesList = () => {
    const {
        sbCustomizer,
        badgesList,
        setBadgesList,
        badgesTotal,
        setBadgesTotal,
        editorTopLoader,
        editorNotification,
        editorConfirmDialog
    } = useContext( TrustBadgesScreenContext );

    const [ selected, setSelected ] = useState( [] );
    const [ bulkAction, setBulkAction ] = useState( '' );
    const [ copiedId, setCopiedId ] = useState( 0 );
    const [ currentPage, setCurrentPage ] = useState( 1 );
    const [ isLoading, setIsLoading ] = useState( false );

    // Sent by the server (SBR_Trust_Badge_Store::PER_PAGE), not repeated here: the
    // two were separate 50s, so 23 badges came to one page and no controls rendered.
    // The 20 fallback matches the constant, for a page served before it was added.
    // `||` already catches 0, '' and NaN. It does not catch a NEGATIVE, which
    // divides to a negative page count that is truthy — so `|| 1` lets it through
    // and the pager renders backwards. Clamped to a positive integer instead.
    //
    // The clamp is on the FLOORED value, not the raw one: `rawPerPage > 0` is true
    // for anything in (0,1), and `Math.floor( 0.5 )` is 0, so the divide below gave
    // `Math.ceil( total / 0 )` = Infinity and the pager tried to render endlessly.
    // Guarding the input and then transforming it is the hole; guard what is used.
    const rawPerPage = Number( sbCustomizer?.trustBadges?.perPage );
    const perPage = Number.isFinite( rawPerPage ) && Math.floor( rawPerPage ) >= 1
        ? Math.floor( rawPerPage )
        : DEFAULT_PER_PAGE;
    const totalPages = Math.max( 1, Math.ceil( ( badgesTotal || 0 ) / perPage ) );

    const bulkActionsList = {
        '': __( 'Bulk Actions', 'reviews-feed' ),
        delete: __( 'Delete', 'reviews-feed' )
    };

    const editUrl = ( id ) => `${ sbCustomizer?.trustBadges?.editURL || '' }${ id }`;

    // One source for the shortcode: it is both displayed and copied, and the two
    // drifting apart would hand someone a shortcode different from the one on
    // screen.


    /**
     * Show the server's refusal, if it sent one.
     *
     * `SbUtils.ajaxPost` looks for it at `data.message`, but wp_send_json_error()
     * nests its payload: the wire shape is `{success:false,data:{message:'…'}}`.
     * So a 403 from the capability check, or a 400 from a bad payload, currently
     * surfaces nowhere. Read the real path here rather than change ajaxPost,
     * which every screen of every vendoring plugin calls.
     *
     * @param {Object} data Parsed AJAX response.
     *
     * @return {boolean} True when a refusal was shown.
     */
    // Whether the response was a refusal, so the callback can stop before acting on
    // it. It no longer raises the notice: SbUtils.ajaxPost reads the nested
    // `data.data.message` itself now and shows it, so doing it here as well put two
    // error toasts on screen.
    // One predicate for "the server refused", used by every branch that has to
    // stop. Three call sites inlined `data?.success === false` instead, so adding a
    // second refusal signal would have had to be remembered in each — review on
    // sb-customizer#192.
    const wasRefused = ( data ) => data?.success === false;

    // Functional form throughout: `selected` captured at render is stale as soon
    // as two ticks land in one batch, and React 18 batches them by default —
    // ReviewAlertsList.selectPopup documents hitting exactly this.
    const toggleSelected = ( id ) => {
        if ( id === 'all' ) {
            setSelected( ( prev ) => ( prev.length === badgesList.length ? [] : badgesList.map( ( b ) => b.id ) ) );
            return;
        }

        setSelected( ( prev ) => (
            prev.includes( id ) ? prev.filter( ( s ) => s !== id ) : [ ...prev, id ]
        ) );
    };

    /**
     * What sits under the name: this badge's sources, as All Feeds does it.
     *
     * Hybrid, per the design's `sourceLabel()`: name one or two platforms, count
     * above that — naming six wraps, and "1 source" says nothing. Names arrive
     * resolved; stored `sources` are bare account_ids.
     */
    const subtitle = ( badge ) => {
        const providers = badge.providers || [];
        const count = ( badge.settings?.sources || [] ).length;

        if ( providers.length > 0 && providers.length <= 2 ) {
            return providers.join( ', ' );
        }

        if ( count > 0 ) {
            // Lowercase: the shipped text-transform: capitalize renders "5
            // Sources". _n because one plural form cannot serve every language.
            return sprintf(
                _n( '%d source', '%d sources', count, 'reviews-feed' ),
                count
            );
        }

        // No sources. The design returns '' here, but an empty line under a name
        // reads as a fault — and this badge renders NOTHING on the front end, which
        // is the one thing the row should say out loud. It previously fell back to
        // "Card · Light", the Review Alerts convention that design decision 02
        // explicitly rejected for this list in favour of the All Feeds one, so it
        // both hid the problem and used the wrong vocabulary to do it.
        return __( 'No sources yet', 'reviews-feed' );
    };

    // `page` on every request: the delete route re-reads the list for the page it is
    // given, so without it deleting from page two answered with page one.
    const post = ( action, body, onDone, success ) => {
        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            { action, nonce: sbCustomizer.nonce, page: currentPage, ...body },
            ( data ) => {
                if ( wasRefused( data ) ) {
                    return;
                }

                onDone( data );

                // Fired HERE, not through ajaxPost's `success` entry. That entry
                // was still present while showRefusal() was added, and ajaxPost
                // only suppresses it when `data.message` is set — which
                // wp_send_json_error() never sets, because it nests the message
                // at data.data.message. So a refusal set the error notice and
                // then had "Badge deleted" painted straight over it.
                editorNotification && SbUtils.applyNotification( {
                    type: 'success',
                    icon: 'success',
                    text: success }, editorNotification );
            },
            editorTopLoader,
            editorNotification,
            {
                // No `success` entry, per above. `error` stays so ajaxPost's
                // .catch() still says something on a dropped connection or a
                // non-JSON response.
                error: { icon: 'info', text: GENERIC_ERROR },
            }
        );
    };

    /**
     * Load one page of badges.
     *
     * @param {number} page 1-based page number.
     *
     * @return {void}
     */
    const loadPage = ( page ) => {
        setIsLoading( true );

        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            { action: BADGE_ACTIONS.list, nonce: sbCustomizer.nonce, page },
            ( data ) => {
                setIsLoading( false );

                // wasRefused() for the refusal half, so "what counts as a refusal"
                // lives in one place; the shape check is this branch's own. The
                // branch raises no notice — ajaxPost already raised the server's
                // message — which is what the removed call used to do here.
                if ( wasRefused( data ) || ! Array.isArray( data?.data?.items ) ) {
                    return;
                }

                setBadgesList( data.data.items );
                setBadgesTotal( data.data.total ?? 0 );
                setSelected( [] );
                setCurrentPage( page );
            },
            editorTopLoader,
            editorNotification,
            { error: { icon: 'info', text: GENERIC_ERROR } }
        );
    };

    const handleDuplicate = ( badge ) => {
        post(
            BADGE_ACTIONS.duplicate,
            { id: badge.id },
            ( data ) => {
                if ( data?.data?.id ) {
                    // Updater form: the array captured at render is stale once a
                    // second duplicate resolves, dropping the earlier row.
                    setBadgesList( ( prev ) => [ data.data, ...prev ] );

                    // The total has to move with it, or a duplicate on a full
                    // page leaves perPage+1 rows on screen while the pager still
                    // counts the old total. Bumped rather than re-read because
                    // this route answers with the new badge alone — delete gets
                    // a `badgesCount` back and re-syncs from it instead.
                    setBadgesTotal( ( prev ) => ( prev || 0 ) + 1 );
                }
            },
            __( 'Badge duplicated', 'reviews-feed' )
        );
    };

    /**
     * Delete, mirroring Review Alerts: same request shape, and the list comes back
     * from the server rather than being guessed at here.
     *
     * @param {Array}  ids     Badge ids.
     * @param {string} message Success notification text.
     */
    const removeBadges = ( ids, message ) => {
        post(
            BADGE_ACTIONS.delete,
            { ids },
            ( data ) => {
                if ( wasRefused( data ) ) {
                    return;
                }

                // The server's list, as ReviewAlertsList takes popupsList back:
                // removing rows before the response makes a refusal look like a
                // success.
                if ( Array.isArray( data?.data?.badgesList ) ) {
                    setBadgesList( data.data.badgesList );

                    if ( data.data.badgesCount !== undefined ) {
                        setBadgesTotal( data.data.badgesCount );

                        // Deleting the last rows of a page leaves currentPage past
                        // the end: the server answers with an empty list for a page
                        // that no longer exists, and an empty list renders
                        // TrustBadgesEmptyState — telling someone with 20 badges
                        // that they have none. Step back to the last real page.
                        const lastPage = Math.max(
                            1,
                            Math.ceil( ( data.data.badgesCount || 0 ) / perPage )
                        );

                        if ( data.data.badgesCount > 0
                            && data.data.badgesList.length === 0
                            && currentPage > lastPage ) {
                            loadPage( lastPage );

                            return;
                        }
                    }
                } else {
                    // Only reachable if the route stops returning `badgesList`;
                    // SBR_Trust_Badge_Builder::delete_response() always does.
                    // The total still has to move, or the count and the pager keep
                    // describing rows that are gone.
                    const removed = ( data?.data?.ids || ids ).map( ( id ) => String( id ) );

                    // Both setters called at the top level: nesting one inside the
                    // other's updater made that updater impure, and React 18 runs
                    // updaters twice in StrictMode to surface exactly that — which
                    // would have double-decremented the total.
                    setBadgesList( ( prev ) => prev.filter( ( b ) => ! removed.includes( String( b.id ) ) ) );
                    // `removed` are ids the server confirmed deleted, and they came
                    // from the selection of rows on screen, so each one was counted.
                    setBadgesTotal( ( total ) => Math.max( 0, total - removed.length ) );
                }

                setSelected( [] );
            },
            message
        );
    };

    /**
     * Open the delete dialog. Review Alerts' shape (ReviewAlertsList.js:386-410):
     * `active` opens it, not `open`.
     *
     * @param {Array}  ids  Badge ids.
     * @param {Object} [badge] The row, when deleting a single one.
     */
    const confirmDelete = ( ids, badge = null ) => {
        const single = ids.length === 1;

        // Resolved from the ids, never from `single`. Both callers reach here with
        // one id: the row's trash button passes the badge object, the bulk action
        // does not — so branching on `single` dropped the caveat for exactly one
        // selected badge, which is the case it was added for. `heading` below gets
        // this right with `single && badge`; this is the same trap one line up.
        //
        // One unknown row is enough to make the set unknown. The guarantee is that
        // we never imply a known state, and the dialog speaks about "anywhere you
        // have placed them" for a set we may not have been able to scan.
        const isUnknown = ( row ) => row?.instances?.status === 'unknown';
        const anyUnknown = badgesList.some(
            ( row ) => ids.includes( row.id ) && isUnknown( row )
        ) || isUnknown( badge );

        editorConfirmDialog.setConfirmDialog( {
            active: true,
            heading: ( single && badge )
                // One string: `Delete "` alone is half a sentence, not translatable.
                // translators: %s: badge name.
                ? sprintf( __( 'Delete "%s"?', 'reviews-feed' ), badge.name )
                : __( 'Delete trust badges?', 'reviews-feed' ),
            // The shipped copy already avoids claiming the badge is unused — it says
            // what happens wherever it IS placed — so the unknown state does not
            // have to retract anything, only add that we could not look.
            // `single && badge`, matching `heading` above rather than `single` alone.
            // Ticking one row and using bulk Apply gives single === true with no
            // badge, which paired the plural heading with singular body text. Same
            // distinction the fix below turns on; it belongs in both places.
            description: anyUnknown
                ? ( ( single && badge )
                    ? __( "We couldn't check where this trust badge is used. It may still be placed on pages, and anywhere it is will stop showing a badge. This action cannot be undone.", 'reviews-feed' )
                    : __( "We couldn't check where some of these trust badges are used. They may still be placed on pages, and anywhere they are will stop showing a badge. This action cannot be undone.", 'reviews-feed' ) )
                : ( ( single && badge )
                    ? __( 'Are you sure you want to delete this trust badge? Anywhere you have placed it will stop showing a badge. This action cannot be undone.', 'reviews-feed' )
                    : __( 'Are you sure you want to delete the selected trust badges? Anywhere you have placed them will stop showing a badge. This action cannot be undone.', 'reviews-feed' ) ),
            confirm: {
                text: __( 'Delete', 'reviews-feed' ),
                icon: 'trash',
                onConfirm: () => {
                    removeBadges( ids, __( 'Badge deleted', 'reviews-feed' ) );
                    editorConfirmDialog.setConfirmDialog( { active: false } );
                }
            },
            cancel: {
                text: __( 'Cancel', 'reviews-feed' )
            }
        } );
    };

    const applyBulkAction = () => {
        if ( bulkAction === 'delete' && selected.length > 0 ) {
            confirmDelete( selected );
        }
    };

    /**
     * Clipboard fallback for insecure contexts.
     *
     * @param {string}   text    Text to copy.
     * @param {Function} onDone  Called once it is on the clipboard.
     */
    const copyViaTextarea = ( text, onDone ) => {
        const scratch = document.createElement( 'textarea' );

        scratch.value = text;
        scratch.style.position = 'fixed';
        scratch.style.opacity = '0';
        document.body.appendChild( scratch );
        scratch.select();

        // execCommand answers false when the copy did not happen — reporting
        // "Copied" regardless told the user their clipboard held something it did
        // not — and it can also THROW, which left the textarea appended to the body.
        // try/finally, as EmbedModal.js does it; that fix was applied there and
        // missed here.
        let copied = false;

        try {
            copied = document.execCommand( 'copy' );
        } catch ( e ) {
            copied = false;
        } finally {
            scratch.remove();
        }

        if ( copied ) {
            onDone();
        } else {
            editorNotification && SbUtils.applyNotification( {
                type: 'error',
                icon: 'info',
                text: __( 'Could not copy — select the shortcode and copy it manually.', 'reviews-feed' ) }, editorNotification );
        }
    };

    const copyShortcode = ( badge ) => {
        const shortcode = shortcodeFor( 'badge', badge.id );

        // navigator.clipboard needs a secure context, which wp-admin over plain
        // http is not — there it rejects while the button says "Copied".
        const flash = () => {
            setCopiedId( badge.id );
            window.setTimeout( () => setCopiedId( 0 ), COPY_FLASH_MS );
        };

        if ( navigator.clipboard?.writeText ) {
            navigator.clipboard.writeText( shortcode ).then( flash ).catch( () => copyViaTextarea( shortcode, flash ) );

            return;
        }

        copyViaTextarea( shortcode, flash );
    };

    const columns = [
        __( 'Name', 'reviews-feed' ),
        __( 'Shortcode', 'reviews-feed' ),
        __( 'Instances', 'reviews-feed' ),
        __( 'Actions', 'reviews-feed' )
    ];

    /**
     * "Used in N places", with the hover list behind it. A post-content scan, so
     * the count is a floor — a theme template, a page builder or an email placement
     * is not found. Hence "used in", never "only used in".
     */
    const instancesCell = ( badge ) => {
        const count = badge.instances?.count || 0;
        const items = badge.instances?.items || [];

        // Older payloads carry no status; absent reads as 'ok', which is the
        // behaviour before SMASH-2117. A failed scan and an unplaced badge both
        // come back with no rows, and only one of them licenses a zero here —
        // this cell sits next to the delete button that acts on it.
        if ( badge.instances?.status === 'unknown' ) {
            return (
                <span className="sb-dark2-text sb-relative">
                    { __( "Couldn't check", 'reviews-feed' ) }
                    {
                        // Left on the helper's default, which joins the words with
                        // &nbsp;. Review read that as "cannot wrap out of the cell";
                        // measured on the rendered page it is the opposite — the
                        // tooltip is absolutely positioned, so it escapes the cell and
                        // sizes to its content: 272x27 on one line. Turning the default
                        // off gives it no width to size to and it collapses to 59x162,
                        // a column one word wide.
                        SbUtils.printTooltip(
                            __( 'The check did not finish. Reload to try again.', 'reviews-feed' )
                        )
                    }
                </span>
            );
        }

        const places = sprintf(
            _n( '%d place', '%d places', count, 'reviews-feed' ),
            count
        );

        if ( count === 0 ) {
            // Only the count is dimmed, via the shipped .sb-displayed-on-empty
            // (review-alert-settings.css:3391). No tooltip: nothing to list.
            return (
                <span>
                    { __( 'Used in', 'reviews-feed' ) }{ ' ' }
                    <span className="sb-displayed-on-empty">{ places }</span>
                </span>
            );
        }

        return (
            <span>
                { __( 'Used in', 'reviews-feed' ) }{ ' ' }
                <LocationsTooltip
                    trigger={ places }
                    triggerClass="sb-bold"
                    header={ __( 'This badge is used in', 'reviews-feed' ) }
                    headerCount={ places }
                    items={ items }
                    icons={ LocationTypeIcons }
                    ariaLabel={ `${ count } ${ __( 'instances, view list', 'reviews-feed' ) }` }
                />
            </span>
        );
    };

    return (
        <div className="sb-feedslist-ctn sb-fs">
            <div className="sb-feedslist-top">
                <div className="sb-feedslist-bulk-ctn">
                    <Select
                        size="small"
                        customClass="sb-blulk-select"
                        onChange={ ( event ) => setBulkAction( event.currentTarget.value ) }
                    >
                        { Object.keys( bulkActionsList ).map( ( action ) => (
                            <option key={ action } value={ action }>{ bulkActionsList[ action ] }</option>
                        ) ) }
                    </Select>
                    <Button
                        type="secondary"
                        size="small"
                        boxshadow="false"
                        text={ __( 'Apply', 'reviews-feed' ) }
                        onClick={ applyBulkAction }
                    />
                </div>
                <div className="sb-feedslist-pagination">
                    <Pagination
                        currentPage={ currentPage }
                        totalPages={ totalPages }
                        totalItems={ badgesTotal }
                        onPageChange={ loadPage }
                        isLoading={ isLoading }
                    />
                </div>
            </div>

            <div className="sb-feedslist-table-wrap sb-fs">
                <table className="sb-feedslist-table sb-text-tiny">
                    <thead className="sb-feedslist-thtf sb-feedslist-thead sb-dark2-text">
                        <tr>
                            <th>
                                <Checkbox
                                    value={ selected.length === badgesList.length && badgesList.length > 0 }
                                    enabled={ true }
                                    ariaLabel={ __( 'Select all badges', 'reviews-feed' ) }
                                    onChange={ () => toggleSelected( 'all' ) }
                                />
                            </th>
                            { columns.map( ( label, i ) => (
                                <th key={ label } className={ i === columns.length - 1 ? 'cff-fd-lst-act-th' : undefined }>
                                    <span>{ label }</span>
                                </th>
                            ) ) }
                        </tr>
                    </thead>

                    <tbody className="sb-feedslist-tbody">
                        { badgesList.map( ( badge ) => (
                            <tr key={ badge.id }>
                                <td>
                                    <Checkbox
                                        value={ selected.includes( badge.id ) }
                                        enabled={ true }
                                        ariaLabel={ `${ __( 'Select badge', 'reviews-feed' ) }: ${ badge.name }` }
                                        onChange={ () => toggleSelected( badge.id ) }
                                    />
                                </td>
                                <td className="sb-feedslist-name-ctn">
                                    <a className="sb-text-small" href={ editUrl( badge.id ) }>
                                        { badge.name || __( 'Untitled Badge', 'reviews-feed' ) }
                                    </a>
                                    <span>{ subtitle( badge ) }</span>
                                </td>
                                <td className="sb-badge-shortcode-ctn">
                                    <code className="sb-badge-shortcode">{ shortcodeFor( 'badge', badge.id ) }</code>
                                    <div className="sb-relative">
                                        <Button
                                            type="secondary"
                                            size="small"
                                            iconSize="11"
                                            boxshadow={ false }
                                            icon="duplicate"
                                            ariaLabel={ __( 'Copy shortcode', 'reviews-feed' ) }
                                            tooltip={ copiedId === badge.id ? __( 'Copied', 'reviews-feed' ) : __( 'Copy', 'reviews-feed' ) }
                                            onClick={ () => copyShortcode( badge ) }
                                            customClass="sb-feed-action-btn"
                                        />
                                    </div>
                                </td>
                                <td>{ instancesCell( badge ) }</td>
                                <td className="sb-feed-item-actions">
                                    <div className="sb-feed-item-btns">
                                        <div className="sb-relative">
                                            <Button
                                                type="secondary"
                                                size="small"
                                                iconSize="14"
                                                boxshadow={ false }
                                                icon="pen"
                                                ariaLabel={ __( 'Edit badge', 'reviews-feed' ) }
                                                tooltip={ __( 'Edit', 'reviews-feed' ) }
                                                onClick={ () => {
                                                    window.location.href = editUrl( badge.id );
                                                } }
                                                customClass="sb-feed-action-btn sb-feed-edit-btn"
                                            />
                                        </div>
                                        <div className="sb-relative">
                                            <Button
                                                type="secondary"
                                                size="small"
                                                iconSize="11"
                                                boxshadow={ false }
                                                icon="duplicate"
                                                ariaLabel={ __( 'Duplicate badge', 'reviews-feed' ) }
                                                tooltip={ __( 'Duplicate', 'reviews-feed' ) }
                                                onClick={ () => handleDuplicate( badge ) }
                                                customClass="sb-feed-action-btn sb-feed-duplicate-btn"
                                            />
                                        </div>
                                        <div className="sb-relative">
                                            <Button
                                                type="secondary"
                                                size="small"
                                                iconSize="11"
                                                boxshadow={ false }
                                                icon="trash"
                                                ariaLabel={ __( 'Delete badge', 'reviews-feed' ) }
                                                tooltip={ __( 'Delete', 'reviews-feed' ) }
                                                onClick={ () => confirmDelete( [ badge.id ], badge ) }
                                                customClass="sb-feed-action-btn sb-feed-delete-btn"
                                            />
                                        </div>
                                    </div>
                                </td>
                            </tr>
                        ) ) }
                    </tbody>

                    <tfoot className="sb-feedslist-thtf sb-feedslist-tfoot sb-dark2-text">
                        <tr>
                            <th>
                                <Checkbox
                                    value={ selected.length === badgesList.length && badgesList.length > 0 }
                                    enabled={ true }
                                    ariaLabel={ __( 'Select all badges', 'reviews-feed' ) }
                                    onChange={ () => toggleSelected( 'all' ) }
                                />
                            </th>
                            { columns.map( ( label, i ) => (
                                <th key={ label } className={ i === columns.length - 1 ? 'cff-fd-lst-act-th' : undefined }>
                                    <span className="sb-text-tiny sb-dark2-text">{ label }</span>
                                </th>
                            ) ) }
                        </tr>
                    </tfoot>
                </table>

                {/* Bottom Pagination — the sibling shell has one and the design's
                    list shows the item count under the table as well as over it. */}
                <div className="sb-feedslist-bottom">
                    <div className="sb-feedslist-pagination sb-feedslist-pagination-bottom">
                        <Pagination
                            currentPage={ currentPage }
                            totalPages={ totalPages }
                            totalItems={ badgesTotal }
                            onPageChange={ loadPage }
                            isLoading={ isLoading }
                        />
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TrustBadgesList;
