import { useState } from "react";
import SbUtils from '../../../Utils/SbUtils'
import SingleControl from './SingleControl'
import ListControl from './ListControl'
import { AccordionRoot, AccordionItem, AccordionTrigger, AccordionContent } from '../../../a11y'


const GroupControl = ( { group, groupInd,  editorActiveSection, editorFeedSettings } ) => {

    const [ groupMinimized, setGroupMinimized ] = useState( group?.minimized ? group.minimized : false )

    const attrList = [
        'dimmed'
    ];

    // Radix Accordion needs a string "value" for the open item; adapt at the
    // binding only so the existing groupMinimized boolean state is preserved.
    const ITEM_VALUE = 'group';
    const accordionValue = groupMinimized ? '' : ITEM_VALUE;
    const handleValueChange = ( nextValue ) => {
        setGroupMinimized( nextValue !== ITEM_VALUE );
    };

    return (
        <AccordionRoot
            type="single"
            collapsible
            value={ accordionValue }
            onValueChange={ handleValueChange }
            asChild
        >
            <AccordionItem value={ ITEM_VALUE } asChild>
                <div
                    className='sb-group-ctn sb-fs'
                    data-minimized={ groupMinimized }
                    { ...SbUtils.getElementAttributes( group, attrList ) }
                >
                    <AccordionTrigger asChild>
                        <div
                            className='sb-group-heading sb-text-small sb-bold sb-fs'
                            role='button'
                            tabIndex={ 0 }
                            // a11y (SMASH-1377): Radix's AccordionTrigger relies on a
                            // native <button> for focus + Enter/Space activation. We
                            // slot a <div> here (block-level icon child can't live in a
                            // <button>), so the div needs an explicit role/tabIndex and
                            // a keydown shim that fires the click Radix listens for.
                            onKeyDown={ ( event ) => {
                                if ( event.target !== event.currentTarget ) {
                                    return;
                                }
                                if ( event.key === 'Enter' || event.key === ' ' ) {
                                    event.preventDefault();
                                    event.currentTarget.click();
                                }
                            } }
                        >
                            {
                                group.icon &&
                                <div className='sb-group-heading-icon'> { SbUtils.printIcon( group.icon ) } </div>
                            }
                            {group.heading}
                            { SbUtils.printIcon( 'chevron-bottom', 'sb-customizer-sec-el-chevron' ) }
                        </div>
                    </AccordionTrigger>
                    <AccordionContent asChild forceMount>
                        <div className='sb-group-controls-list sb-fs'>
                            {
                                group.controls.map( ( element, elementInd ) => {

                                    let showElement = SbUtils.checkControlCondition( element, editorFeedSettings.feedSettings );
                                    element.dimmed = showElement === 'dimmed' ? true : null;

                                    if( element.type === 'list'  && showElement !== false ){
                                        /** Render List control*/
                                        return (
                                            <ListControl
                                                key={ elementInd }
                                                list={ element }
                                                listInd={ elementInd }
                                                fullspace={ element.fullspace }
                                            />
                                        );
                                    }else{
                                        if( showElement !== false ){
                                            /** Render normal control*/
                                            return (
                                                <SingleControl
                                                    key={ elementInd }
                                                    control={ element }
                                                    controlInd={ elementInd }
                                                />
                                            );
                                        }
                                    }
                                })
                            }
                        </div>
                    </AccordionContent>
                </div>
            </AccordionItem>
        </AccordionRoot>
    )

}

export default GroupControl;
