import { Fragment, useEffect, useMemo, useRef, useState, useId } from 'react';
import { __ } from '@wordpress/i18n';
import LocationTypeIcons from '../LocationTypeIcons';

/**
 * "Search for a page or a post" combo box. Three states in one control, which is
 * why it is a component and not an input plus a list:
 *
 * - searching — magnifier, text field, grouped result list
 * - picked    — type icon, title, status pill, clear button
 * - creating  — a title field for a page that does not exist yet
 *
 * Rows arrive grouped and ordered from SBR_Embed_Targets, so nothing here decides
 * what a "Page" or a "Product" is.
 *
 * The list is a listbox: ArrowUp/Down move the highlight, Enter takes it, Escape
 * closes. Without that the control is mouse-only.
 */

/** Icons for the picker's own furniture, at the design's sizes. */
const SEARCH_ICON = (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">
        <path d="M15.5 14h-.79l-.28-.27A6.47 6.47 0 0 0 16 9.5 6.5 6.5 0 1 0 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14" />
    </svg>
);

const CLOSE_ICON = (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">
        <path d="M19 6.41 17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" />
    </svg>
);

const ADD_ICON = (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">
        <path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8zm2 14h-3v3h-2v-3H8v-2h3v-3h2v3h3z" />
    </svg>
);

const EmbedTargetPicker = ( {
    targets = [],
    value = null,
    onChange,
    onCreate,
    onDraftChange,
    // Defaults OFF, matching EmbedModal's own default for the same flag. The two
    // disagreed, and it was the primitive that defaulted the affordance on — so a
    // consumer importing this directly got a create row with no `onCreate`, where
    // `onCreate?.()` means the row opens and Enter silently does nothing.
    allowCreate = false,
    // Whether the record being embedded exists on the site yet. The parent gates its
    // CTA on this (EmbedModal.js) because creating a page before the record is saved
    // sends an empty wizard id and the page lands with nothing embedded. This
    // component has its own Enter-to-create path, so it needs the same gate — one
    // guarded trigger and one unguarded trigger for the same action is the bug.
    // Defaults true so existing consumers keep their behaviour.
    saved = true,
} ) => {
    const [ query, setQuery ] = useState( '' );
    const [ open, setOpen ] = useState( false );
    const [ highlight, setHighlight ] = useState( 0 );
    const [ creating, setCreating ] = useState( false );
    const [ newTitle, setNewTitle ] = useState( '' );
    const wrapRef = useRef( null );

    // Generated, not the literal "sb-embed-results" this replaces: two pickers on
    // one page shared the id, so the second combobox's aria-controls pointed at the
    // first one's listbox.
    const listboxId = useId();

    /** The create row is an option in the listbox too, so it needs an id. */
    const createOptionId = `${ listboxId }-create`;

    // This state's submit control is the modal's own CTA, which relabels to
    // "Create Page and Go" — it lives outside this component, so it has to be told.
    //
    // Through a ref, and `onDraftChange` out of the dependency array: a caller
    // passing an inline arrow gave a new identity every render, so the effect fired
    // every render and told the modal about a draft that had not changed. The ref
    // keeps the newest callback without making the effect depend on its identity.
    const draftChangeRef = useRef( onDraftChange );
    draftChangeRef.current = onDraftChange;

    useEffect( () => {
        draftChangeRef.current?.( { creating, title: newTitle } );
    }, [ creating, newTitle ] );

    const matches = useMemo( () => {
        const q = query.trim().toLowerCase();

        if ( q === '' ) {
            return targets;
        }

        // `t?.title ?? ''`: a null title (a DB row with none, or the older
        // wordpressPageLists shape) threw and killed the whole search rather than
        // dropping one row. Every other field in this component is already guarded.
        return targets.filter( ( t ) => String( t?.title ?? '' ).toLowerCase().includes( q ) );
    }, [ targets, query ] );

    // Re-clamped when the list shrinks under an open combobox — an async refresh of
    // `targets` leaves `highlight` past the end otherwise. Enter is already guarded
    // (`highlight < matches.length`), so this is not a crash; the symptom is Enter
    // silently taking the "create page" branch instead of picking a result.
    useEffect( () => {
        setHighlight( ( prev ) => Math.min( prev, Math.max( 0, matches.length - 1 ) ) );
    }, [ matches.length ] );

    // The group boundary is derived here rather than tracked by a variable mutated
    // inside the .map() callback. That worked — .map() is synchronous and ordered —
    // but it made the render function impure, and a reviewer's point stands: it is
    // the kind of thing a later memoisation quietly breaks, and the breakage would
    // be a missing or duplicated header rather than an error.
    //
    // Truthiness, not inequality against a seed: the BC wordpressPageLists shape
    // carries no `group`, and `undefined !== null` drew an empty header.
    // Memoised alongside `matches`, which it derives from: this rebuilt on every
    // render of the searching branch even though its input was already stable.
    // Inconsequential for a page/post result list, free to fix — review on #192.
    const rows = useMemo( () => matches.map( ( target, index ) => ( {
        target,
        index,
        // Falls back to the row's position. The BC wordpressPageLists shape can
        // arrive without `type`, and a partial row without `id` — either way every
        // such row collapsed onto `undefined-undefined`, so React saw one key for
        // many rows and aria-activedescendant named whichever rendered last.
        rowKey: target.type != null && target.id != null // eslint-disable-line eqeqeq
            ? `${ target.type }-${ target.id }`
            : `row-${ index }`,
        header: target.group && target.group !== matches[ index - 1 ]?.group
            ? target.group
            : null,
    } ) ), [ matches ] );


    // Close on an outside click. A combo whose list survives a click elsewhere
    // covers the section under it and looks stuck.
    useEffect( () => {
        if ( ! open ) {
            return undefined;
        }

        const onDown = ( event ) => {
            if ( wrapRef.current && ! wrapRef.current.contains( event.target ) ) {
                setOpen( false );
            }
        };

        document.addEventListener( 'mousedown', onDown );

        return () => document.removeEventListener( 'mousedown', onDown );
    }, [ open ] );

    const pick = ( target ) => {
        onChange?.( target );
        setOpen( false );
        setQuery( '' );
    };

    const onKeyDown = ( event ) => {
        if ( event.key === 'Escape' ) {
            setOpen( false );
            return;
        }

        if ( event.key === 'ArrowDown' || event.key === 'ArrowUp' ) {
            event.preventDefault();
            setOpen( true );

            // `saved` too, or ArrowDown lands on the create row's index while the
            // row itself is not rendered, and aria-activedescendant below then names
            // an element that is not in the DOM.
            const last = matches.length - ( allowCreate && saved ? 0 : 1 );
            setHighlight( ( prev ) => {
                const next = event.key === 'ArrowDown' ? prev + 1 : prev - 1;
                return Math.max( 0, Math.min( next, last ) );
            } );

            return;
        }

        if ( event.key === 'Enter' ) {
            event.preventDefault();

            if ( highlight < matches.length ) {
                pick( matches[ highlight ] );
            } else if ( allowCreate && saved ) {
                setCreating( true );
                setNewTitle( query );
            }
        }
    };

    // Picked: show what was chosen, with a way back.
    if ( value && ! creating ) {
        return (
            <div className="sb-embed-combo" ref={ wrapRef }>
                <div className="sb-embed-field">
                    <span className="sb-embed-field-ico">
                        { LocationTypeIcons[ value.icon ] || LocationTypeIcons.page }
                    </span>
                    <span className="sb-embed-picked">
                        <span className="nm">{ value.title }</span>
                        { value.statusLabel
                            ? <span className={ `sb-embed-pill ${ value.status }` }>{ value.statusLabel }</span>
                            : null }
                    </span>
                    <button
                        type="button"
                        className="sb-embed-field-x"
                        onClick={ () => onChange?.( null ) }
                        aria-label={ __( 'Choose a different page', 'reviews-feed' ) }
                    >
                        { CLOSE_ICON }
                    </button>
                </div>
            </div>
        );
    }

    // Creating: a title for a page that does not exist yet.
    if ( creating ) {
        return (
            <div className="sb-embed-combo" ref={ wrapRef }>
                <div className="sb-embed-field">
                    <span className="sb-embed-field-ico">{ ADD_ICON }</span>
                    <input
                        type="text"
                        value={ newTitle }
                        onChange={ ( e ) => setNewTitle( e.target.value ) }
                        placeholder={ __( 'Page title', 'reviews-feed' ) }
                        autoComplete="off"
                        spellCheck="false"
                        aria-label={ __( 'New page title', 'reviews-feed' ) }
                        onKeyDown={ ( e ) => {
                            if ( e.key !== 'Enter' ) {
                                return;
                            }

                            // preventDefault before the bail: Enter in a field inside
                            // a form would submit it, and bailing first let that happen.
                            e.preventDefault();

                            if ( ! saved || newTitle.trim() === '' ) {
                                return;
                            }

                            // Guarded because onCreate is optional: allowCreate can be
                            // turned on by a consumer that never wires the handler.
                            // (This said "allowCreate defaults to true" until
                            // 2026-09-09; it defaults to FALSE, and had done since
                            // earlier in this PR — the comment was simply stale.)
                            onCreate?.( newTitle.trim() );
                        } }
                    />
                    <button
                        type="button"
                        className="sb-embed-field-x"
                        onClick={ () => { setCreating( false ); setNewTitle( '' ); } }
                        aria-label={ __( 'Cancel and search instead', 'reviews-feed' ) }
                    >
                        { CLOSE_ICON }
                    </button>
                </div>
            </div>
        );
    }

    // Searching.
    //

    return (
        <div className="sb-embed-combo" ref={ wrapRef }>
            <div className="sb-embed-field">
                <span className="sb-embed-field-ico">{ SEARCH_ICON }</span>
                <input
                    type="text"
                    value={ query }
                    onChange={ ( e ) => { setQuery( e.target.value ); setOpen( true ); setHighlight( 0 ); } }
                    onFocus={ () => setOpen( true ) }
                    onKeyDown={ onKeyDown }
                    placeholder={ __( 'Search for a page or a post', 'reviews-feed' ) }
                    autoComplete="off"
                    spellCheck="false"
                    role="combobox"
                    aria-expanded={ open }
                    /* The combobox pattern expects this alongside aria-expanded
                       and aria-controls: it tells assistive tech the suggestions
                       are a list rather than inline completion. */
                    aria-autocomplete="list"
                    /* Only while the listbox exists. aria-activedescendant was
                       already gated this way after an earlier round; aria-controls
                       was not, so it named an element that is not in the DOM
                       whenever the list is closed. */
                    aria-controls={ open ? listboxId : undefined }
                    /* Which option the arrow keys are on. Without it the
                       highlight is a visual state only — a screen reader
                       following the combobox is told nothing as it moves. */
                    aria-activedescendant={
                        ( () => {
                            if ( ! open ) {
                                return undefined;
                            }

                            // From rows[…].rowKey, the same value the option's id
                            // is built from. Rebuilding it here from type/id would
                            // diverge for a row that fell back to its index —
                            // exactly the malformed rows the fallback exists for, so
                            // the ARIA reference would break precisely where it
                            // matters most.
                            if ( rows[ highlight ] ) {
                                return `sb-embed-opt-${ rows[ highlight ].rowKey }`;
                            }

                            // Arrowing past the last result lands on the create row.
                            // It used to resolve to undefined here, so the one state
                            // this attribute exists for — being told which row you
                            // are on — went silent at the end of the list.
                            return allowCreate && saved && highlight >= matches.length ? createOptionId : undefined;
                        } )()
                    }
                />
            </div>

            { open && (
                <div className="sb-embed-results" id={ listboxId } role="listbox">
                    { matches.length === 0 && (
                        <div className="sb-embed-none">
                            { query.trim() !== ''
                                ? __( 'Nothing matched that search.', 'reviews-feed' )
                                : __( 'No pages or posts yet.', 'reviews-feed' ) }
                        </div>
                    ) }

                    { rows.map( ( { target, index, header: groupName, rowKey } ) => {
                        const header = groupName
                            ? (
                                /* presentation, so a heading between options does
                                   not read as one of them. */
                                <div className="sb-embed-grp" role="presentation" key={ `g-${ groupName }` }>
                                    { groupName }
                                </div>
                            )
                            : null;

                        return (
                            /* A Fragment, not a div: a node between the listbox
                               and its options breaks the relationship the role
                               depends on. */
                            <Fragment key={ rowKey }>
                                { header }
                                <button
                                    type="button"
                                    id={ `sb-embed-opt-${ rowKey }` }
                                    className={ `sb-embed-opt ${ index === highlight ? 'hi' : '' }` }
                                    role="option"
                                    aria-selected={ index === highlight }
                                    onMouseEnter={ () => setHighlight( index ) }
                                    onClick={ () => pick( target ) }
                                >
                                    <span className="oi">
                                        { LocationTypeIcons[ target.icon ] || LocationTypeIcons.page }
                                    </span>
                                    <span className="nm">{ target.title }</span>
                                    { target.statusLabel
                                        ? <span className={ `sb-embed-pill ${ target.status }` }>{ target.statusLabel }</span>
                                        : null }
                                </button>
                            </Fragment>
                        );
                    } ) }

                    { allowCreate && saved && (
                        <button
                            type="button"
                            id={ createOptionId }
                            role="option"
                            aria-selected={ highlight >= matches.length }
                            className={ `sb-embed-create ${ highlight >= matches.length ? 'hi' : '' }` }
                            onClick={ () => { setCreating( true ); setNewTitle( query ); } }
                        >
                            { ADD_ICON }
                            <span className="lb">
                                { query.trim() !== ''
                                    ? <>{ __( 'Create page', 'reviews-feed' ) } <b>{ query.trim() }</b></>
                                    : __( 'Create a new page', 'reviews-feed' ) }
                            </span>
                        </button>
                    ) }
                </div>
            ) }
        </div>
    );
};

export default EmbedTargetPicker;
