import { __ } from "@wordpress/i18n";

const TopNoticeBar = ( props ) => {
    return (
        props?.active &&
        <div
            className="sb-noticebar-ctn"
            data-type={ props?.type ? props?.type : 'default' }
        >
            <span className="sb-noticebar-heading">
                { props?.heading }
                {
                    props?.actionsList &&
                    props?.actionsList.map((act, actKey) => {
                        return (
                            <button
                                type="button"
                                key={actKey}
                                className="sb-noticebar-action sb-button-reset"
                                data-style={act?.style ?? 'default'}
                                onClick={ () => {
                                    if (act?.onClick === 'openAddApiKeyModal') {
                                        props?.openAddApiKeyModal(act?.provider)
                                    } else{
                                        if (act?.onClick){
                                            act?.onClick()
                                        }
                                    }
                                }}
                           >
                             {act?.text}
                            </button>
                        )
                    })
                }

                {
                    props?.actionText &&
                    <button
                        type="button"
                        className="sb-button-reset sb-bold"
                        onClick={ () => {
                            props?.actionClick &&
                                props?.actionClick()
                        }}
                    >
                        {props?.actionText}
                    </button>
                }
            </span>
            {
                (props?.close !== false || props?.close === undefined) &&
                <button
                    type="button"
                    className='sb-cls-ctn sb-modal-cls sb-button-reset'
                    aria-label={ __( 'Dismiss notice', 'sb-customizer' ) }
                    onClick={ () => {
                        props?.onClose &&
                            props.onClose()
                    }}
                >
                </button>
            }

        </div>
    )
}

export default TopNoticeBar;