import { __ } from "@wordpress/i18n";
import Button from "../../../Common/Button";
import FeatureEmptyState from "../../../Common/FeatureEmptyState";
import SbUtils from "../../../../Utils/SbUtils";
import { useContext, useMemo, useState } from "react";
import ModalContainer from "../../../Global/ModalContainer";
import CreateCollectionModal from "../../../Modals/CreateCollectionModal";
import CollectionEmpty from "./Single/CollectionEmpty";
import Pagination from "../../../Common/Pagination";

/**
 * Fallback page size, for a bundle served by a plugin build from before
 * `collectionsPerPage` was sent. Matches DB::COLLECTIONS_PER_PAGE.
 */
const DEFAULT_PER_PAGE = 20;

const CollectionsList = () => {
    const currentContext = SbUtils.getCurrentContext();
    const {
        sbCustomizer,
        slSection,
        sources,
        curCl,
        editorTopLoader,
        editorNotification,
        collectionP,
        getCollectionReviewsList,
        editorConfirmDialog,
        currentForms
    } = useContext( currentContext );

    const [ collectionNamePopup, setCollectionNamePopup ] = useState( false );
    const [ collectionInfoPopup, setCollectionInfoPopup ] = useState( false );


    // SMASH-1599: seeded from the server's FIRST PAGE OF COLLECTIONS, not from
    // filtering `sourcesList`. That list is one page of 20 rows across every
    // provider, so filtering it showed however many of a site's first 20 sources
    // happened to be collections — 15 on the reporting site — with no way to
    // reach the rest. The filter stays only as a fallback for a bundle served by
    // a plugin build from before `collectionsList` was sent.
    const initialCollections = Array.isArray( sbCustomizer?.collectionsList )
        ? sbCustomizer.collectionsList
        : ( sources?.sourcesList || [] ).filter( s => s.provider === 'collection' );

    const [ collectionsList, setCollectionsList ] = useState( initialCollections );
    // Falls back to the LIST's own length, not 0. Both values go missing
    // together — they come from the same payload — so a 0 here put "0 Items"
    // above a list with rows in it. `loadPage`'s fallback branch already derived
    // the total from the rows it rendered; this is the same rule at the seed,
    // which is the half that was missed.
    const [ collectionsTotal, setCollectionsTotal ] = useState(
        Number.isFinite( Number( sbCustomizer?.collectionsCount ) )
            ? Number( sbCustomizer.collectionsCount )
            : initialCollections.length
    );
    const [ currentPage, setCurrentPage ] = useState( 1 );
    const [ isLoading, setIsLoading ] = useState( false );

    // Sent by the server (DB::COLLECTIONS_PER_PAGE), not repeated here — a second
    // copy of the number is how a pager ends up disagreeing with its own rows.
    // Clamped on the FLOORED value: anything in (0,1) is > 0 but floors to 0, and
    // `Math.ceil( total / 0 )` is Infinity, which renders a pager forever.
    // (Both traps are the ones TrustBadgesList hit; inherited rather than re-found.)
    const rawPerPage = Number( sbCustomizer?.collectionsPerPage );
    const perPage = Number.isFinite( rawPerPage ) && Math.floor( rawPerPage ) >= 1
        ? Math.floor( rawPerPage )
        : DEFAULT_PER_PAGE;
    const totalPages = Math.max( 1, Math.ceil( ( collectionsTotal || 0 ) / perPage ) );

    const collections =  useMemo(
        () => ({ collectionsList, setCollectionsList }),
		[collectionsList, setCollectionsList]
    );

    /**
     * Load one page of collections.
     *
     * @param {number} page            1-based page number.
     * @param {Array}  [fallbackSources] A `sourcesList` from the response of
     *        whatever action triggered this, used only when the paging route is
     *        not available. See the comment below.
     *
     * @return {void}
     */
    const loadPage = ( page, fallbackSources = null ) => {
        const wanted = Math.max( 1, page );
        setIsLoading( true );

        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            {
                action : 'sbr_feed_saver_manager_load_more_collections',
                collections_page : wanted
            },
            ( data ) => {
                setIsLoading( false );

                if ( ! Array.isArray( data?.collectionsList ) ) {
                    // A bundle newer than the plugin serving it: the action is
                    // unregistered, admin-ajax answers the bare string `0`, and
                    // `0 === false` is strict-false so ajaxPost raises nothing
                    // either. Without this branch the list simply never changed
                    // after a create, delete or duplicate — the row stayed on
                    // screen and nothing said why. Degrade to the pre-SMASH-1599
                    // behaviour rather than to silence.
                    if ( Array.isArray( fallbackSources ) ) {
                        const derived = fallbackSources.filter( s => s.provider === 'collection' );
                        setCollectionsList( derived );
                        setCollectionsTotal( derived.length );
                        setCurrentPage( 1 );
                    }
                    return;
                }

                const count = Number( data.collectionsCount ) || 0;

                // Deleting the last rows of the last page leaves `wanted` past
                // the end, and the screen would draw the "you have no
                // collections" splash at someone with fifty. Jump straight to
                // the last real page rather than walking back a page per round
                // trip, which is what TrustBadgesList does.
                //
                // Gated on `count > 0` as well: an empty answer for a page that
                // still has rows is a failed request, not a short page, and
                // stepping back on it would move someone off a page that was
                // fine.
                const lastPage = Math.max( 1, Math.ceil( count / perPage ) );
                if ( count > 0 && data.collectionsList.length === 0 && wanted > lastPage ) {
                    loadPage( lastPage );
                    return;
                }

                setCollectionsList( data.collectionsList );
                setCollectionsTotal( count );
                setCurrentPage( wanted );
            },
            editorTopLoader,
            editorNotification,
            null
        );
    };

    const createNewCollection  = (collectionName = '') => {
        if (SbUtils.checkNotEmpty(collectionName)) {
            const formData = {
                action : 'sbr_feed_saver_manager_create_new_collection',
                collection_name : collectionName
            },
            notificationsContent = {
                success : {
                    icon : 'success',
                    text : __( 'New Collection created successfully', 'reviews-feed' )
                }
            }

            SbUtils.ajaxPost(
                sbCustomizer.ajaxHandler,
                formData,
                ( data ) => { //Call Back Function
                    setCollectionNamePopup(false)
                    sources.setSourcesList(data?.sourcesList)
                    // The new collection changes the count and the page
                    // boundaries, and the response only carries a page of
                    // SOURCES. Re-read page one rather than derive from it.
                    loadPage(1, data?.sourcesList)
                    curCl.setCurrentCollection(data?.newCollection)
                    setTimeout(function(){
                        slSection.setCollectionSectionActive('single')
                    }, 200)
                },
                editorTopLoader,
                editorNotification,
                notificationsContent
            )
        }
    }


    const deleteCollection = ( collection ) => {
        const confirmDialogInfo = {
                active : true,
                heading : `${ __('Delete ', 'reviews-feed') + '"'+collection.name +'"?'  }`,
                description : __( 'By deleting this collection, all the reviews created and added for it will be deleted too', 'reviews-feed' ),
                confirm : {}
        },
        notificationsContent = {
            success : {
                icon : 'success',
                text : __( 'Collection Deleted!', 'reviews-feed' )
            }
        };

        confirmDialogInfo.confirm.onConfirm = () => {
            const formData = {
                action : 'sbr_feed_saver_manager_delete_source',
                sourceID : collection.id,
                sourceAccountID : collection.account_id,
                sourceProvider : collection.provider,
                isCollection : true
            }
            SbUtils.ajaxPost(
                sbCustomizer.ajaxHandler,
                formData,
                ( data ) => { //Call Back Function
                    sources.setSourcesList( data.sourcesList )
                    // Not `data.sourcesList.filter(...)` — that is one page of
                    // all providers and re-deriving from it is the bug being
                    // fixed. Re-read the page we are actually on.
                    loadPage( currentPage, data?.sourcesList )
                },
                editorTopLoader,
                editorNotification,
                notificationsContent
            )
        }
        editorConfirmDialog.setConfirmDialog( confirmDialogInfo )

    }


    const duplicateCollection = ( collection ) => {

         const confirmDialogInfo = {
                active : true,
                heading : `${ __('Duplicate ', 'reviews-feed') + '"'+collection.name +'"?'  }`,
                description : __( 'By duplicating this collection, all the reviews created and added to this collection will be duplicated too!', 'reviews-feed' ),
                confirm : {
                    type : 'primary',
                    text : __('Duplicate Collection ', 'reviews-feed')
                }
        },
        notificationsContent = {
            success : {
                icon : 'success',
                text : __( 'Collection Duplicated!', 'reviews-feed' )
            }
        };
        confirmDialogInfo.confirm.onConfirm = () => {
            const formData = {
                action : 'sbr_feed_saver_manager_duplicate_collection',
                collection_id : collection.account_id
            }
            SbUtils.ajaxPost(
                sbCustomizer.ajaxHandler,
                formData,
                ( data ) => { //Call Back Function
                    if (data?.sourcesList ){
                        sources.setSourcesList( data.sourcesList )
                    }
                    // A duplicate adds a row, so the page it lands on and the
                    // total both move. Same reason as delete: ask the server.
                    loadPage( currentPage, data?.sourcesList )
                },
                editorTopLoader,
                editorNotification,
                notificationsContent
            )
        }
        editorConfirmDialog.setConfirmDialog( confirmDialogInfo )

    }

	return (
		<>
			<div className='sb-dashboard-heading sb-fs'>
                <h2 className='sb-h2'>{ __( 'All Collections', 'reviews-feed' ) }</h2>
                <div className='sb-dashboard-action-btns'>
                    <Button
                        customClass='sb-dashboard-btn'
                        type='primary'
                        size='small'
                        icon='plus'
                        iconSize='11'
                        text={ __( 'Add New', 'reviews-feed' ) }
                        onClick={ () => {
                            setCollectionNamePopup(true)
                        } }
                    />
                    {
                        collections?.collectionsList.length > 0 &&
                        <button
                            type='button'
                            className='sb-button-reset sb-fs sb-coll-link sb-light-text2 sb-bold'
                            onClick={() => {
                                setCollectionInfoPopup(true)
                            }}
                        >
                            {SbUtils.printIcon('help', '', false, 16)}
                            {__('What are collections?', 'reviews-feed')}
                        </button>
                    }
                </div>
            </div>
            {
                collections.collectionsList.length > 0 &&
                <div className='sb-feedslist-top sb-fs'>
                    <div className='sb-feedslist-pagination'>
                        <Pagination
                            currentPage={ currentPage }
                            totalPages={ totalPages }
                            totalItems={ collectionsTotal }
                            onPageChange={ loadPage }
                            isLoading={ isLoading }
                        />
                    </div>
                </div>
            }

            {
                collections.collectionsList.length > 0 &&
                <div className='sb-collections-ctn sb-fs'>
                    {
                        collections?.collectionsList.map( (collection, ckey) => {
                           return (
                                <div className='sb-collection-item' key={ckey}>
                                    <div className='sb-collection-item-icon'>{ SbUtils.printIcon( 'collection-provider', false, false, 32  ) }</div>
                                    <div className='sb-collection-item-info'>
                                        <div className='sb-collection-item-text'>
                                            <strong className='sb-collection-item-name sb-standard-p'>{collection.name}</strong>
                                            <span className='sb-collection-item-num sb-small-p'>{collection.reviews_number} {collection.reviews_number === 1 ? __( 'Review', 'reviews-feed' ) : __( 'Reviews', 'reviews-feed' )}</span>
                                        </div>
                                        <div className='sb-collection-item-actions sb-tr-2'>
                                            <div className='sb-feed-item-btns'>
                                                <div className='sb-relative'>
                                                    <Button
                                                        type='secondary'
                                                        size='small'
                                                        iconSize='14'
                                                        boxshadow={false}
                                                        icon='pen'
                                                        ariaLabel={ __( 'Edit collection', 'reviews-feed' ) }
                                                        tooltip={ __( 'Edit', 'reviews-feed' ) }
                                                        onClick={ () => {
                                                            curCl.setCurrentCollection(collection)
                                    						currentForms.setCurrentConnectedForms(SbUtils.getCollectionConnectedForms(collection))
                                                            collectionP.setCollectionReviewsPage(1)
                                                            getCollectionReviewsList(collection)
                                                        } }
                                                        customClass='sb-feed-action-btn sb-feed-edit-btn'
                                                    />
                                                </div>
                                                <div className='sb-relative'>
                                                    <Button
                                                        type='secondary'
                                                        size='small'
                                                        iconSize='11'
                                                        boxshadow={false}
                                                        icon='duplicate'
                                                        ariaLabel={ __( 'Duplicate collection', 'reviews-feed' ) }
                                                        tooltip={ __( 'Duplicate', 'reviews-feed' ) }
                                                        onClick={ () => {
                                                            duplicateCollection(collection)
                                                        } }
                                                        customClass='sb-feed-action-btn sb-feed-duplicate-btn'
                                                    />
                                                </div>
                                                <div className='sb-relative'>
                                                    <Button
                                                        type='secondary'
                                                        size='small'
                                                        iconSize='11'
                                                        boxshadow={false}
                                                        icon='trash'
                                                        ariaLabel={ __( 'Delete collection', 'reviews-feed' ) }
                                                        tooltip={ __( 'Delete', 'reviews-feed' ) }
                                                        onClick={ () => {
                                                            deleteCollection(collection)
                                                        } }
                                                        customClass='sb-feed-action-btn sb-feed-delete-btn'
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                           )
                        })
                    }
                </div>
            }

            {
                collections.collectionsList.length > 0 &&
                <div className='sb-feedslist-bottom sb-fs'>
                    <div className='sb-feedslist-pagination sb-feedslist-pagination-bottom'>
                        <Pagination
                            currentPage={ currentPage }
                            totalPages={ totalPages }
                            totalItems={ collectionsTotal }
                            onPageChange={ loadPage }
                            isLoading={ isLoading }
                        />
                    </div>
                </div>
            }

            {
                collections.collectionsList.length === 0 &&
                <FeatureEmptyState
                    imageUrl={ window.sb_customizer.assetsURL + 'sb-customizer/assets/images/collections-splash.svg' }
                    imageAlt={ __( 'Empty Collections Icon', 'reviews-feed' ) }
                    title={ __( 'Showcase your best reviews with collections', 'reviews-feed' ) }
                    description={ __( 'Create collections of handpicked reviews to showcase them on your website, reviews page or product page', 'reviews-feed' ) }
                />
            }
            {
                collectionNamePopup&&
                <ModalContainer
                    size='small'
                    closebutton={true}
                    onClose={ () => {
                        setCollectionNamePopup(false)
                    } }
                >
                    <CreateCollectionModal
                        createNewCollection={(collectionName) => {
                            createNewCollection(collectionName)
                        }}
                        onCancel={ () => {
                            setCollectionNamePopup(false)
                        } }
                    />
                </ModalContainer>
            }
            {
                collectionInfoPopup &&
                <ModalContainer
                    size='medium'
                    type='collections-info'
                    closebutton={true}
                    onClose={ () => {
                        setCollectionInfoPopup(false)
                    } }
                >
                    <>
                        <div className='sb-collections-inf-modal-top sb-fs'>
                            <h4 className='sb-h4'>{ __('What are collections?', 'reviews-feed') }</h4>
                        </div>
                        <CollectionEmpty
                            modal={true}
                        />
                        <div className='sb-collections-inf-modal-bottom sb-fs'>
                            <Button
                                type='primary'
                                size='small'
                                icon='success'
                                iconSize='11'
                                text={ __( 'Okay, got it', 'reviews-feed' ) }
                                onClick={ () => {
                                    setCollectionInfoPopup(false)
                                } }
                            />
                        </div>
                    </>
                </ModalContainer>
            }
		</>
	)

}

export default CollectionsList;
