// Inputs that carry a TripAdvisor location id: the "-d<digits>" listing token (any
// length), a bare id, or a numeric last path segment (SMASH-1706).
const isResolvableTripAdvisorInput = ( input ) => /-d\d+/i.test( input ) || /(?:^|\/)\d+$/.test( input );

// Per-provider URL patterns to catch BEFORE the network round-trip, with a
// specific "why this URL isn't supported" message. Extend by adding a row.
// Module-scoped so the array is allocated once per module load, not per render.
// Each row: { provider, test: (rawInput) => bool, getMessage: () => translated string }
// getMessage is a thunk so __() is evaluated at render time (when translations
// are guaranteed loaded), not at module-eval time.
const UNSUPPORTED_URL_PATTERNS = [
    {
        provider : 'tripadvisor',
        // AttractionProductReview URLs are Viator tours/experiences, which
        // TripAdvisor's Content API does not expose. See SMASH-1294.
        // If TripAdvisor ever publishes Viator via Content API, delete this row.
        test       : ( input ) => /\/AttractionProductReview-/i.test( input ),
        getMessage : () => __(
            'This TripAdvisor URL is for a tour or experience (Viator), which isn\'t available through TripAdvisor\'s public API. Please paste a URL for a <strong>hotel</strong>, <strong>restaurant</strong>, or <strong>attraction</strong> instead. Example: <a href="https://www.tripadvisor.com/Hotel_Review-g60763-d93437-Reviews-Hotel_Plaza_Athenee-New_York_City_New_York.html" target="_blank" rel="noopener noreferrer">Hotel_Review-…</a>',
            'sb-customizer'
        ),
    },
    {
        provider : 'tripadvisor',
        // A member profile, not a business. Listed before the geo row and checked before
        // checkValidIDUrl(): a handle can itself contain "-d<digits>".
        test       : ( input ) => /\/Profile\//i.test( input ),
        getMessage : () => __(
            'This TripAdvisor link is a member profile, not a business. Open the business on TripAdvisor and copy the URL of its own page.',
            'sb-customizer'
        ),
    },
    {
        provider : 'tripadvisor',
        // Tourism-g… / Attractions-g… / Restaurants-g… / Hotels-g…: a geo id names a
        // place, not a listing, so there is nothing to resolve (SMASH-1706).
        test       : ( input ) => ! isResolvableTripAdvisorInput( input ) && /-g\d+/i.test( input ),
        getMessage : () => __(
            'This TripAdvisor link is a category page (a destination or a list of places), not a single listing. Open the individual business and copy the URL of its own page.',
            'sb-customizer'
        ),
    },
];

const findUnsupportedUrlMatch = ( provider, input ) =>
    UNSUPPORTED_URL_PATTERNS.find( ( p ) => p.provider === provider && p.test( input ) );

