    const [ providerIdUrl, setProviderIdUrl ] = useState( '' );
    const [ inputError, setInputError ] = useState( null ); //Will serve in case of adding Invalid API key or Wrong Place/Location URL/ID

    const [ selectedFBPages , setSelectedFBPages ] = useState( [ ] );

    // SMASH-1409 — guard against the double-click duplicate-source bug. The
    // Finish button on the last step of the add-source flow fires an AJAX
    // POST that creates a row in `wp_sbr_sources`. Without this gate, a
    // rapid double-click (or Enter pressed twice) fires the request twice
    // and the customizer renders the source twice in the list before the
    // backend dedup catches up. The `ref` is the synchronous guard (state
    // updates are async — two fast clicks can both pass a state-only check
