import { __ } from '@wordpress/i18n'
import SbUtils from '../../../Utils/SbUtils'
import PostAuthor from './PostAuthor'
import PostRating from './PostRating'
import PostMedia from './PostMedia'
import PostText from './PostText'

// Slugify a value for safe use inside a CSS class token. Strips characters
// other than `[a-z0-9_-]`, lowercases, collapses repeats, trims dashes —
// prevents class-token splitting (`wordpress.org` → `wordpress org` which
// would introduce a spurious `.org` class) and invalid CSS identifiers.
export const slugifyForClass = ( value ) =>
    String(value ?? '')
        .toLowerCase()
        .replace(/[^a-z0-9_-]+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '');

const SinglePost = ( { post, postIndex, feedSettings, isPro } ) => {
    // SMASH-782 Phase 2 — mirror FeedDisplay::item_classes() so the customizer
    // preview applies the same per-provider CSS rules the frontend uses.
    // Specifically: `.sbr-provider-{name}` enables the per-provider scoping
    // for Booking score badge, AliExpress flag inline, Airbnb reply styling,
    // etc. `.sbr-item-{id}` matches the frontend wrap shape exactly.
    const providerName = post?.provider?.name?.toLowerCase() || '';
    const providerSlug = slugifyForClass(providerName);
    const providerClass = providerSlug !== '' ? ` sbr-provider-${providerSlug}` : '';
    const reviewId = post?.review_id || post?.id || post?.provider_id || '';
    const reviewIdSlug = slugifyForClass(reviewId);
    const itemClass = reviewIdSlug !== '' ? ` sbr-item-${reviewIdSlug}` : '';

    // Airbnb host reply (SMASH-782 Phase 2). RapidAPI's Airbnb adapter forwards
    // host info as `post.reply = { name, avatar, from }` and the response text
    // as `post.response`. Render only when text is non-empty (no demo fallback).
    const renderAirbnbReply = () => {
        if (providerName !== 'airbnb') return null;
        // Coerce to string before `.trim()` — relay-adapter drift could
        // surface a non-string in any of these fields, which would crash
        // the preview otherwise.
        const replyText   = (post?.response       ?? '').toString().trim();
        if (replyText === '') return null;
        const replyName   = (post?.reply?.name    ?? '').toString().trim();
        const replyAvatar = (post?.reply?.avatar  ?? '').toString().trim();
        return (
            <div className='sb-item-reply' data-from='host'>
                <div className='sb-item-reply-header'>
                    {replyAvatar !== '' && (
                        <img className='sb-item-reply-avatar' src={replyAvatar} alt={replyName} loading='lazy' />
                    )}
                    {replyName !== '' && (
                        <span className='sb-item-reply-name'>{replyName}</span>
                    )}
                    <span className='sb-item-reply-label'>{__('Host', 'sb-customizer')}</span>
                </div>
                <div className='sb-item-reply-text'>{replyText}</div>
            </div>
        );
    };

    return (
        <div className={`sb-post-item-wrap${providerClass}${itemClass}`} key={postIndex}>
            <div className='sb-post-item' key={postIndex}>
                { providerName !== '' && SbUtils.printIcon( providerName + '-provider', 'sb-item-provider-icon' ) }
                {
                    (feedSettings?.postElements ?? []).map((element, key) => {
                        switch (element) {
                            case 'rating':
                                return <PostRating
                                    post={post}
                                    postIndex={postIndex}
                                    feedSettings={feedSettings}
                                    key={key}
                                    isPro={isPro}
                                />
                            case 'author':
                            return  <PostAuthor
                                    post={post}
                                    postIndex={postIndex}
                                    feedSettings={feedSettings}
                                    key={key}
                                    isPro={isPro}
                                />
                            case 'media':
                                return <PostMedia
                                    post={post}
                                    postIndex={postIndex}
                                    feedSettings={feedSettings}
                                    key={key}
                                />
                            default:
                            return <PostText
                                    post={post}
                                    postIndex={postIndex}
                                    feedSettings={feedSettings}
                                    key={key}
                                />
                        }
                    })
                }
                { renderAirbnbReply() }
            </div>
            { SbUtils.addHighlighter( 'reviews', 'Reviews', postIndex ) }
        </div>
    )
}

export default SinglePost;