import { useContext, useState } from 'react';
import SbUtils from '../../Utils/SbUtils'
import Button from '../Common/Button';

const PluginNotices = ( props ) => {
    const currentContext = SbUtils.getCurrentContext();
    const {
        globalNotices,
        focusSection
    } = useContext( currentContext ) ;
    const [ currentNoticeIndex, setCurrentNoticeIndex  ] = useState( 0 );
    const [ currentNotice, setCurrentNotice  ] = useState( globalNotices?.pluginNotices[currentNoticeIndex] || false);


    const printNoticeDescription = (description) => {
        if (Array.isArray(description)) {
            return description.join("<br/><br/>")
        }
        return description;
    }

    // A notice can point at a section on the page the reader is already looking at — the
    // sunset notice shows on Settings, and its remedy lives on Settings. Following the
    // link would reload the page just to move a scroll position.
    //
    // Handing this to the settings screen rather than scrolling here on purpose: sections
    // exist in the DOM only for the ACTIVE tab, so from any other tab a scroll finds
    // nothing. focusSection() owns the tabs, switches if needed, then scrolls. It is
    // absent on screens with no settings tabs (All Feeds), and there navigation is
    // genuinely what we want — so its absence is the fallback condition.
    //
    // getElementActions() gives `link` precedence over `onClick`, so a Button gets one or
    // the other, never both.
    const sectionType = ( link ) => {
        const match = /#sbr-settings-([a-z-]{1,40})$/.exec( String( link || '' ) );
        return match ? match[1] : null;
    };

    return (
        currentNotice &&
        <div
            className='sb-inplugin-notice-ctn sb-full-wrapper sb-fs'
            data-type={currentNotice.type}
        >
            <div className='sb-inplugin-notice-content sb-fs'>
                <div className='sb-inplugin-notice-icon'>
                    <span className='sb-inplugin-notice-svg'>{SbUtils.printIcon( 'exclamation', '', false, 16 )}</span>
                </div>
                <div className='sb-inplugin-notice-text'>
                    <h4 className='sb-inplugin-notice-heading sb-h4'>{ currentNotice.heading }</h4>
                    <span className='sb-text sb-dark2-tex' dangerouslySetInnerHTML={{__html:  printNoticeDescription(currentNotice.description)  }}></span>
                    <div className='sb-inplugin-notice-action'>
                        {
                            currentNotice?.actions && currentNotice?.actions.map( (action, key) => {
                                const type = focusSection ? sectionType( action?.link ) : null;
                                return (
                                    <Button
                                        key={key}
                                        size='medium'
                                        type={ action?.type }
                                        text={ action?.text }
                                        { ...( type
                                            ? { onClick: () => focusSection( type ) }
                                            : { link: action?.link } ) }
                                    />
                                )
                            } )
                        }
                    </div>

                </div>
            </div>
        </div>
    )

}

export default PluginNotices;
