import { useRef } from 'react';

/**
 * Horizontal radio-card group, serving badge Style and badge Theme — in Common
 * because nothing in it is badge-specific. An option's optional `art` node makes
 * the card a label under a miniature instead of a plain label.
 *
 * Geometry is the Review Alerts editor's shipped `.sb-popup-type-card` spec:
 * 12px padding, 12px gap, an 18px radio with a 6px white centre.
 *
 * @param {Object}   props
 * @param {string}   props.value      Selected option value.
 * @param {Array}    props.options    `{ value, label, art? }`.
 * @param {Function} props.onChange   Called with the new value.
 * @param {string}   props.ariaLabel  Group label for assistive tech.
 * @param {string}   [props.variant]  'tile' when options carry art, else plain.
 * @param {boolean}  [props.locked]   Renders every card `aria-disabled`. The
 *                                    stored value is left alone, so the choice
 *                                    comes back when the condition lifts.
 * @param {*}         [props.lockedValue] Which card reads as active while
 *                                    locked — the value the renderer resolves
 *                                    to, which is not necessarily the stored
 *                                    one.
 * @param {string}   [props.describedBy] Id of the element saying WHY the group
 *                                    is locked. Without it a keyboard user
 *                                    hears "unavailable" and no reason.
 *
 * Keyboard: one tab stop for the group and arrow keys between cards, which is
 * what `role="radiogroup"` promises. With default button tabbing every card was
 * its own stop and arrows did nothing, so the role described a control that was
 * not there.
 *
 * `locked` uses aria-disabled rather than `disabled`, because a disabled button
 * leaves the tab order — with every card disabled the group had no tab stop and
 * a keyboard user tabbed past it without hearing the state or the reason. The
 * handlers, not the attribute, are what keep a locked group inert.
 */
const RadioCardGroup = ( {
    value,
    options = [],
    onChange,
    ariaLabel,
    variant = 'plain',
    locked = false,
    lockedValue,
    describedBy,
} ) => {
    const isTile = variant === 'tile';
    const active = locked ? lockedValue : value;

    // The tab stop. Selected card, or the first one when nothing is selected yet —
    // a group with no tabbable card is unreachable by keyboard entirely.
    let focusIndex = options.findIndex( ( option ) => option.value === active );
    if ( focusIndex === -1 ) {
        focusIndex = 0;
    }

    // Focus targets by index. The previous version walked
    // `event.currentTarget.parentNode.querySelectorAll( '.sb-radiocard' )`, which
    // tied arrow-key navigation to both the DOM nesting and a styling class name —
    // a wrapper element or a class rename would have broken it silently.
    const cardRefs = useRef( [] );

    // Dropped entries would only ever be read through `wrapped`, which is modulo
    // options.length — but truncating says so instead of leaving it to be re-derived.
    cardRefs.current.length = options.length;

    const moveTo = ( index, event ) => {
        // preventDefault BEFORE the bail: an arrow key over a locked group otherwise
        // fell through to the browser and scrolled the page, which is not what
        // pressing a key on a disabled control should do. The keys this group owns
        // are its own whether or not it acts on them.
        event.preventDefault();

        if ( locked || options.length === 0 ) {
            return;
        }

        const wrapped = ( ( index % options.length ) + options.length ) % options.length;

        // Selection follows focus, which is the radiogroup pattern: arrowing to a
        // card chooses it rather than merely landing on it.
        onChange?.( options[ wrapped ].value );

        cardRefs.current[ wrapped ]?.focus();
    };

    const onKeyDown = ( event, index ) => {
        switch ( event.key ) {
            case 'ArrowRight':
            case 'ArrowDown':
                moveTo( index + 1, event );
                break;
            case 'ArrowLeft':
            case 'ArrowUp':
                moveTo( index - 1, event );
                break;
            case 'Home':
                moveTo( 0, event );
                break;
            case 'End':
                moveTo( options.length - 1, event );
                break;
            default:
                break;
        }
    };

    return (
        <div
            className={ `${ isTile ? 'sb-style-tiles' : 'sb-theme-cards' } sb-radiocard-group` }
            role="radiogroup"
            aria-label={ ariaLabel }
        >
            { options.map( ( option, index ) => {
                const selected = locked
                    ? option.value === lockedValue
                    : value === option.value;

                return (
                    <button
                        key={ option.value }
                        ref={ ( node ) => { cardRefs.current[ index ] = node; } }
                        type="button"
                        className={ `${ isTile ? 'sb-style-tile' : 'sb-theme-card' } sb-radiocard sb-button-reset` }
                        data-active={ selected }
                        role="radio"
                        aria-checked={ selected }
                        aria-disabled={ locked ? 'true' : undefined }
                        aria-describedby={ locked ? describedBy : undefined }
                        tabIndex={ index === focusIndex ? 0 : -1 }
                        onKeyDown={ ( event ) => onKeyDown( event, index ) }
                        onClick={ () => ! locked && onChange?.( option.value ) }
                    >
                        { /* Decoration: the label is what the control announces. */ }
                        <span className="sb-radio-deco" aria-hidden="true"></span>
                        { option.art
                            ? <span className="sb-style-tile-art" aria-hidden="true">{ option.art }</span>
                            : null }
                        <span className={ isTile ? 'sb-style-tile-label' : 'sb-theme-card-label' }>
                            { option.label }
                        </span>
                    </button>
                );
            } ) }
        </div>
    );
};

export default RadioCardGroup;
