import { useMemo, useState } from 'react';
import { __ } from '@wordpress/i18n';
import Header from '../Global/Header';
import Button from '../Common/Button';
import SbUtils from '../../Utils/SbUtils';
import { BADGE_ACTIONS, FALLBACK_LIST_URL } from '../../Utils/BadgeSettings';
import TrustBadgesScreenContext from '../Context/TrustBadgesScreenContext';
import TrustBadgesList from './TrustBadges/TrustBadgesList';
import TrustBadgesEmptyState from './TrustBadges/TrustBadgesEmptyState';
import FullScreenLoader from '../Global/FullScreenLoader';
import ModalContainer from '../Global/ModalContainer';
import CustomizerSourcesModal from '../Modals/CustomizerSourcesModal';

/**
 * All Badges — the list screen. ReviewAlertsScreen's shape: shared Header, the
 * sb-dashboard-heading row with a primary action, then the table or the empty
 * state. Only the data and the copy are new.
 */
/**
 * The two sub-objects the Header contract requires but this screen has no state for.
 * Module scope so they are the same reference on every render.
 */
const EMPTY_NOTICE_BAR_MEMO = { topNoticeBar: {} };
const EMPTY_FEED_DATA = { feedData: [] };

const TrustBadgesScreen = ( {
    editorTopLoader,
    editorNotification,
    editorConfirmDialog,
    isPro,
    upsellModal,
    noticeBar,
    apiKeyModal,
    apis,
    apiLimits,
    freeRet,
    addSModal,
    freeRetModal,
    sources,
    sourcesCount
} ) => {
    const sbCustomizer = window.sb_customizer;

    const [ badgesList, setBadgesList ] = useState(
        sbCustomizer?.trustBadges?.list?.items || []
    );
    // The FULL count, not badgesList.length: the list arrives one page at a time, so
    // the length is only ever this page's.
    const [ badgesTotal, setBadgesTotal ] = useState(
        sbCustomizer?.trustBadges?.list?.total || 0
    );
    const [ isCreating, setIsCreating ] = useState( false );

    // Source selection is the first step of creating a badge, as it is for an alert
    // (ReviewAlertsScreen.js `handleCreateNew`). A badge is a claim about specific
    // platforms, so the author picks them rather than discovering what was picked.
    const [ showSourcesModal, setShowSourcesModal ] = useState( false );

    // Three things the picker needs and this screen otherwise has no use for:
    // CustomizerSourcesModal.js:129 dereferences `fbModal` unguarded, and the
    // AddSourceModal nested inside it reads `allowedTiers` and `bulkModal` off
    // context. Built here rather than threaded from HomeScreen, which is what
    // ReviewAlertsScreen.js:94 does for the same picker.
    const [ connectFacebookActive, setConnectFacebookActive ] = useState(
        sbCustomizer?.newSourceData !== undefined
    );
    const fbModal = useMemo(
        () => ( { connectFacebookActive, setConnectFacebookActive } ),
        [ connectFacebookActive, setConnectFacebookActive ]
    );

    const initialTiers = sbCustomizer?.pluginStatus?.tier_allowed_providers;
    const [ tiers, setTiers ] = useState(
        Array.isArray( initialTiers ) ? initialTiers : [ 'google', 'yelp' ]
    );
    const allowedTiers = useMemo(
        () => ( { tiers: Array.isArray( tiers ) ? tiers : [ 'google', 'yelp' ], setTiers } ),
        [ tiers, setTiers ]
    );

    const [ bulkHistoryModalNotice, setBulkHistoryModalNotice ] = useState( false );
    const bulkModal = useMemo(
        () => ( { bulkHistoryModalNotice, setBulkHistoryModalNotice } ),
        [ bulkHistoryModalNotice, setBulkHistoryModalNotice ]
    );

    /**
     * Add New opens the source picker. Nothing is saved until a source is chosen —
     * the previous version created the badge immediately against
     * `sourcesList[0]`, so the author never saw which platform they had claimed.
     */
    const handleCreate = () => {
        setShowSourcesModal( true );
    };

    /**
     * Create the badge from the chosen sources and open it.
     *
     * The picker below passes `useDbId={ false }`, so these are `account_id`
     * strings — what badge settings store and what `providers_for_sources()`
     * queries by. Review Alerts passes true and gets database ids instead.
     */
    const handleSourcesSelected = ( selectedSources ) => {
        const chosen = ( Array.isArray( selectedSources ) ? selectedSources : [] )
            // Filtered before stringifying: a row with no account_id would become
            // the string "null", a source id no lookup can resolve.
            .filter( ( id ) => id !== null && id !== undefined && id !== '' )
            .map( ( id ) => String( id ) );

        setShowSourcesModal( false );

        // Cancel, or a confirm with nothing ticked. The picker's own button is
        // disabled while the selection is empty, so this is the closed path.
        if ( chosen.length === 0 ) {
            return;
        }

        setIsCreating( true );

        // Named after the first source, the way an alert is. Falls back to the
        // generic name when the row cannot be found rather than to an empty title.
        const sourceRows = sources?.sourcesList || [];
        const firstSource = sourceRows.find(
            ( row ) => String( row.account_id ) === chosen[0]
        );
        const name = firstSource?.name
            ? `${ firstSource.name } ${ __( 'Trust Badge', 'reviews-feed' ) }`
            : __( 'New Trust Badge', 'reviews-feed' );

        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            {
                action: BADGE_ACTIONS.save,
                nonce: sbCustomizer.nonce,
                name,
                // Sent explicitly: the save route refuses an empty settings payload.
                // chip / light is the design's opening shape for a new badge, not the
                // store's defaults (`card`).
                settings: JSON.stringify( {
                    ...( sbCustomizer?.trustBadges?.defaults || {} ),
                    style: 'chip',
                    theme: 'light',
                    sources: chosen,
                } )
            },
            ( data ) => {
                if ( data?.data?.id ) {
                    // Guarded: a missing editURL navigated to "undefined42".
                    const editURL = sbCustomizer?.trustBadges?.editURL;

                    window.location.href = editURL
                        ? `${ editURL }${ data.data.id }`
                        : FALLBACK_LIST_URL;

                    return;
                }

                setIsCreating( false );

                // No notice here: ajaxPost reads the nested `data.data.message` and
                // raises it. Raising it here too showed the failure twice.
            },
            editorTopLoader,
            editorNotification,
            {
                // No `success` entry: the redirect above is the confirmation, and
                // a toast on a page that is navigating away is never read.
                error: {
                    icon: 'info',
                    text: __( 'The badge could not be created. Please try again.', 'reviews-feed' )
                }
            }
        );
    };

    // Memoised so a re-render this screen owns but the context does not care about
    // — `isCreating` toggling, which is deliberately not a member — stops handing
    // every consumer a new value. ReviewAlertsScreen.js:38 does the same.
    const screenContext = useMemo(
        () => ( {
            sbCustomizer,
            badgesList,
            setBadgesList,
            badgesTotal,
            setBadgesTotal,
            editorTopLoader,
            editorNotification,
            editorConfirmDialog,
            isPro: isPro || sbCustomizer?.isPro,
            upsellModal,
            // Header context compatibility — Header reads these off whatever
            // context getCurrentContext() resolves to, so they have to be
            // present here as they are on the alerts screen.
            apiKeyModal,
            apis,
            apiLimits,
            freeRet,
            addSModal,
            freeRetModal,
            noticeBar,
            noticeBarMemo: EMPTY_NOTICE_BAR_MEMO,
            editorFeedData: EMPTY_FEED_DATA,
            headerClasses: '',
            globalNotices: null,
            sources,
            sourcesCount,
            // Read off context by the source picker and the AddSourceModal inside it.
            fbModal,
            allowedTiers,
            bulkModal
        } ),
        [
            sbCustomizer, badgesList, setBadgesList, badgesTotal, setBadgesTotal,
            editorTopLoader, editorNotification, editorConfirmDialog, isPro,
            upsellModal, apiKeyModal, apis, apiLimits, freeRet, addSModal,
            freeRetModal, noticeBar, sources, sourcesCount, fbModal, allowedTiers,
            bulkModal
        ]
    );

    return (
        <TrustBadgesScreenContext.Provider value={ screenContext }>
            <Header
                className="sb-dashboard-header"
                heading={ __( 'Trust Badges', 'reviews-feed' ) }
                editorTopLoader={ editorTopLoader }
                topNoticeBar={ noticeBar?.topNoticeBar }
                setTopNoticeBar={ ( e ) => {
                    noticeBar?.setTopNoticeBar?.( e );
                } }
                showHelpButton={ true }
            />

            { isCreating && <FullScreenLoader /> }

            <section className="sb-full-wrapper sb-fs">
                <div className="sb-dashboard-heading sb-fs">
                    <h2 className="sb-h2">{ __( 'Trust Badges', 'reviews-feed' ) }</h2>
                    <div className="sb-dashboard-action-btns">
                        <Button
                            customClass="sb-dashboard-btn"
                            type="primary"
                            size="small"
                            icon="plus"
                            iconPosition="left"
                            iconSize="11"
                            text={ __( 'Add New', 'reviews-feed' ) }
                            onClick={ handleCreate }
                        />
                    </div>
                </div>

                { badgesList.length > 0 ? <TrustBadgesList /> : <TrustBadgesEmptyState /> }
            </section>

            { showSourcesModal && (
                <ModalContainer
                    size="medium"
                    closebutton={ true }
                    onClose={ () => setShowSourcesModal( false ) }
                >
                    <CustomizerSourcesModal
                        selectedSources={ [] }
                        fbModal={ fbModal }
                        useDbId={ false }
                        onCancel={ () => setShowSourcesModal( false ) }
                        onUpdateSources={ handleSourcesSelected }
                        title={ __( 'Select Sources', 'reviews-feed' ) }
                        description={ __( "The badge rating is calculated from the sources you select below. Don't worry, you can always change this later.", 'reviews-feed' ) }
                        buttonText={ __( 'Create Trust Badge', 'reviews-feed' ) }
                        buttonIcon="chevron-right"
                        buttonIconPosition="right"
                    />
                </ModalContainer>
            ) }
        </TrustBadgesScreenContext.Provider>
    );
};

export default TrustBadgesScreen;
