import { useContext } from 'react';
import { __ } from '@wordpress/i18n';
import TrustBadgeEditorContext from '../Context/TrustBadgeEditorContext';
import FeedSources from '../Common/FeedSources';
import { resolveSources } from '../../Utils/BadgeSettings';

/**
 * Trust Badge sources (SBR-163). A thin wrapper over the shipped FeedSources
 * control, so there is no second picker to keep in step with the sources table.
 *
 * `useDbId` is false, so selections store `account_id` — what consumers speak:
 * `providers_for_sources()` queries `WHERE account_id IN (…)`, `feed_for_badge()`
 * matches on it. Review Alerts passes true, and copying that lists the source
 * while silently not scoping the rating.
 */
const TrustBadgeSources = ( { selected, onChange } ) => {
    const { sources, fbModal, fbManualModal } = useContext( TrustBadgeEditorContext );

    // Guarded like TrustBadgePreview.js:65. Before the rows arrive `resolveSources`
    // resolves nothing, which is indistinguishable from every source being gone — so
    // an unguarded call flashes "no longer available" over ids that are perfectly
    // valid, and the summary asks for a source the badge already has.
    const sourceRows = sources?.sourcesList;
    const rowsLoaded = Array.isArray( sourceRows );
    const { selectedSources, unresolvedIds } = rowsLoaded
        ? resolveSources( sourceRows, selected )
        : { selectedSources: [], unresolvedIds: [] };

    const dropUnresolved = ( id ) => {
        onChange( ( selected || [] ).filter( ( value ) => String( value ) !== String( id ) ) );
    };

    return (
        <div className="sb-customizer-sidebar-section-ctn sb-fs">
            <div className="sb-customizer-sidebar-sec-el sb-fs sb-sec-open-hd">
                <span className="sb-small-p sb-bold sb-dark-text">{ __( 'Sources', 'reviews-feed' ) }</span>
            </div>

            <div className="sb-control-content sb-fs sb-dropdown-tall">
                <div className="sb-control-elem-output">
                    <FeedSources
                        customClass="sb-feedsources-control"
                        sources={ sources }
                        feedSourcesList={ selectedSources }
                        value={ selected || [] }
                        fbModal={ fbModal }
                        fbManualModal={ fbManualModal }
                        onChange={ onChange }
                        useDbId={ false }
                    />
                </div>
            </div>

            { unresolvedIds.length > 0 && (
                <div className="sb-control-content sb-fs sbr-tb-dead-sources">
                    { unresolvedIds.map( ( id ) => (
                        <div className="sbr-tb-dead-source" key={ id }>
                            <span className="sbr-tb-dead-source-text">
                                { __( 'This source is no longer available. The badge stays hidden until you remove it or reconnect the source.', 'reviews-feed' ) }
                            </span>
                            <button
                                type="button"
                                className="sb-button-reset sbr-tb-dead-source-remove"
                                onClick={ () => dropUnresolved( id ) }
                            >
                                { __( 'Remove', 'reviews-feed' ) }
                            </button>
                        </div>
                    ) ) }
                </div>
            ) }

            { /* One source is a claim about that platform, several a claim about
                 the combined feed. Zero gets neither: a new badge on a site with no
                 connected sources saves `sources: []`, and promising a combined
                 rating over nothing is the one sentence that is simply false. */ }
            <p className="sb-small-p sb-light-text sb-dropdown-tall">
                { /* Counted on what RESOLVED, not on what is stored: an unresolvable
                     id renders nothing, so counting it said "the badge reports this
                     source's own rating" over a badge reporting nothing at all. */ }
                { selectedSources.length === 0 && __( 'Add a source for the badge to report a rating.', 'reviews-feed' ) }
                { selectedSources.length === 1 && __( 'The badge reports this source\'s own rating.', 'reviews-feed' ) }
                { selectedSources.length > 1 && __( 'The badge reports the combined rating of every source above.', 'reviews-feed' ) }
            </p>
        </div>
    );
};

export default TrustBadgeSources;
