import { __, sprintf } from '@wordpress/i18n';
import SbUtils from '../../../Utils/SbUtils'
import Button from '../../Common/Button';

const Header = ( { feedSettings, editorFeedData, isPro, globalSettings } ) => {
    let totalReviews = 0,
        ratingAverage = 0;

    const sourcesList = editorFeedData?.feedData?.sourcesList || [];

    // SMASH-1412: prefer the plugin-computed feed aggregate when present. For
    // EDD / WooCommerce multi-source feeds the plugin dedups across overlapping
    // downloads / products and emits feed_total_review_count + feed_average_rating
    // on each source.info. Older plugin builds don't set feed_aggregated, so
    // the fallback below preserves the previous behaviour (which is correct for
    // independent businesses like Yelp / Google / Trustpilot).
    let aggregate = null;
    for ( const source of sourcesList ) {
        const info = SbUtils.jsonParse( source.info );
        if ( info?.feed_aggregated ) {
            aggregate = {
                count: parseInt( info.feed_total_review_count || 0 ),
                avg: parseFloat( info.feed_average_rating || 0 ),
            };
            break;
        }
    }

    if ( aggregate ) {
        totalReviews = aggregate.count;
        ratingAverage = aggregate.avg;
    } else {
        // SMASH-1583: weight each source's rating by its review count (matches
        // the front-end Parser::get_average_rating) so a 3-review Facebook
        // source can't swing the headline as hard as a 219-review Google one.
        // The PHP preview path backfills empty counts (FB recommendations) into
        // these source infos, so the count read here lines up with the live feed.
        let weightedSum = 0,
            weightedCount = 0,
            simpleSum = 0,
            simpleN = 0;
        sourcesList.forEach( source => {
            const info = SbUtils.jsonParse( source.info );
            if ( info ) {
                // Support both old format (total_rating) and new format (review_count)
                const reviewCount = parseInt( info?.review_count || info?.total_rating || 0, 10 ) || 0;
                totalReviews += reviewCount;
                // Support both rating and average_rating for WooCommerce multi-product sources
                const rating = parseFloat( info?.rating || info?.average_rating || 0 ) || 0;
                if ( rating > 0 ) {
                    weightedSum += rating * reviewCount;
                    weightedCount += reviewCount;
                    simpleSum += rating;
                    simpleN += 1;
                }
            }
        } );
        // When no source reports a count, fall back to the unweighted mean of
        // the rated sources — same as the PHP front-end (Parser::get_average_rating),
        // which also skips empty ratings. This is intentionally NOT the old preview
        // math (which divided by sourcesList.length); aligning the preview with the
        // published feed is the point of this change.
        if ( weightedCount > 0 ) {
            ratingAverage = Math.round( ( weightedSum / weightedCount ) * 10 ) / 10;
        } else if ( simpleN > 0 ) {
            ratingAverage = Math.round( ( simpleSum / simpleN ) * 10 ) / 10;
        } else {
            ratingAverage = 0;
        }
    }

    // SMASH-782: a Booking-only feed shows the hotel's REAL Booking general
    // rating (review_score 0-10 + review_score_word, e.g. "9.5 Exceptional")
    // instead of the converted 5-star average — same SCALE as the per-card score
    // badge (PostRating.js renderBookingScore), not the same value: this is the
    // property's overall score with Booking's own word, while each card carries
    // its own reviewer's score with the band word for it. Only fires when
    // EVERY source carries a native review_score; a single non-Booking source
    // (or older Booking data without the field) falls back to stars.
    let bookingRating = { only: false, score: 0, word: '' };
    if ( sourcesList.length > 0 ) {
        const scores = [];
        const words = [];
        let allNative = true;
        let weightedSum = 0,
            weightedCount = 0;
        for ( const source of sourcesList ) {
            const info = SbUtils.jsonParse( source.info );
            const score = parseFloat( info?.review_score );
            // Require the source to actually be Booking, not just to carry a
            // review_score — so the native-score header can never be applied to
            // a non-Booking feed if another provider ever exposes the field.
            if ( source.provider !== 'booking' || ! Number.isFinite( score ) || score <= 0 ) {
                allNative = false;
                break;
            }
            scores.push( score );
            // Count-weight the native 0-10 score by each hotel's review volume so a
            // 12k-review hotel dominates a 300-review one — mirrors the PHP
            // FeedDisplay::get_booking_header_rating(). Booking stores the volume in
            // total_rating; some payloads use review_count.
            const count = parseInt( info?.review_count ?? info?.total_rating ?? 0, 10 ) || 0;
            if ( count > 0 ) {
                weightedSum += score * count;
                weightedCount += count;
            }
            const word = typeof info?.review_score_word === 'string' ? info.review_score_word.trim() : '';
            if ( word !== '' ) {
                words.push( word );
            }
        }
        if ( allNative && scores.length > 0 ) {
            // Prefer the count-weighted mean on the 0-10 scale; fall back to the
            // unweighted mean only when no source reported a usable count (mirrors PHP).
            const avg = weightedCount > 0
                ? Math.round( ( weightedSum / weightedCount ) * 10 ) / 10
                : Math.round( ( scores.reduce( ( a, b ) => a + b, 0 ) / scores.length ) * 10 ) / 10;
            // Word only when every source agrees (single source trivially does);
            // averaging distinct words would fabricate a rating Booking never gave.
            const word = ( words.length === scores.length && new Set( words ).size === 1 ) ? words[0] : '';
            bookingRating = { only: true, score: avg, word };
        }
    }

    const halfStarIcon = ( i ) => {
        const icons = [SbUtils.printIcon( 'star', 'sb-feed-header-icon sb-item-rating-icon-dimmed' , i ) , SbUtils.printIcon( 'star', ' sb-item-rating-icon-halfdimmed')];
        return (
            <span className='sb-feed-item-icon sb-feed-item-icon-half' key={i}>
                { icons }
            </span>
        )
    }
    return (
            feedSettings.showHeader &&
                <section className='sb-feed-header sb-fs' data-align='left'>
                    {
                        SbUtils.addHighlighter( 'header', 'Header', 0, true  )
                    }
                    <div className='sb-feed-header-content'>
                        {
                            feedSettings.headerContent.includes( 'heading' ) &&
                            <div className='sb-feed-header-heading'>
                                <span className='sb-relative sb-flex'>
                                    {feedSettings.headerHeadingContent}
                                    { SbUtils.addHighlighter( 'heading', 'Heading', 0 ,  ['id', 'heading'] ) }
                                </span>
                            </div>
                        }
                        <div className='sb-feed-header-bottom sb-fs'>
                            {
                                ( feedSettings.headerContent.includes( 'averagereview' ) && isPro ) &&
                                <div className={ 'sb-feed-header-average sb-relative' + ( bookingRating.only ? ' sb-feed-header-average-booking' : '' ) }>
                                    {
                                        bookingRating.only
                                        ? <>
                                            <span className='sb-feed-header-rating'>{ bookingRating.score.toFixed( 1 ) }</span>
                                            { bookingRating.word !== '' &&
                                                <span className='sb-feed-header-rating-label'>{ bookingRating.word }</span>
                                            }
                                          </>
                                        : <>
                                            <span className='sb-feed-header-rating'>{ ratingAverage }</span>
                                            <span className='sb-feed-header-rating-icons'>
                                                {
                                                    Array.from({ length: 5 } , (ic, i) => {
                                                        const iconClass = ratingAverage - i < 1 ? ' sb-item-rating-icon-dimmed' : '';
                                                        if( ratingAverage - i < 1 && ratingAverage - i >= 0.5 ){
                                                            return halfStarIcon( i )
                                                        }
                                                        return SbUtils.printIcon( 'star', 'sb-feed-header-icon' + iconClass, i )
                                                    })
                                                }
                                            </span>
                                          </>
                                    }
                                    <span className='sb-feed-header-rating-subtext'>{ sprintf( __( 'Over %d Reviews', 'sb-customizer' ), totalReviews ) }</span>
                                    { SbUtils.addHighlighter( 'header-average', 'Average Reviews Rating' ) }
                                </div>
                            }
                            {
                                feedSettings.headerContent.includes( 'button' ) &&
                                <div className='sb-feed-header-btn-ctn sb-relative'>
                                    <Button
                                        icon='pen'
                                        customClass='sb-feed-header-btn'
                                        text={globalSettings?.pluginSettings?.translations?.writeReview ?? __('Write a Review', 'sb-customizer')}
                                    />
                                    { SbUtils.addHighlighter( 'header-button', 'Header Button' ) }

                                </div>
                            }
                        </div>
                    </div>
                </section>
    )
}

export default Header;