import SbUtils from '../../../Utils/SbUtils'

const PostAuthor = ( { post, postIndex, feedSettings, isPro } ) => {
    const avatarUrl = post?.reviewer?.avatar || `${window.sb_customizer.assetsURL}sb-customizer/assets/images/avatar.jpg`;

    // New-source providers mark the author block as a review section element so
    // it shares the uniform section spacing and the gap is preserved when
    // adjacent sections are toggled off.
    const horizontalElementClass = ['booking', 'aliexpress', 'airbnb'].includes( post?.provider?.name?.toLowerCase() )
        ? ' sbr-review-horizontal-element'
        : '';

    // SMASH-782 Phase 2 — for AliExpress, render the buyer's country flag
    // INLINE next to the reviewer name (per prototype AliExpressCard.jsx).
    // Mirrors the PHP injection at templates/frontend/pro/post-elements/author.php.
    const renderAliexpressFlag = () => {
        const providerName = post?.provider?.name?.toLowerCase();
        if (providerName !== 'aliexpress') return null;
        const buyerCountry = (post?.metadata?.buyer_country || '').toString().trim();
        // Strict ISO-3166 alpha-2 check before code-point math. A
        // length-only check would let `"1A"` or `"!?"` through, producing
        // garbage glyphs or out-of-range code points. Mirrors the PHP
        // side (`ctype_alpha` + `strlen === 2`) in author.php.
        if (!/^[A-Za-z]{2}$/.test(buyerCountry)) return null;
        const cc = buyerCountry.toUpperCase();
        const offset = 0x1F1E6 - 'A'.charCodeAt(0);
        const flag = String.fromCodePoint(cc.charCodeAt(0) + offset) + String.fromCodePoint(cc.charCodeAt(1) + offset);
        return (
            <span className='sb-item-author-flag' aria-label={buyerCountry}>{` ${flag}`}</span>
        );
    };

    return (
        <div className={`sb-item-author-date-ctn sb-fs${horizontalElementClass}`}>
        <div className='sb-item-author-ctn sb-relative'>
            {
                ( feedSettings.authorContent.includes( 'image' ) && isPro ) &&
                <div className='sb-item-author-img sb-relative' title={SbUtils.decodeHtmlEntities(post?.reviewer?.name)}
                    style={{
                        backgroundImage: `url(${avatarUrl})`
                    }}
                >
                    { SbUtils.addHighlighter( 'post-author-image', 'Author Image' , postIndex ) }
                </div>
            }
            {
                ( feedSettings.authorContent.includes( 'name' ) || feedSettings.authorContent.includes( 'date' ) ) &&
                <div className='sb-item-name-date'>
                    {
                        feedSettings.authorContent.includes( 'name' ) &&
                        <span className='sb-item-author-name sb-relative'>
                            {SbUtils.decodeHtmlEntities(post?.reviewer?.name)}
                            { renderAliexpressFlag() }
                            { SbUtils.addHighlighter( 'post-author-name', 'Author Name' , postIndex ) }
                        </span>
                    }
                    {
                        feedSettings.authorContent.includes( 'date' ) &&
                        <span className='sb-item-author-date sb-relative'>
                            { feedSettings?.dateBeforeText + ' ' + SbUtils.printDate(post?.time, feedSettings ) + ' ' + feedSettings?.dateAfterText}
                            { SbUtils.addHighlighter( 'post-date', 'Date' , postIndex ) }
                        </span>
                    }
                </div>
            }
            { SbUtils.addHighlighter( 'post-author-date', 'Author and Date' , postIndex ) }
        </div>
        </div>
    )
}

export default PostAuthor;