import { useContext } from 'react';
import { __ } from '@wordpress/i18n';
import TrustBadgeEditorContext from '../Context/TrustBadgeEditorContext';
import { badgeEmptyMessage, resolveSources, unreportedNote } from '../../Utils/BadgeSettings';

/**
 * Trust Badge preview (SBR-163). The page around the badge is a skeleton wireframe
 * so the badge can be judged in context without competing with it: everything grey
 * is placeholder artwork. The badge markup comes from PHP — see ajax_preview().
 */

/** Device chooser icons, from the shipped feed customizer's own chooser. */
const DEVICE_ICONS = {
    desktop: (
        <svg viewBox="0 0 14 13" aria-hidden="true" focusable="false">
            <path d="M12.2497 8.83342H1.74967V1.83341H12.2497V8.83342ZM12.2497 0.666748H1.74967C1.10217 0.666748 0.583008 1.18591 0.583008 1.83341V8.83342C0.583008 9.14283 0.705924 9.43958 0.924717 9.65837C1.14351 9.87717 1.44026 10.0001 1.74967 10.0001H5.83301V11.1667H4.66634V12.3334H9.33301V11.1667H8.16634V10.0001H12.2497C12.5591 10.0001 12.8558 9.87717 13.0746 9.65837C13.2934 9.43958 13.4163 9.14283 13.4163 8.83342V1.83341C13.4163 1.524 13.2934 1.22725 13.0746 1.00846C12.8558 0.789664 12.5591 0.666748 12.2497 0.666748Z" />
        </svg>
    ),
    tablet: (
        <svg viewBox="0 0 10 13" aria-hidden="true" focusable="false">
            <path d="M8.16667 1.83342V11.1667H1.16667L1.16667 1.83342H8.16667ZM0 1.25008L0 11.7501C0 12.3976 0.519167 12.9167 1.16667 12.9167H8.16667C8.47608 12.9167 8.77283 12.7938 8.99162 12.575C9.21042 12.3562 9.33333 12.0595 9.33333 11.7501V1.25008C9.33333 0.940663 9.21042 0.643918 8.99162 0.425125C8.77283 0.206333 8.47608 0.083416 8.16667 0.083416H1.16667C0.857247 0.083416 0.560501 0.206333 0.341709 0.425125C0.122916 0.643918 0 0.940663 0 1.25008Z" />
        </svg>
    ),
    mobile: (
        <svg viewBox="0 0 9 13" aria-hidden="true" focusable="false">
            <path d="M7.25 10.5833H1.41667V2.41659H7.25V10.5833ZM7.25 0.083252H1.41667C0.769167 0.083252 0.25 0.602419 0.25 1.24992V11.7499C0.25 12.0593 0.372916 12.3561 0.591709 12.5749C0.810501 12.7937 1.10725 12.9166 1.41667 12.9166H7.25C7.55942 12.9166 7.85617 12.7937 8.07496 12.5749C8.29375 12.3561 8.41667 12.0593 8.41667 11.7499V1.24992C8.41667 0.940499 8.29375 0.643753 8.07496 0.424961C7.85617 0.206168 7.55942 0.083252 7.25 0.083252Z" />
        </svg>
    ),
};

const DEVICES = [
    { key: 'desktop', label: __( 'Desktop', 'reviews-feed' ) },
    { key: 'tablet', label: __( 'Tablet', 'reviews-feed' ) },
    { key: 'mobile', label: __( 'Mobile', 'reviews-feed' ) },
];

/**
 * How many marks the placeholder draws.
 *
 * One per DISTINCT PROVIDER, not one per source: `providers_for_sources()`
 * dedupes by provider (SBR_Badge_Renderer.php), so a badge with two Google
 * sources draws one mark. Counting sources made the placeholder wider than the
 * badge on the most ordinary multi-source setup there is.
 *
 * A full logo speaks for one platform, so there is exactly one lockup however
 * many sources are behind the number.
 *
 * No cap. The placeholder uses the badge's own `.sbr-tb-logos` container and the
 * same mark size, so it wraps exactly where the badge wraps — measured at 22
 * marks in the desktop preview. A cap only made the two disagree earlier.
 *
 * Falls back to one while the source rows are still loading: at that point
 * nothing resolves, which is indistinguishable from every source being gone.
 *
 * @param {Object} settings   Badge settings.
 * @param {Array}  sourceRows The sources table, or undefined before it loads.
 * @return {number} Marks to draw.
 */
const ghostMarkCount = ( settings, sourceRows ) => {
    if ( settings?.logo_style === 'full' ) {
        return 1;
    }

    if ( ! Array.isArray( sourceRows ) ) {
        return 1;
    }

    const { selectedSources } = resolveSources( sourceRows, settings?.sources );
    const providers = [];

    selectedSources.forEach( ( row ) => {
        const provider = row?.provider ? String( row.provider ) : '';

        if ( provider !== '' && ! providers.includes( provider ) ) {
            providers.push( provider );
        }
    } );

    return Math.max( providers.length, 1 );
};

/**
 * The badge slot's placeholder — the badge's own shell, unpainted.
 *
 * It carries the real wrapper classes (`sbr-tb-badge sbr-tb-style-<style>`) and
 * the real element classes, so every dimension that decides the box — padding,
 * radius, gaps, the value's font size, the star size, the mark size — comes from
 * the plugin's own stylesheet per style. The version this replaced was one
 * hand-drawn shape, 232x88, standing in for boxes of 179x69 (chip), 311x65
 * (card) and 188x140 (medal): it jumped in both axes on every style.
 *
 * The leaves are empty. Nothing renders a plausible-looking rating that could
 * survive a missing stylesheet and read as real data — the widths come from
 * `em` sizing in trust-badges.css instead.
 *
 * Same shimmer as the Review Alerts preview (`sbr-popup-skeleton`), and the same
 * rules paint the live badge while a source change recalculates.
 */
const BadgeGhost = ( { settings, sourceRows } ) => {
    const style = [ 'chip', 'card', 'medal' ].includes( settings?.style ) ? settings.style : 'chip';
    const marks = Array.from( { length: ghostMarkCount( settings, sourceRows ) }, ( _, i ) => i );
    const full = settings?.logo_style === 'full';

    const value = settings?.show_rating === false ? null : <span className="sbr-tb-val"></span>;
    const stars = settings?.show_stars === false ? null : (
        <span className="sbr-badge-stars">
            { [ 0, 1, 2, 3, 4 ].map( ( i ) => <span className="sbr-badge-star" key={ i }></span> ) }
        </span>
    );
    const count = settings?.show_count === false ? null : <span className="sbr-tb-cnt"></span>;
    const logos = settings?.show_logos === false ? null : (
        <span className={ full ? 'sbr-tb-logos sbr-tb-logos-full' : 'sbr-tb-logos' }>
            { marks.map( ( i ) => (
                <span className={ full ? 'sbr-tb-lockup' : 'sbr-tb-provider' } key={ i }></span>
            ) ) }
        </span>
    );

    return (
        <div
            className={ `sbr-tb-badge sbr-tb-style-${ style } sbr-tb-badge-ghost` }
            data-theme={ settings?.theme || 'light' }
            data-logos={ settings?.logo_color === 'mono' ? 'mono' : 'brand' }
            aria-hidden="true"
        >
            <div className="sbr-tb-main">
                { /* The three styles differ in element ORDER, which is why the
                     plugin ships three templates rather than one with branches
                     (see templates/frontend/badges/). The shell mirrors that. */ }
                { style === 'chip' && (
                    <>
                        <div className="sbr-tb-row">
                            { value }
                            { stars }
                            { count }
                        </div>
                        { logos }
                    </>
                ) }

                { style === 'card' && (
                    <>
                        { value }
                        <span className="sbr-tb-card-col">
                            { stars }
                            { count }
                        </span>
                        { logos && <span className="sbr-tb-card-src">{ logos }</span> }
                    </>
                ) }

                { style === 'medal' && (
                    <>
                        { value }
                        { stars }
                        { count }
                        { logos }
                    </>
                ) }
            </div>

            { settings?.show_footer && (
                <div className="sbr-tb-foot">
                    <span></span>
                </div>
            ) }
        </div>
    );
};

/** One placeholder product card. */
const SkeletonProduct = () => (
    <div className="sbr-tb-product">
        <div className="sbr-tb-product-img">
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                <path d="M3 16l5-5 4 4 3-3 6 6" />
                <circle cx="8.5" cy="8.5" r="1.5" />
                <rect x="3" y="3" width="18" height="18" rx="2" />
            </svg>
        </div>
        <span className="sbr-tb-skel" style={ { width: '70%' } }></span>
        <span className="sbr-tb-skel" style={ { width: '40%' } }></span>
    </div>
);


const TrustBadgePreview = () => {
    const { device, setDevice, previewHtml, isLoadingPreview, isRecalculating, previewFailed, badge, sources, unreported } =
        useContext( TrustBadgeEditorContext );

    // The rating on screen is wrong, not merely stale, once a source is added or
    // removed — so the placeholder goes back up until the new number lands. Set in
    // TrustBadgeEditor on the click, before the debounce. Every other setting keeps
    // its badge: a shimmer on every pixel of a hue drag would strobe, and the badge
    // already there is a better placeholder for the next one than a grey shape.
    const recalculating = !! isRecalculating;

    // With a badge on screen the placeholder is that badge, masked in place, so the
    // box cannot change. Only when there is nothing to mask — the first render on a
    // cold aggregate, which reads every source's feed and takes long enough that an
    // empty slot reads as a broken badge — is a shell drawn from scratch.
    const maskLive = recalculating && previewHtml !== '';
    const showGhost = ( isLoadingPreview || recalculating ) && previewHtml === '';
    const placeholderUp = maskLive || showGhost;

    // One sentence naming what did not count, derived in BadgeSettings so it is
    // testable without rendering this component — and so a badge that is BOTH
    // errored and pending gets both sentences.
    const note = unreportedNote( unreported );

    // An empty preview has three causes and they need different sentences. Telling
    // someone who has already picked three sources to "add a source" sends them
    // to fix the one thing that is not wrong — and telling someone whose sources
    // are all disconnected to wait for reviews never comes true.
    const chosenSources = Array.isArray( badge?.settings?.sources ) ? badge.settings.sources.length : 0;
    // Same resolution the sidebar lists dead ids with (TrustBadgeSources.js:19).
    // Only meaningful once the rows are here: before that everything resolves to
    // nothing, which is indistinguishable from every source being disconnected.
    const sourceRows = sources?.sourcesList;
    const resolvedCount = Array.isArray( sourceRows )
        ? resolveSources( sourceRows, badge?.settings?.sources ).selectedSources.length
        : undefined;

    return (
        // Structure copied from ReviewAlertPreview: every class here has rules in
        // the shipped CSS, device widths included (the
        // `[data-preview-device=tablet|mobile] .sb-preview-wrapper` rules in
        // sb-common.css). Our `[data-device]` rules cover only the scene.
        <section className="sb-customizer-preview" data-preview-device={ device }>
            <section className="sb-preview-wrapper sb-fs sb-tr-2" data-device={ device }>
                <section className="sb-preview-devices-top sb-fs">
                    <span className="sb-bold sb-text-tiny sb-dark2-text">{ __( 'Preview', 'reviews-feed' ) }</span>

                    <div className="sb-preview-devices-chooser">
                        { DEVICES.map( ( { key, label } ) => (
                            <button
                                key={ key }
                                type="button"
                                className="sb-preview-chooser-btn"
                                data-device={ key }
                                data-active={ device === key }
                                aria-label={ label }
                                aria-pressed={ device === key }
                                onClick={ () => setDevice( key ) }
                            >
                                { DEVICE_ICONS[ key ] }
                            </button>
                        ) ) }
                    </div>
                </section>

                {/* Same slot Review Alerts puts its preview in. The modifier drops
                    that slot's inner padding for this screen: the slot is already a
                    white rounded card, and the wireframe canvas was a second one
                    inside it — two nested cards, with the inner one not even
                    reaching the edges (510px inside 665px of usable width). One
                    frame, filled edge to edge, reads as the page it is standing in
                    for. */}
                <section className="sb-popup-preview-area sb-fs sb-tb-preview-area">
                <div className="sbr-tb-site">
                    <div className="sbr-tb-site-nav">
                        <span className="sbr-tb-site-brand">
                            <i></i>
                            <span className="sbr-tb-skel" style={ { width: '76px', height: '12px' } }></span>
                        </span>
                        <span className="sbr-tb-site-links">
                            { [ 44, 58, 38, 50 ].map( ( w, i ) => (
                                <span key={ i } className="sbr-tb-skel" style={ { width: `${ w }px` } }></span>
                            ) ) }
                        </span>
                    </div>

                    <div className="sbr-tb-hero">
                        <span className="sbr-tb-skel" style={ { width: '112px', height: '8px' } }></span>
                        <div className="sbr-tb-skel-headline">
                            <span className="sbr-tb-skel" style={ { width: '420px' } }></span>
                            <span className="sbr-tb-skel" style={ { width: '280px' } }></span>
                        </div>
                        <div className="sbr-tb-skel-copy">
                            <span className="sbr-tb-skel" style={ { width: '430px' } }></span>
                            <span className="sbr-tb-skel" style={ { width: '330px' } }></span>
                        </div>

                        { /* `data-recalculating` masks the live badge in place rather
                             than swapping in a shape of another size: its box is then
                             exactly the badge's, so the recalculation costs no layout
                             shift. Rules in trust-badges.css. */ }
                        <div
                            className="sbr-tb-badge-slot"
                            data-recalculating={ maskLive ? '1' : undefined }
                            aria-busy={ placeholderUp ? 'true' : undefined }
                        >
                            {
                                // Reasons in `showGhost` above.
                                showGhost
                                    ? <BadgeGhost settings={ badge?.settings } sourceRows={ sourceRows } />
                                : // An empty render is a real answer — the renderer
                                  // refuses rather than publish an unresolved badge —
                                  // so say so instead of leaving a blank slot.
                                ! isLoadingPreview && previewHtml === ''
                                    ? (
                                        <span className="sbr-tb-badge-empty">
                                            { badgeEmptyMessage( previewFailed, chosenSources, resolvedCount ) }
                                        </span>
                                    )
                                    : (
                                        // Not SafeHtml: its span/b/i allowlist strips the
                                        // badge's div, the provider <svg>s and the inline
                                        // hue properties. Safe for this source only — our
                                        // own nonce- and capability-gated endpoint, whose
                                        // every dynamic field is escaped at the output sink
                                        // (esc_html/esc_attr in templates/frontend/badges/,
                                        // esc_url on footer_url in tb-footer.php).
                                        // Enforced by
                                        // tests/Unit/Badges/BadgeOutputEscapingTest.php in the
                                        // plugin, which drives the renderer AND each template
                                        // in templates/frontend/badges/ with hostile values and
                                        // asserts structurally (DOMXPath: no script element, no
                                        // on* attribute, no executable scheme). Mutation set
                                        // .claude/qa/mutations/sbr-163-badge-output-escaping.json
                                        // removes each escape in turn; all 5 fail a test.
                                        // nosemgrep: react-dangerouslysetinnerhtml -- Safe: markup from SBR_Badge_Renderer, every dynamic field escaped at output
                                        <div dangerouslySetInnerHTML={ { __html: previewHtml } } />
                                    )
                            }
                        </div>

                        { /* Editor only, and BENEATH the badge: the badge itself is
                             rendered from the sources that reported, so a visitor
                             sees a correct rating and no apology. The author is the
                             only one who can act on this, so the author is the only
                             one told. Names, not a count — "2 sources are not
                             loading" does not say which one to reconnect. */ }
                        { ! placeholderUp && ! isLoadingPreview && previewHtml !== '' && note !== '' && (
                            <div className="sbr-tb-unreported" role="status">
                                { note }
                            </div>
                        ) }

                        <div className="sbr-tb-cta-row">
                            <span className="sbr-tb-skel-btn"></span>
                            <span className="sbr-tb-skel-btn"></span>
                        </div>
                    </div>

                    <div className="sbr-tb-products">
                        { [ 1, 2, 3 ].map( ( i ) => <SkeletonProduct key={ i } /> ) }
                    </div>
                </div>
                </section>
            </section>
        </section>
    );
};

export default TrustBadgePreview;
