import { useEffect, useRef } from 'react';
import { __ } from '@wordpress/i18n';

/**
 * Curved Arrow SVG Component
 * Points from the heading area toward the preview content
 */
const CurvedArrow = () => (
    <svg
        className="sbr-emptystate-arrow"
        width="250"
        height="140"
        viewBox="0 0 250 140"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
    >
        <path
            d="M6.58607 0.17067C6.12798 -0.137837 5.50654 -0.0165789 5.19803 0.441506L0.170625 7.90644C-0.137881 8.36452 -0.0166235 8.98597 0.441462 9.29448C0.899547 9.60298 1.52099 9.48172 1.8295 9.02364L6.2983 2.38814L12.9338 6.85695C13.3919 7.16545 14.0133 7.0442 14.3218 6.58611C14.6303 6.12803 14.5091 5.50658 14.051 5.19807L6.58607 0.17067ZM249.527 131.5L249.27 130.534C204.495 142.474 149.457 138.57 102.841 117.39C56.2475 96.2198 18.1349 57.8289 7.00896 0.808596L6.02747 1.00011L5.04598 1.19162C16.3201 58.9713 54.9574 97.8304 102.014 119.211C149.047 140.58 204.56 144.526 249.785 132.466L249.527 131.5Z"
            fill="url(#paint0_linear_emptystate)"
        />
        <defs>
            <linearGradient
                id="paint0_linear_emptystate"
                x1="11.0275"
                y1="23.0001"
                x2="249.027"
                y2="112.5"
                gradientUnits="userSpaceOnUse"
            >
                <stop stopColor="#0068A0" />
                <stop offset="1" stopColor="#0068A0" stopOpacity="0" />
            </linearGradient>
        </defs>
    </svg>
);

/**
 * Feature Empty State Component
 *
 * Reusable empty state layout with:
 * - Curved arrow pointing from heading to preview
 * - Preview image demonstrating the feature
 * - Title and description text
 *
 * @param {Object} props
 * @param {string} props.imageUrl - URL to the preview image
 * @param {string} props.imageAlt - Alt text for the preview image
 * @param {Object} props.specimen - Rendered specimen to show instead of an image. Takes
 *                                  precedence over imageUrl when given, for a feature
 *                                  whose specimen the browser can draw for real.
 * @param {string} props.title - Main heading text
 * @param {string} props.description - Description text
 * @param {boolean} props.showArrow - Whether to show the curved arrow (default: true)
 */
const FeatureEmptyState = ( {
    imageUrl,
    imageAlt,
    specimen,
    title,
    description,
    showArrow = true
} ) => {
    // Everything under an aria-hidden subtree must also be unreachable by Tab, or a
    // keyboard user lands on a control assistive tech has been told to ignore. Done
    // in an effect rather than with `inert`, whose support this bundle's browser
    // matrix does not guarantee, and applied to the injected markup's descendants
    // because the specimen arrives as HTML rather than as elements this file renders.
    const previewRef = useRef( null );

    useEffect( () => {
        if ( ! specimen || ! previewRef.current ) {
            return;
        }

        // Previous values recorded and put back on cleanup. The first version
        // overwrote whatever tabindex a node already carried and never restored it,
        // so a specimen that relied on one lost it permanently with no way to opt
        // out — review on sb-customizer#192. Today's specimen is decorative, which
        // is why it was harmless rather than right.
        const touched = [ ...previewRef.current.querySelectorAll(
            'a[href], button, input, select, textarea, [tabindex]'
        ) ].map( ( node ) => {
            const had = node.hasAttribute( 'tabindex' );

            return { node, had, previous: had ? node.getAttribute( 'tabindex' ) : null };
        } );

        touched.forEach( ( { node } ) => node.setAttribute( 'tabindex', '-1' ) );

        return () => {
            touched.forEach( ( { node, had, previous } ) => {
                if ( had ) {
                    node.setAttribute( 'tabindex', previous );
                } else {
                    node.removeAttribute( 'tabindex' );
                }
            } );
        };
    }, [ specimen ] );

    return (
        <div className="sbr-emptystate-ctn">
            {/* Curved Arrow */}
            { showArrow && (
                <div className="sbr-emptystate-arrow-wrapper">
                    <CurvedArrow />
                </div>
            ) }

            {/*
              * Specimen: the real thing where the browser can draw it, a picture
              * otherwise. `aria-hidden` because it is decoration — the surrounding
              * copy already says what it is — but aria-hidden does NOT remove an
              * element from the tab order, and the badge specimen contains a real
              * `target="_blank"` link (tb-footer.php's "Powered by"). So a keyboard
              * user could tab onto a link a screen reader announces nothing for.
              * The effect below takes the whole subtree out of the tab order.
              */}
            <div
                ref={ previewRef }
                className="sbr-emptystate-popup-preview"
                aria-hidden={ specimen ? true : undefined }
            >
                { specimen || (
                    <img
                        src={ imageUrl }
                        alt={ imageAlt }
                        className="sbr-emptystate-popup-image"
                    />
                ) }
            </div>

            {/* Text Content */}
            <div className="sbr-emptystate-text">
                <h3 className="sbr-emptystate-subtitle">
                    { title }
                </h3>
                <p className="sbr-emptystate-description">
                    { description }
                </p>
            </div>
        </div>
    );
};

export default FeatureEmptyState;
