import { Fragment, useId } from 'react';
import { __ } from '@wordpress/i18n';
import SbUtils from '../../Utils/SbUtils';

/**
 * Show/Hide element rows with optional inline edit panels. The Review Alerts
 * markup unchanged, so every state — red eye when hidden, muted label, hover
 * fill, 300ms panel transition — comes from that stylesheet.
 *
 * Rows are fragments, not a div each: the shipped CSS drops the divider on
 * `:last-child`, and one wrapper per row makes every row last.
 *
 * `excludeFromMinimum` names the keys that do not hold the last-visible floor
 * (Review Alerts excludes powered-by, the badge its footer), so a control made
 * only of attribution still counts as empty.
 *
 * @param {Object}   props
 * @param {Array}    props.elements    `{ key, label, edit?, panel? }`.
 * @param {Object}   props.values      `{ [key]: boolean }`.
 * @param {Function} props.onToggle    `(key, nextVisible)`.
 * @param {string}   [props.openPanel] Key whose panel is open.
 * @param {Function} [props.onOpenPanel]
 * @param {Array}    [props.excludeFromMinimum] Keys that do not hold the floor.
 * @param {Object}   [props.locked] `{ [key]: reason }` — rows the current tier or plan does
 *                                  not let the author change. Disabled with the reason as
 *                                  its tooltip, rather than offered and then ignored.
 */
const ShowHideElements = ( {
    // Defaulted like the props below it: rendered before its data arrives,
    // `elements.filter()` and `values[ key ]` threw rather than degrading to an
    // empty list.
    elements = [],
    values = {},
    onToggle = () => {},
    openPanel = null,
    onOpenPanel = () => {},
    excludeFromMinimum = [],
    locked = {},
} ) => {
    // Generated, so two element lists on one screen cannot produce the same
    // describedby target. EmbedTargetPicker took the same fix in this PR.
    const uid = useId();

    const countable = elements.filter(
        ( el ) => ! excludeFromMinimum.includes( el.key ) && values[ el.key ]
    ).length;

    return (
        // `sb-popup-elements-list` only: the `sb-popup-header-list` variant moves
        // the border to the list, which is Review Alerts' one-block look rather
        // than the per-row rule this design draws.
        <div className="sb-popup-elements-list sb-showhide-list">
            { elements.map( ( element ) => {
                const isVisible = !! values[ element.key ];
                const isOpen = openPanel === element.key;
                const holdsFloor = ! excludeFromMinimum.includes( element.key );
                const isLastVisible = isVisible && holdsFloor && countable === 1;
                // PRESENCE locks the row, not the truthiness of the reason. Reading
                // `locked[key] || ''` meant a caller that named a key but had not
                // computed its sentence yet left the row fully editable — the map was
                // populated precisely to stop that, and it silently did nothing.
                const hasLock = Object.prototype.hasOwnProperty.call( locked, element.key );
                const lockReason = hasLock ? String( locked[ element.key ] ?? '' ) : '';

                // `panel` takes a factory (lazy, preferred) or a plain node. The
                // node form is kept because this is a Common component and the
                // cheap shape should still work; only the factory is lazy.
                const hasPanel = !! element.panel;
                const panelNode = typeof element.panel === 'function'
                    ? element.panel
                    : () => element.panel;
                const isFrozen = isLastVisible || hasLock;
                // A frozen row always carries a sentence. An unexplained disabled
                // control is the thing the rest of this PR went to some trouble to
                // remove, so a lock with no reason of its own still says something.
                const tooltip = lockReason
                    || ( isLastVisible ? __( 'At least one element must be visible', 'reviews-feed' ) : '' )
                    || ( hasLock ? __( 'This element cannot be changed', 'reviews-feed' ) : '' );

                return (
                    <Fragment key={ element.key }>
                        { /* The tooltip lives on the ROW, not on the button: a
                             disabled element fires no pointer events, so a `title`
                             there is never shown — and the reason a row is frozen
                             is the one thing the person needs.

                             The toggle is aria-disabled rather than `disabled`, for
                             the same reason as RadioCardGroup: `disabled` takes it out
                             of the tab order, so its own aria-describedby could never
                             be announced. The early return in onClick keeps it inert. */ }
                        <div
                            className={ `sb-popup-element-item sb-popup-header-item ${ isVisible ? 'sb-visible' : 'sb-hidden' } ${ isFrozen ? 'sb-disabled' : '' }` }
                            title={ isFrozen ? tooltip : undefined }
                        >
                            <button
                                type="button"
                                className="sb-popup-header-toggle sb-button-reset"
                                aria-disabled={ isFrozen ? 'true' : undefined }
                                aria-describedby={ isFrozen && tooltip ? `sb-frozen-${ uid }-${ element.key }` : undefined }
                                title={ isFrozen ? undefined : tooltip }
                                onClick={ () => {
                                    if ( isFrozen ) {
                                        return;
                                    }

                                    onToggle( element.key, ! isVisible );
                                } }
                            >
                                { SbUtils.printIcon( isVisible ? 'eye' : 'eyeslash', 'sb-popup-element-icon' ) }
                                <span className="sb-popup-element-label">{ element.label }</span>
                            </button>

                            { isFrozen && tooltip
                                ? <span id={ `sb-frozen-${ uid }-${ element.key }` } className="sb-visually-hidden">{ tooltip }</span>
                                : null }

                            { hasPanel && (
                                <button
                                    type="button"
                                    className={ `sb-popup-header-edit sb-button-reset ${ isOpen ? 'sb-open' : '' }` }
                                    aria-expanded={ isOpen }
                                    onClick={ () => onOpenPanel( isOpen ? null : element.key ) }
                                >
                                    <span>{ __( 'Edit', 'reviews-feed' ) }</span>
                                    { SbUtils.printIcon( isOpen ? 'chevron-top' : 'chevron-bottom' ) }
                                </button>
                            ) }
                        </div>

                        { hasPanel && (
                            <div className={ `sb-popup-header-edit-panel sb-edit-panel-animate ${ isOpen ? 'sb-edit-panel-open' : '' }` }>
                                { /* Built only while open. A closed panel rendered
                                     its whole subtree on every render of the
                                     parent. */ }
                                <div className="sb-popup-edit-panel-inner">{ isOpen ? panelNode() : null }</div>
                            </div>
                        ) }
                    </Fragment>
                );
            } ) }
        </div>
    );
};

export default ShowHideElements;
