import { useEffect, useState } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import { default as ReactSliderInput } from 'react-input-slider';
import { hexToOklchHue, FALLBACK_HEX } from '../../Utils/OklchUtils';

/**
 * Hue slider + HEX readout + reset, in the Review Alerts "Add your own" shell.
 *
 * The thumb runs on local state: round-tripping through a parent lags a drag by a
 * render. `toHex` comes from the caller because the colour a hue makes depends on
 * the consumer (the badge stars are `oklch(0.6 0.25 h)`). Do not define this
 * inside another component — the remount pulls the slider's node mid-drag.
 *
 * @param {Object}   props
 * @param {number}   props.hue         Current hue, 0-359.
 * @param {Function} [props.onChange]  Called with the new hue.
 * @param {Function} [props.toHex]     hue => '#rrggbb', in the consumer's colour
 *                                    space. Defaults to the grey fallback — a
 *                                    consumer that forgets it gets a visible
 *                                    control rather than a render crash.
 * @param {Function} [props.fromHex]   The INVERSE of toHex, in the same colour
 *                                    space. Defaults to the oklch one.
 * @param {boolean}  props.showReset   Whether the reset control is offered.
 * @param {Function} [props.onReset]   Called when reset is pressed.
 * @param {string}   [props.resetTitle] Tooltip, e.g. "Reset to gold".
 * @param {string}   [props.resetLabel] Screen-reader label, spelled out.
 * @param {string}   [props.label]     Heading above the slider; omitted when empty.
 * @param {boolean}  [props.standalone] True when this is the only colour control
 *                                      in its section, which drops the divider
 *                                      that separates it from a preset row.
 * @param {string}   [props.ariaLabel]
 */
const HuePicker = ( {
    hue,
    onChange,
    toHex = () => FALLBACK_HEX,
    fromHex = hexToOklchHue,
    showReset = false,
    onReset,
    resetTitle,
    resetLabel,
    label = '',
    standalone = false,
    ariaLabel,
} ) => {
    const [ localHue, setLocalHue ] = useState( hue );

    // The slider and the HEX field are two different controls and cannot announce
    // under one name. `ariaLabel` names the pair for the caller; the slider says it
    // is the hue slider and the field keeps the plain label.
    // Both controls need a name whether or not the caller passes one. `ariaLabel` is
    // optional with no propType, so the field was exposed unnamed to assistive tech
    // whenever it was omitted — and naming only the slider was the previous round's
    // fix, which is how the field ended up the last one without a name.
    const hexLabel = ariaLabel
        ? sprintf( /* translators: %s: control name, e.g. "Accent" */ __( '%s hex value', 'reviews-feed' ), ariaLabel )
        : __( 'Hex color value', 'reviews-feed' );

    const sliderLabel = ariaLabel
        ? sprintf( /* translators: %s: control name, e.g. "Accent" */ __( '%s hue slider', 'reviews-feed' ), ariaLabel )
        : __( 'Hue slider', 'reviews-feed' );

    // sRGB hex, not the caller's `oklch()`: an unsupported oklch() is invalid at
    // computed-value time, so its `var()` fallback never fires and the slider and
    // swatch come out colourless (Chrome < 111, Firefox < 113, Safari < 15.4).
    const paint = toHex( localHue );

    // What the field shows mid-edit. null means "not being edited" — without it,
    // handleHex's commit-on-six-characters overwrote every partial keystroke.
    const [ typing, setTyping ] = useState( null );

    // Follow the outside when it moves for a reason other than this slider: a
    // reset, a typed hex, a mode switch that repoints the control.
    //
    // `typing` is cleared with it. Leaving it set kept a half-typed hex in the
    // field after an external change, so the readout showed the old keystrokes
    // while the badge had already moved to the new hue.
    useEffect( () => {
        setLocalHue( hue );
        setTyping( null );
    }, [ hue ] );

    const commit = ( next ) => {
        setLocalHue( next );
        // Optional-chained like every other callback in this batch — see
        // RadioCardGroup's `moveTo`, EmbedTargetPicker's `commit` and EmbedModal's
        // `copy`. Cited by symbol: line numbers in those files have already drifted
        // twice inside this PR.
        onChange?.( next );
    };

    const handleHex = ( event ) => {
        const raw = ( event?.target?.value || '' ).replace( '#', '' ).toUpperCase();

        setTyping( raw );

        // Commit on a complete colour only: per keystroke walks the preview
        // through unrelated hues mid-typing.
        if ( /^[0-9A-F]{6}$/.test( raw ) ) {
            // Current hue as the fallback, not fromHex's default of 0. A grey
            // has no hue to read, and 0 is red — so typing FFFFFF used to
            // repaint the badge red. Now it leaves the hue where it was.
            commit( fromHex( `#${ raw }`, localHue ) );
        }
    };

    // Back to the live colour on blur, so an abandoned partial entry does not
    // linger as if it had been applied.
    const handleHexBlur = () => setTyping( null );

    return (
        // `sb-huepicker-standalone` drops the top rule .sb-accent-color-custom
        // carries in review-alert-settings.css: with no preset row above it, it
        // separates nothing. By modifier, so Review Alerts keeps it.
        <div className={ `sb-accent-color-custom ${ standalone ? 'sb-huepicker-standalone' : '' }` }>
            { label ? <span className="sb-accent-color-label">{ label }</span> : null }

            <div className="sb-hue-slider-wrapper" style={ { '--slider-thumb-color': paint } }>
                <div className="sb-slider-content sb-hue-slider-content sb-fs">
                    { /* The slider is the primary control and announced as an
                         unnamed one: `ariaLabel` only ever reached the HEX field.
                         react-input-slider forwards unknown props to its thumb, so
                         the role and the value text go on with it. */ }
                    <ReactSliderInput
                        axis="x"
                        xmin={ 0 }
                        xmax={ 359 }
                        x={ localHue }
                        aria-label={ sliderLabel }
                        aria-valuemin={ 0 }
                        aria-valuemax={ 359 }
                        aria-valuenow={ localHue }
                        aria-valuetext={ `${ localHue }°` }
                        onChange={ ( { x } ) => {
                            // Drop any in-progress text: the slider is the source of
                            // truth now. Only blur cleared `typing` before, and the
                            // slider preventDefaults its mousedown so the field never
                            // loses focus — so the readout sat on the typed colour
                            // while the badge followed the thumb somewhere else.
                            //
                            // Here rather than in commit(), which the typed path also
                            // calls: hex -> hue -> hex is lossy, so clearing there
                            // would rewrite the field under the person typing in it.
                            setTyping( null );
                            commit( Math.round( x ) );
                        } }
                    />
                </div>
            </div>

            { /* The reset is a sibling of the field, not a child: inside, the
                 flex-grow input squeezed it to 2px wide. */ }
            <div className="sb-accent-row">
                <div className="sb-accent-color-hex-row">
                    <span className="sb-accent-color-hex-label">HEX</span>
                    <input
                        type="text"
                        className="sb-accent-color-hex-input"
                        value={ typing ?? toHex( localHue ).replace( '#', '' ).toUpperCase() }
                        onChange={ handleHex }
                        onBlur={ handleHexBlur }
                        maxLength={ 6 }
                        spellCheck="false"
                        autoComplete="off"
                        aria-label={ hexLabel }
                    />
                    <span className="sb-accent-color-preview-circle" style={ { backgroundColor: paint } }></span>
                </div>

                { showReset && (
                    <button
                        type="button"
                        className="sb-btn sb-btn-secondary sb-accent-reset"
                        onClick={ onReset }
                        title={ resetTitle }
                        aria-label={ resetLabel || resetTitle }
                    >
                        { /* The design's stroked rotate-back arrow. The plugin's
                             `reset` icon is filled and reads as another control
                             at this size. */ }
                        <span className="sb-btn-icon">
                            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                                <polyline points="1 4 1 10 7 10"></polyline>
                                <path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"></path>
                            </svg>
                        </span>
                        { __( 'Reset', 'reviews-feed' ) }
                    </button>
                ) }
            </div>
        </div>
    );
};

export default HuePicker;
