import { __ } from '@wordpress/i18n';
import FeatureEmptyState from '../../Common/FeatureEmptyState';

/**
 * Shown when the site has no saved Trust Badges yet — the same shared component
 * the Review Alerts empty state uses.
 *
 * The specimen is a REAL badge, not a screenshot: PHP renders it through the same
 * renderer the front end uses and hands over the markup, so it cannot go stale when the
 * badge design changes. Review Alerts ships a PNG because a popup cannot be drawn this
 * way; a badge can. It carries the site's own rating when one is already cached.
 */
const TrustBadgesEmptyState = () => {
    const assetsURL = window.sb_customizer?.assetsURL || '';
    const specimenHtml = window.sb_customizer?.trustBadges?.specimenHtml || '';

    // The badge stylesheet is the plugin's, enqueued alongside this screen, so these
    // classes are not part of the customizer bundle and the build cannot shake them out.
    const specimen = specimenHtml
        // Enforced by tests/Unit/Badges/BadgeOutputEscapingTest.php in the plugin, which drives
        // the renderer AND each template in templates/frontend/badges/ with hostile values and
        // asserts structurally (DOMXPath: no script element, no on* attribute, no executable
        // scheme). Mutation set .claude/qa/mutations/sbr-163-badge-output-escaping.json removes
        // each escape in turn; all 5 fail a test.
        // nosemgrep: react-dangerouslysetinnerhtml -- Safe: markup from SBR_Badge_Renderer, every dynamic field escaped at output
        ? <div dangerouslySetInnerHTML={ { __html: specimenHtml } } />
        : null;

    return (
        <FeatureEmptyState
            specimen={ specimen }
            // Only reached when no feed resolves, so there is no badge to draw. The
            // Review Alerts artwork stands in rather than leaving a gap; its alt says
            // what is on screen, not the badge it isn't.
            imageUrl={ `${ assetsURL }sb-customizer/assets/images/review-alert-preview.png` }
            imageAlt={ __( 'Reviews Feed preview', 'reviews-feed' ) }
            title={ __( 'Show trust badges that turn visitors into customers', 'reviews-feed' ) }
            description={ __( 'One compact mark combines every review source you have connected into a single star rating — your whole reputation, visible before a visitor has to scroll.', 'reviews-feed' ) }
        />
    );
};

export default TrustBadgesEmptyState;
