import { __, sprintf } from '@wordpress/i18n';
import SbUtils from '../../../Utils/SbUtils'
import { ProsIcon, ConsIcon } from '../../Common/Icons/ReviewIcons'

const PostText = ( { post, postIndex, feedSettings } ) => {
    const providerName = post?.provider?.name?.toLowerCase();
    const newProviders = ['booking', 'woocommerce', 'airbnb', 'aliexpress'];
    // Booking.com specific template
    const renderBookingTemplate = () => {
        const hasTitle = post?.title;
        const hasPros = post?.metadata?.pros;
        const hasCons = post?.metadata?.cons;
        // SMASH-782 Phase 2 — helpful row (mirrors PHP extras/booking.php).
        // Localized via `__()` + `sprintf()` so translators can re-order
        // the count + noun for grammatical agreement in other languages.
        const helpfulCount = parseInt(post?.metadata?.helpful_vote_count, 10) || 0;
        const helpfulText = helpfulCount === 1
            ? __('1 person found this helpful', 'sb-customizer')
            : sprintf(
                /* translators: %d: number of people who marked the review helpful */
                __('%d people found this helpful', 'sb-customizer'),
                helpfulCount
            );

        return (
            <>
                {hasTitle && (
                    <div className='sb-item-title sb-fs sbr-review-horizontal-element'>
                        {post.title}
                    </div>
                )}
                {(hasPros || hasCons) && (
                    <div className='sb-item-pros-cons sbr-review-horizontal-element'>
                        {hasPros && (
                            <div className='sb-item-pros' style={{ display: 'flex', alignItems: 'flex-start', marginBottom: '8px', clear: 'both' }}>
                                <span className='sb-item-pros-icon' style={{ display: 'inline-flex', alignItems: 'center', height: '1lh', flexShrink: 0 }}><ProsIcon /></span>
                                <span className='sb-pros-text'>{SbUtils.printText(post.metadata.pros, feedSettings)}</span>
                            </div>
                        )}
                        {hasCons && (
                            <div className='sb-item-cons' style={{ display: 'flex', alignItems: 'flex-start' }}>
                                <span className='sb-item-cons-icon' style={{ display: 'inline-flex', alignItems: 'center', height: '1lh', flexShrink: 0 }}><ConsIcon /></span>
                                <span className='sb-cons-text'>{SbUtils.printText(post.metadata.cons, feedSettings)}</span>
                            </div>
                        )}
                    </div>
                )}
                {helpfulCount > 0 && (
                    <div className='sb-item-helpful sbr-review-horizontal-element'>
                        <svg className='sb-item-helpful-icon' width='16' height='16' viewBox='0 0 16 16' fill='none' xmlns='http://www.w3.org/2000/svg' aria-hidden='true' focusable='false'>
                            <path d='M14 5.33h-3.63l.75-3.07a1.14 1.14 0 0 0-2-.91L5.5 5a1.16 1.16 0 0 0-.17.55v6.78c0 .37.13.71.39.97.26.26.6.4.97.4H12c.26 0 .5-.08.73-.23.23-.16.4-.35.5-.57l2-4.7c.04-.08.06-.16.07-.25a3 3 0 0 0 .03-.25V6.67c0-.36-.13-.68-.4-.94a1.3 1.3 0 0 0-.93-.4ZM2.67 14c-.37 0-.7-.13-.97-.4a1.3 1.3 0 0 1-.4-.93v-6c0-.36.13-.69.4-.95.26-.26.6-.39.97-.39s.69.13.95.39c.26.26.39.59.39.95v6c0 .36-.13.68-.4.94-.26.26-.58.39-.94.39Z' fill='#696D80'/>
                        </svg>
                        <span className='sb-item-helpful-count'>{helpfulText}</span>
                    </div>
                )}
            </>
        );
    };

    // AliExpress template — mirrors PHP text-aliexpress.php + extras/aliexpress.php.
    // Order: translated indicator (SIBLING before .sb-item-text) → text wrapped
    // in .sb-item-text → variants pills → followup. NOTE: this template is
    // returned as a fragment and rendered WITHOUT the outer `.sb-item-text`
    // wrap (see the conditional in the main PostText return), so DOM structure
    // matches the frontend exactly (translated as sibling, not nested).
    const renderAliExpressTemplate = () => {
        const isTranslated = !!post?.metadata?.translated;
        // Cap the length before the variant regex. The key/value matcher below
        // uses a space-inclusive lookahead, so a pathologically long malformed
        // item_spec could backtrack quadratically and stall the preview. Real
        // AliExpress specs are short (e.g. "Color: Black, Ships From: China"),
        // so 500 chars is well clear of any legitimate value.
        const itemSpec = (post?.metadata?.item_spec || '').toString().trim().slice(0, 500);
        const variants = [];
        if (itemSpec !== '') {
            const re = /([A-Za-z][A-Za-z0-9 _-]*):([^\s][^\s]*(?:\s+[^\s:]+)*?)(?=\s+[A-Za-z][A-Za-z0-9 _-]*:|$)/g;
            let m;
            while ((m = re.exec(itemSpec)) !== null) {
                variants.push(m[0].replace(/^([^:]+):\s*/, '$1: '));
            }
        }
        const followup = post?.metadata?.followup;
        // Coerce to string before `.trim()` — `followup.text` / `.date`
        // may arrive as numbers or other non-string types if the upstream
        // adapter ever drifts. `.trim()` on a non-string throws TypeError
        // and would crash the customizer preview.
        const followupText = (followup?.text ?? '').toString().trim();
        const followupDate = (followup?.date ?? '').toString().trim();
        const hasFollowup = followup && typeof followup === 'object'
            && (followupText !== '' || followupDate !== '');

        return (
            <>
                {isTranslated && (
                    <div className='sb-item-translated'>{__('Translated from original', 'sb-customizer')}</div>
                )}
                <div className='sb-item-text sb-fs sbr-review-horizontal-element'>
                    {SbUtils.printText(post?.text ?? '', feedSettings)}
                </div>
                {hasFollowup && (
                    <div className='sb-item-followup sbr-review-horizontal-element'>
                        <div className='sb-item-followup-header'>
                            <span className='sb-item-followup-label'>{__('Follow-up Review', 'sb-customizer')}</span>
                            {followupDate !== '' && (
                                <span className='sb-item-followup-date'>{followupDate}</span>
                            )}
                        </div>
                        {followupText !== '' && (
                            <div className='sb-item-followup-text'>{followupText}</div>
                        )}
                    </div>
                )}
                {variants.length > 0 && (
                    <div className='sb-item-variants sb-fs sbr-review-horizontal-element'>
                        {variants.map((v, i) => (
                            <span key={i} className='sb-item-variants-pill'>{v}</span>
                        ))}
                    </div>
                )}
            </>
        );
    };

    // Default template for other new providers (can be customized later)
    const renderDefaultNewProviderTemplate = () => {
        return SbUtils.printText(post?.text ?? '', feedSettings);
    };

    // SMASH-1553 — review-title block, rendered ONLY for providers where the
    // title is authoritative customer input. Cannot use a generic `post.title`
    // truthy check because `Util::parse_single_review()` on the plugin side
    // synthesizes a substring-fallback title from the review text when the
    // upstream provider omits one — so non-EDD reviews stored via Collection
    // / Import paths carry a fake "first 40 chars of text" title that would
    // render as a bold heading above the same text. Provider allowlist scopes
    // the render to providers where the title is real. Add new entries here
    // as providers gain genuine review-title support.
    const providersWithReviewTitles = ['edd'];
    const hasRealTitle =
        providersWithReviewTitles.includes(providerName)
        && typeof post?.title === 'string'
        && post.title.length > 0;
    // HTML entity decoding: EDD's save flow runs `esc_html()` on the title
    // BEFORE persisting it to `edd_review_title` comment meta, so the raw
    // value contains entities like `&amp;` / `&#039;`. Rendering it as a JSX
    // text node would display the literal entities. Mirror the review-text
    // body pattern (`SbUtils.printText` / `SbUtils.decodeHtmlEntities`) for
    // consistent rendering across feed elements.
    const titleNode = hasRealTitle ? (
        <div className='sb-item-title'>{SbUtils.decodeHtmlEntities(post.title)}</div>
    ) : null;

    // Check if this is a new provider with custom template
    const renderContent = () => {
        if (newProviders.includes(providerName)) {
            switch (providerName) {
                case 'booking':
                    // Booking template renders its own title — no double-render
                    return renderBookingTemplate();
                case 'aliexpress':
                    return renderAliExpressTemplate();
                case 'woocommerce':
                case 'airbnb':
                    // aliexpress has its own renderAliExpressTemplate above
                    // (translated indicator + variants pills + followup).
                    // woocommerce / airbnb fall through to the default new
                    // provider template, prefixed by `titleNode` so that
                    // when (in the future) one of these providers gets added
                    // to the EDD-style title allowlist, the title block
                    // renders without another file touch. Today the allowlist
                    // is `['edd']` so `titleNode` is null for these — harmless.
                    return (
                        <>
                            {titleNode}
                            {renderDefaultNewProviderTemplate()}
                        </>
                    );
                default:
                    return (
                        <>
                            {titleNode}
                            {SbUtils.printText(post?.text ?? '', feedSettings)}
                        </>
                    );
            }
        }
        // Default template for existing sources (Google, Yelp, Facebook, EDD, etc.)
        return (
            <>
                {titleNode}
                {SbUtils.printText(post?.text ?? '', feedSettings)}
            </>
        );
    };

    // SMASH-782 Phase 2 — provider-specific templates (booking, aliexpress)
    // render their own structure (title/pros/cons/photos for Booking, plus
    // a translated indicator that must be a SIBLING of .sb-item-text for
    // AliExpress). Wrapping them in an outer `.sb-item-text` would change the
    // DOM shape vs the PHP frontend (text.php returns; for these providers
    // and the custom template emits siblings, not nested children). Skip the
    // wrapper for custom-template providers; the templates emit the
    // `.sb-item-text` div themselves when they need it.
    const skipOuterTextWrap = newProviders.includes(providerName) && (providerName === 'booking' || providerName === 'aliexpress');

    if (skipOuterTextWrap) {
        return (
            <>
                {renderContent()}
                { SbUtils.addHighlighter( 'post-text', 'Paragraph' , postIndex ) }
            </>
        );
    }

    // Airbnb uses this default text wrap and joins the new-source section spacing.
    const sbrTextSectionClass = providerName === 'airbnb' ? ' sbr-review-horizontal-element' : '';

    return (
        <div className={ 'sb-item-text sb-fs' + sbrTextSectionClass }>
            {renderContent()}
            { SbUtils.addHighlighter( 'post-text', 'Paragraph' , postIndex ) }
        </div>
    )

}

export default PostText;