import { useRef } from 'react'
import SbUtils from '../../Utils/SbUtils'
const parse = require('html-react-parser');

/**
 * ToggleSet — APG radiogroup pattern.
 *
 * Callers SHOULD pass `ariaLabel` so the radiogroup has an accessible name
 * for screen readers. Without it the group is still functional but unlabeled.
 *
 * Keyboard model (SMASH-1377 v2-r6):
 *  - Roving tabindex: only the selected (or first) option is in the Tab order.
 *  - Arrow keys (Left/Right/Up/Down) move focus and selection, wrapping.
 *    Pro-locked options receive focus but are not auto-activated.
 *  - Enter / Space activates the focused option (or opens the upsell modal).
 */
const ToggleSet = ( props ) => {

    const slug = 'sb-toggleset',
          parentActionsList =  [ 'parentOnClick' ],
          elementsActionsList =  [ 'onClick' ],
          classesList =  [ 'size', 'layout' ];

    const optionRefs = useRef( [] );
    const selectedIndex = props?.options?.findIndex( o => o.value === props?.value ) ?? -1;
    const effectiveIndex = selectedIndex >= 0 ? selectedIndex : 0;

    const onChooseElement = ( value ) => {
        props.onClick( value )
    }

    const handleKeyDown = ( e, opt, optInd, isSettingPro ) => {
        if ( e.key === 'Enter' || e.key === ' ' ) {
            e.preventDefault();
            if ( isSettingPro === false ) {
                onChooseElement( opt.value )
            } else {
                SbUtils.openUpsellModal( isSettingPro, props.upsellModal )
            }
            return;
        }
        if ( [ 'ArrowRight', 'ArrowDown', 'ArrowLeft', 'ArrowUp' ].includes( e.key ) ) {
            e.preventDefault();
            const len = props.options.length;
            const direction = ( e.key === 'ArrowRight' || e.key === 'ArrowDown' ) ? 1 : -1;
            const next = ( optInd + direction + len ) % len;
            const nextOpt = props.options[ next ];
            const nextIsPro = SbUtils.checkSettingIsPro( nextOpt.upsellModal );
            if ( nextIsPro === false || nextIsPro === undefined ) {
                onChooseElement( nextOpt.value )
            }
            optionRefs.current[ next ]?.focus();
        }
    }

    return (
        <div
            className={'sb-toggleset-ctn sb-fs ' + SbUtils.getClassNames( props, slug, classesList)}
            { ...SbUtils.getElementActions( props, parentActionsList ) }
            role="radiogroup"
            aria-label={ props.ariaLabel }
        >
            {
                props?.options?.map( ( opt, optInd ) => {
                    const isSettingPro = SbUtils.checkSettingIsPro( opt.upsellModal );
                    const isActive = props?.value === opt.value;
                    return (
                        <div
                            className='sb-toggleset-elem sb-fs'
                            { ...SbUtils.getElementActions( props, elementsActionsList ) }
                            key={ optInd }
                            ref={ el => optionRefs.current[ optInd ] = el }
                            data-active={ isActive }
                            data-description={ opt.description !== undefined }
                            data-disabled={ isSettingPro !== false }
                            role="radio"
                            tabIndex={ optInd === effectiveIndex ? 0 : -1 }
                            aria-checked={ isActive }
                            aria-disabled={ isSettingPro !== false }
                            onKeyDown={ ( e ) => handleKeyDown( e, opt, optInd, isSettingPro ) }
                            onClick={ () => {
                                if( isSettingPro === false ) {
                                    onChooseElement( opt.value )
                                }else{
                                    SbUtils.openUpsellModal( isSettingPro, props.upsellModal )
                                }
                            }}
                        >
                            <div className='sb-toggleset-elem-deco sb-tr-2'></div>
                            {
                                opt.icon &&
                                <div className='sb-toggleset-elem-icon'>{ SbUtils.printIcon( opt.icon ) }</div>
                            }
                            <div className='sb-toggleset-elem-label'>
                                <span className={(props.strongLabel ? 'sb-bold ' : '') + 'sb-fs'}>
                                    { parse(opt.label) }
                                    { opt.value === 'carousel' &&  SbUtils.printIcon('rocket-premium', 'pro-rocket-icon') }
                                </span>
                                {
                                    opt.description &&
                                    <span className='sb-toggleset-elem-description sb-text-tiny sb-dark2-text sb-fs'>{ parse(opt.description) }</span>
                                }
                            </div>

                        </div>
                    )
                })
            }

        </div>
    )
}

export default ToggleSet;
