import { __ } from '@wordpress/i18n';
import RadioCardGroup from '../Common/RadioCardGroup';

/**
 * Badge style picker (SBR-163). Each tile carries a miniature of the badge it
 * selects, drawn in CSS rather than captured, so it follows a design change and
 * stays sharp at any zoom. Decorative: the label is what the control announces.
 */

/** Filled stars for a mini. Not the real star partial: at 7px it is a shape. */
const MiniStars = () => (
    <span className="sbr-tb-stars" aria-hidden="true">
        { [ 0, 1, 2, 3, 4 ].map( ( i ) => (
            <svg key={ i } width="7" height="7" viewBox="0 0 20 20" fill="currentColor">
                <path d="M10 15.27 16.18 19l-1.64-7.03L20 7.24l-7.19-.61L10 0 7.19 6.63 0 7.24l5.46 4.73L3.82 19z" />
            </svg>
        ) ) }
    </span>
);

const STYLES = [
    {
        value: 'chip',
        label: __( 'Chip', 'reviews-feed' ),
        art: (
            <span className="sb-mini sb-mini-chip">
                <MiniStars />
                <b>4.6</b>
            </span>
        ),
    },
    {
        value: 'card',
        label: __( 'Card', 'reviews-feed' ),
        art: (
            <span className="sb-mini sb-mini-card">
                <b>4.6</b>
                <span>
                    <MiniStars />
                    <i></i>
                </span>
            </span>
        ),
    },
    {
        value: 'medal',
        label: __( 'Medal', 'reviews-feed' ),
        art: (
            <span className="sb-mini sb-mini-medal">
                <b>4.6</b>
                <MiniStars />
            </span>
        ),
    },
];

/* The markup this used to hand-roll is byte for byte what RadioCardGroup emits
   in its tile variant — which had no caller, so the shared component carried a
   branch nothing exercised while two other files rebuilt it. What is left here
   is the part that is actually specific: the miniature badges. */
const TrustBadgeStyleTiles = ( { value, onChange } ) => (
    <RadioCardGroup
        variant="tile"
        value={ value }
        options={ STYLES }
        onChange={ onChange }
        ariaLabel={ __( 'Badge style', 'reviews-feed' ) }
    />
);

export default TrustBadgeStyleTiles;
