import { useContext, useState } from "react"
import FeedEditorContext from '../../Context/FeedEditorContext'
import SbUtils from '../../../Utils/SbUtils'
import CheckBoxSection from "./CheckBoxSection"
import { slugifyForClass } from "../../ReviewsPlugin/Feed/SinglePost"
import { getConfiguredProviderTypes, getProviderLabel } from "./providerElements"

// SMASH-1185 — feature flag. The per-provider Order & Visibility accordion is
// fully built (UI, show/hide, drag-order, single/multi-source gating) but its
// checkboxes still write to ONE shared `postElements` list — per-provider
// persistence + the settings migration are not done yet. Shipping the accordion
// now would expose sections that look per-provider but aren't wired, so it's
// gated OFF until the dedicated PR lands (persistence + migration + the rest of
// the Order & Visibility work). All the accordion code below is preserved and
// re-enabled by flipping this to true. The new-source card ELEMENTS themselves
// (Booking score, pros/cons, AliExpress variants/flag, Airbnb reply — SMASH-1187)
// are unaffected: they render on the cards regardless of this flag.
const PER_PROVIDER_ELEMENTS_ENABLED = false

// Collection feeds (more than one provider type) get one accordion section per
// provider type. The accordion + header follow the prototype design; the inner
// element list is the production CheckBoxSection verbatim, so drag-and-drop,
// drill-in and the show/hide checkboxes keep working. Every section reuses the
// shared postElements list for now.
//
// This is the single gate+render decision point: it reads the provider list
// once and either renders the accordion (>1 type) or falls back to the plain
// CheckBoxSection (<=1 type, or live data not ready). Sidebar always delegates
// here, so the gate and the render can never read different data and leave the
// element editor empty.
const ProviderElementsAccordion = ( { checkBoxSection, checkBoxSectionInd, editorBreadCrumb, parentSection, upsellModal } ) => {

    const { sbCustomizer, editorFeedData } = useContext( FeedEditorContext );

    const providerTypes = getConfiguredProviderTypes( editorFeedData?.feedData );
    const [ openType, setOpenType ] = useState( providerTypes[0] ?? null );

    // Flag OFF (SMASH-1185) → always the flat shared-list editor, for every
    // feed. Single-type feed (or live data not yet populated) → same flat list.
    // Never return an empty container.
    if( ! PER_PROVIDER_ELEMENTS_ENABLED || providerTypes.length <= 1 ){
        return (
            <CheckBoxSection
                checkBoxSection={ checkBoxSection }
                checkBoxSectionInd={ checkBoxSectionInd }
                editorBreadCrumb={ editorBreadCrumb }
                parentSection={ parentSection }
                upsellModal={ upsellModal }
            />
        );
    }

    // Bring the first review of this provider type into view in the preview.
    const scrollToProviderCard = ( type ) => {
        const card = document.querySelector( '.sb-post-item-wrap.sbr-provider-' + slugifyForClass( type ) );
        if( card ){
            card.scrollIntoView( { behavior: 'smooth', block: 'center' } );
        }
    };

    const toggleSection = ( type ) => {
        const willOpen = openType !== type;
        setOpenType( willOpen ? type : null );
        if( willOpen ){
            scrollToProviderCard( type );
        }
    };

    return (
        <div className='sbr-pe-accordion sb-fs'>
            {
                providerTypes.map( ( type ) => {
                    const isOpen = openType === type;
                    // CheckBoxSection mutates checkBoxSection.controls, so give each
                    // section its own clone to keep the lists independent.
                    const sectionClone = {
                        ...checkBoxSection,
                        controls: ( checkBoxSection.controls || [] ).map( ( control ) => ( { ...control } ) )
                    };

                    return (
                        <div className={ 'sbr-pe-accordion-item sb-fs' + ( isOpen ? ' open' : '' ) } key={ type }>
                            <div
                                className='sbr-pe-accordion-header'
                                onClick={ () => toggleSection( type ) }
                            >
                                { SbUtils.printIcon( type + '-provider', 'sb-source-svg' ) }
                                <span className='sbr-pe-provider-name'>{ getProviderLabel( sbCustomizer, type ) }</span>
                            </div>
                            <div className='sbr-pe-accordion-body'>
                                {
                                    isOpen &&
                                    <CheckBoxSection
                                        checkBoxSection={ sectionClone }
                                        editorBreadCrumb={ editorBreadCrumb }
                                        parentSection={ parentSection }
                                        upsellModal={ upsellModal }
                                    />
                                }
                            </div>
                        </div>
                    )
                } )
            }
        </div>
    )

}

export default ProviderElementsAccordion;
