import { useContext, useState, useId } from 'react';
import { __, sprintf } from '@wordpress/i18n';
import SbUtils from '../../Utils/SbUtils';
import { oklchToHex, BADGE_GOLD, BADGE_ACCENT, BADGE_TINT } from '../../Utils/OklchUtils';
import TrustBadgeEditorContext from '../Context/TrustBadgeEditorContext';
import TrustBadgeStyleTiles from './TrustBadgeStyleTiles';
import TrustBadgeSources from './TrustBadgeSources';
import RadioCardGroup from '../Common/RadioCardGroup';
import HuePicker from '../Common/HuePicker';
import ShowHideElements from '../Common/ShowHideElements';
import { visibleElementCount, FOOTER_FALLBACK_TEXT, BADGE_ELEMENT_KEYS, resolveSources } from '../../Utils/BadgeSettings';

/**
 * Trust Badge sidebar (SBR-163). Two tabs, matching Review Alerts: what the badge
 * looks like, then what feeds it. Style, Theme and Colour stay open — every badge
 * makes those three choices; Elements and Sources collapse.
 */

/**
 * Element rows, in the order the design lists them.
 *
 * The KEYS come from BADGE_ELEMENT_KEYS, which `visibleElementCount()` also counts
 * from, so the set cannot drift between the row list and the shown-count heading.
 * Both hardcoded the same five in the same order, and a key added on the PHP side
 * had to be remembered in two places with nothing to fail if one was missed — the
 * drift this PR removed for BADGE_ACTIONS and FALLBACK_LIST_URL. Labels and the
 * `edit` panel stay here, because they are this screen's copy, not the contract.
 */
const ELEMENT_META = {
    show_rating: { label: () => __( 'Rating Value', 'reviews-feed' ) },
    show_stars: { label: () => __( 'Star Rating', 'reviews-feed' ) },
    show_count: { label: () => __( 'Review Count', 'reviews-feed' ) },
    show_logos: { label: () => __( 'Platform Logos', 'reviews-feed' ), edit: 'logos' },
    show_footer: { label: () => __( 'Footer', 'reviews-feed' ), edit: 'footer' },
};

// A key present in the contract but not described here would render a blank row, so
// it falls back to the key itself — visible and greppable rather than empty.
const ELEMENTS = BADGE_ELEMENT_KEYS.map( ( key ) => ( {
    key,
    label: ELEMENT_META[ key ] ? ELEMENT_META[ key ].label() : key,
    ...( ELEMENT_META[ key ]?.edit ? { edit: ELEMENT_META[ key ].edit } : {} ),
} ) );

const THEMES = [
    { value: 'light', label: __( 'Light', 'reviews-feed' ) },
    { value: 'dark', label: __( 'Dark', 'reviews-feed' ) },
    { value: 'tinted', label: __( 'Tinted', 'reviews-feed' ) },
];

/** The tint hue a badge starts on. The gold is BADGE_GOLD.h, which is a
 *  different colour for a different control — this comment named that one. */
const DEFAULT_TINT_HUE = 250;

/**
 * Accent fallback hue, for a stored `accent` that is present but not a number.
 * Only reachable that way: an unset accent has `hasAccent === false`, and the
 * thumb then sits on BADGE_GOLD.h instead.
 */
const DEFAULT_ACCENT_HUE = 45;



/**
 * A stored hue as a usable number, or the fallback.
 *
 * Settings arrive from a saved post, so a value can be '', a non-numeric string
 * or absent. Number() turns the first two into 0 and NaN respectively, and both
 * reach oklchToHex and come back as garbage.
 *
 * @param {*}       value    Stored setting.
 * @param {number}  fallback Hue to use when value is not a finite number.
 * @param {boolean} [enabled=true] When false, the fallback wins outright.
 * @return {number} A finite hue.
 */
const hueOr = ( value, fallback, enabled = true ) => {
    if ( ! enabled ) {
        return fallback;
    }

    const n = Number( value );

    return Number.isFinite( n ) ? n : fallback;
};

/**
 * A permanently-open group: heading, then content, no chevron. Module scope is
 * load-bearing — defined inside TrustBadgeSidebar it is a new function each
 * render, and the remount pulls the hue slider's node mid-drag.
 */
const OpenSection = ( { label, icon, value, children } ) => (
    <div className="sb-customizer-sidebar-sec-el-dropdown sb-fs sb-tb-section">
        <div className="sb-customizer-sidebar-sec-el sb-fs sb-sec-open-hd">
            { icon ? SbUtils.printIcon( icon, 'sb-customizer-sidebar-sec-el-icon' ) : null }
            <span className="sb-small-p sb-bold sb-dark-text">{ label }</span>
            { value ? <span className="sb-customizer-sec-el-value">{ value }</span> : null }
        </div>
        <div className="sb-dropdown-tall">{ children }</div>
    </div>
);

/**
 * A choice inside an edit panel — the same radio-card group as Style and Theme,
 * because `sb-toggleset-*` has no rules in this context. `locked` keeps the stored
 * value, so the choice comes back when the condition lifts.
 *
 * The help line is the only thing that says WHY a locked group cannot be changed,
 * so it is wired to the cards by id rather than left as loose text beside them.
 */
const PanelChoice = ( { label, value, options, onChange, locked = false, lockedValue, help } ) => {
    const helpId = useId();

    return (
        <div className="sb-popup-edit-group">
            <span>{ label }</span>
            <RadioCardGroup
                value={ value }
                options={ options }
                onChange={ onChange }
                ariaLabel={ label }
                locked={ locked }
                lockedValue={ lockedValue }
                describedBy={ help ? helpId : undefined }
            />
            { help ? <span className="sb-popup-edit-help" id={ helpId }>{ help }</span> : null }
        </div>
    );
};

const TrustBadgeSidebar = () => {
    const {
        badge,
        config,
        sources,
        updateSetting,
        updateSettings,
        isProPlus,
    } = useContext( TrustBadgeEditorContext );

    const settings = badge.settings || {};

    const [ tab, setTab ] = useState( 'customize' );
    const [ openElementPanel, setOpenElementPanel ] = useState( null );

    const isTinted = settings.theme === 'tinted';

    // `accent` is stored as a hue string, '' meaning "no accent, keep gold".
    // Empty and zero are different states — hue 0 is red — so the check is on
    // the string, never on truthiness.
    const hasAccent = settings.accent !== '' && settings.accent !== undefined && settings.accent !== null;
    const accentHue = hueOr( settings.accent, DEFAULT_ACCENT_HUE, hasAccent );

    // `??` is not enough here: turning tinting off stores '' (see the reset
    // below), and Number('') is 0 — red — not the default. Anything that is not
    // a finite number falls back instead of reaching oklchToHex as NaN.
    const tintHue = hueOr( settings.tint_hue, DEFAULT_TINT_HUE );

    // The hue the THUMB sits on. With no accent set that is gold's, not the
    // accent default — otherwise the slider points somewhere the badge is not.
    const storedHue = isTinted ? tintHue : ( hasAccent ? accentHue : BADGE_GOLD.h );
    const hueKey = isTinted ? 'tint_hue' : 'accent';


    // The lightness and chroma this section's hue renders at, so the readout and
    // the swatch describe the colour the badge paints. The gold fallback belongs
    // here too, or an unset accent reads as an orange nothing is painting.
    const activeL = isTinted ? BADGE_TINT.l : ( hasAccent ? BADGE_ACCENT.l : BADGE_GOLD.l );
    const activeC = isTinted ? BADGE_TINT.c : ( hasAccent ? BADGE_ACCENT.c : BADGE_GOLD.c );

    const setHue = ( hue ) => {
        updateSetting( hueKey, isTinted ? hue : String( hue ) );
    };

    const resetHue = () => {
        updateSetting( hueKey, isTinted ? DEFAULT_TINT_HUE : '' );
    };

    const showReset = isTinted ? tintHue !== DEFAULT_TINT_HUE : hasAccent;

    const visibleCount = visibleElementCount( settings, isProPlus );

    const renderCustomizeTab = () => (
        <>
            <OpenSection label={ __( 'Style', 'reviews-feed' ) }>
                <TrustBadgeStyleTiles
                    value={ settings.style }
                    onChange={ ( style ) => updateSetting( 'style', style ) }
                />
            </OpenSection>

            <OpenSection label={ __( 'Theme', 'reviews-feed' ) }>
                <RadioCardGroup
                    value={ settings.theme }
                    options={ THEMES }
                    onChange={ ( theme ) => updateSetting( 'theme', theme ) }
                    ariaLabel={ __( 'Theme', 'reviews-feed' ) }
                />
            </OpenSection>

            {/* One control, two jobs: the hue paints the stars on light and dark,
                the surface on tinted, so the heading follows it. No presets — the
                design's colour block is the slider, the field and the reset. */}
            <OpenSection label={ isTinted ? __( 'Tint', 'reviews-feed' ) : __( 'Accent', 'reviews-feed' ) }>
                <HuePicker
                    standalone
                    hue={ storedHue }
                    onChange={ setHue }
                    toHex={ ( h ) => oklchToHex( activeL, activeC, h ) }
                    showReset={ showReset }
                    onReset={ resetHue }
                    resetTitle={ isTinted ? __( 'Reset to default', 'reviews-feed' ) : __( 'Reset to gold', 'reviews-feed' ) }
                    resetLabel={ isTinted
                        ? __( 'Reset tint to default', 'reviews-feed' )
                        : __( 'Reset star color to gold', 'reviews-feed' ) }
                    ariaLabel={ isTinted ? __( 'Tint hue', 'reviews-feed' ) : __( 'Star color hue', 'reviews-feed' ) }
                />
            </OpenSection>

            { /* Permanently open: the rows are the control, each with its own eye
                 toggle, so a second collapse would put two clicks before a switch.
                 The shown-count stays as a heading value. */ }
            <OpenSection
                label={ __( 'Show/Hide Elements', 'reviews-feed' ) }
                icon="eye"
                value={
                    <span className="sb-sec-el-value">
                        { /* translators: 1: shown count, 2: total count */
                            sprintf(
                                __( '%1$d of %2$d shown', 'reviews-feed' ),
                                visibleCount,
                                ELEMENTS.length
                            ) }
                    </span>
                }
            >
                <ShowHideElements
                    elements={ ELEMENTS.map( ( el ) => ( {
                        ...el,
                        // A factory, not a built tree: the map runs on every render
                        // of this tab and both panels were constructed whether or
                        // not one was open. ShowHideElements calls it for the open
                        // one only.
                        panel: el.edit === 'logos'
                            ? renderLogoPanel
                            : ( el.edit === 'footer' ? renderFooterPanel : null ),
                    } ) ) }
                    values={ settings }
                    onToggle={ ( key, next ) => updateSetting( key, next ) }
                    openPanel={ openElementPanel }
                    onOpenPanel={ setOpenElementPanel }
                    excludeFromMinimum={ [ 'show_footer' ] }
                    locked={
                        // Below Pro Plus the renderer forces the attribution whatever is
                        // stored, so the eye is locked rather than offered and ignored.
                        isProPlus
                            ? {}
                            : { show_footer: __( 'The attribution stays on badges below the Plus plan', 'reviews-feed' ) }
                    }
                />
            </OpenSection>
        </>
    );

    const renderLogoPanel = () => {
        // Full logo needs ONE platform that actually has lockup artwork — the same
        // two conditions the renderer applies (logos.php:61 counts distinct
        // providers, :65 requires the artwork to exist). Keyed on the PROVIDER, not
        // the source count, which is where this disagreed with the badge: two
        // sources from one platform draw a single wordmark, and a collection is one
        // source row (provider `collection`, SBR_Sources.php:196) with no artwork of
        // any kind — so the control offered Full logo and the badge quietly drew an
        // icon. The stored pick survives either way; RadioCardGroup's lockedValue
        // only changes which card reads as active.
        const sourceRows = sources?.sourcesList;
        const rowsLoaded = Array.isArray( sourceRows );
        const { selectedSources } = rowsLoaded
            ? resolveSources( sourceRows, settings.sources )
            : { selectedSources: [] };

        const badgeProviders = [ ...new Set(
            selectedSources
                .map( ( row ) => String( row?.provider || '' ) )
                .filter( Boolean )
        ) ];

        // An ABSENT key is not an empty list. `config` is sb_customizer.trustBadges,
        // and lockupProviders comes from the plugin's lockup_providers(); a build
        // that does not localise it leaves this undefined, which is UNKNOWN rather
        // than "no platform has a wordmark". Locking on unknown would say "This
        // platform has no full logo" about Google — the exact class of lie this
        // control was changed to stop. Same reasoning as rowsLoaded below.
        const lockupProviders = Array.isArray( config?.lockupProviders ) ? config.lockupProviders : null;
        const noPlatform      = badgeProviders.length === 0;
        const onePlatform     = badgeProviders.length === 1;
        const hasLockup       = onePlatform
            && ( lockupProviders === null || lockupProviders.includes( badgeProviders[ 0 ] ) );

        // Not locked while the rows are still arriving: before they land
        // resolveSources resolves nothing, which is indistinguishable from "no
        // platform here has artwork", and the group would flash locked on every
        // editor open. Same guard TrustBadgeSources.js:22 documents.
        const logoLocked = rowsLoaded && ! hasLockup;

        // Colour locks on tinted: the surface is one hue, so brand marks fight
        // it. Same shape of rule, different trigger.
        const colorLocked = isTinted;

        return (
            <>
                <PanelChoice
                    label={ __( 'Layout', 'reviews-feed' ) }
                    value={ settings.logo_style }
                    onChange={ ( v ) => updateSetting( 'logo_style', v ) }
                    locked={ logoLocked }
                    lockedValue="icon"
                    help={ logoLocked
                        ? ( noPlatform
                            // "when the badge shows one platform" is true but useless
                            // over a badge showing none — it names a condition instead
                            // of the next action.
                            ? __( 'Pick a source to choose a logo layout', 'reviews-feed' )
                            : ( onePlatform
                                ? __( 'This platform has no full logo, so the badge shows its icon', 'reviews-feed' )
                                : __( 'Full logo is available when the badge shows one platform', 'reviews-feed' ) ) )
                        : '' }
                    options={ [
                        { value: 'full', label: __( 'Full logo', 'reviews-feed' ) },
                        { value: 'icon', label: __( 'Icon only', 'reviews-feed' ) },
                    ] }
                />
                <PanelChoice
                    label={ __( 'Color', 'reviews-feed' ) }
                    value={ settings.logo_color }
                    onChange={ ( v ) => updateSetting( 'logo_color', v ) }
                    locked={ colorLocked }
                    lockedValue="mono"
                    help={ colorLocked
                        ? __( 'Switch to Light or Dark to change logo colors', 'reviews-feed' )
                        : '' }
                    options={ [
                        { value: 'auto', label: __( 'Auto', 'reviews-feed' ) },
                        { value: 'brand', label: __( 'Brand', 'reviews-feed' ) },
                        { value: 'mono', label: __( 'Mono', 'reviews-feed' ) },
                    ] }
                />
            </>
        );
    };

    const renderFooterPanel = () => (
        <>
            { /* Plain inputs with sb-popup-edit-input, not the Input component:
                 this is the same field Review Alerts' Heading ▸ Edit uses, and it
                 carries the panel's own border, radius, hover and focus states.
                 The Input component styles itself for the feed sidebar and looked
                 like a different control one screen over. */ }
            <label className="sb-popup-edit-label">
                <span>{ __( 'Footer text', 'reviews-feed' ) }</span>
                <input
                    type="text"
                    className="sb-popup-edit-input"
                    placeholder={ FOOTER_FALLBACK_TEXT() }
                    value={ isProPlus ? ( settings.footer_text || '' ) : FOOTER_FALLBACK_TEXT() }
                    disabled={ ! isProPlus }
                    onChange={ ( e ) => updateSetting( 'footer_text', e.target.value ) }
                />
            </label>

            <label className="sb-popup-edit-label">
                <span>{ __( 'Footer link', 'reviews-feed' ) }</span>
                <input
                    type="text"
                    className="sb-popup-edit-input"
                    placeholder="https://"
                    value={ isProPlus ? ( settings.footer_url || '' ) : '' }
                    disabled={ ! isProPlus }
                    onChange={ ( e ) => updateSetting( 'footer_url', e.target.value ) }
                />
            </label>

            { /* Below Pro Plus the renderer re-imposes the attribution whatever
                 is stored, so the control says so rather than pretending to be
                 a choice — the free badge always carries it, by design. */ }
            { ! isProPlus && (
                <p className="sb-small-p sb-light-text">
                    { __( 'Badges below the Plus plan always carry the "Powered by Smash Balloon" line. It cannot be edited, relinked or hidden.', 'reviews-feed' ) }
                </p>
            ) }
        </>
    );

    const renderSettingsTab = () => (
        <div className="sb-customizer-sidebar-sec-el-dropdown sb-fs">
            <TrustBadgeSources
                selected={ settings.sources || [] }
                onChange={ ( sources ) => updateSettings( { sources } ) }
            />
        </div>
    );

    return (
        <section className="sb-customizer-sidebar">
            <div className="sb-customizer-sidebar-content sb-fs">
                <div className="sb-customizer-sidebar-tabs sb-fs">
                    { [
                        { id: 'customize', label: __( 'Customize', 'reviews-feed' ) },
                        { id: 'settings', label: __( 'Settings', 'reviews-feed' ) },
                    ].map( ( item ) => (
                        <button
                            type="button"
                            key={ item.id }
                            className="sb-customizer-sidebar-tab sb-button-reset"
                            data-active={ tab === item.id }
                            aria-current={ tab === item.id ? 'true' : undefined }
                            onClick={ () => setTab( item.id ) }
                        >
                            <span className="sb-standard-p sb-bold">{ item.label }</span>
                        </button>
                    ) ) }
                </div>

                <div className="sb-customizer-sidebar-sections sb-fs">
                    <div key={ tab } className="sb-sidebar-section-content">
                        { tab === 'customize' ? renderCustomizeTab() : renderSettingsTab() }
                    </div>
                </div>
            </div>
        </section>
    );
};

export default TrustBadgeSidebar;
