import { __ } from '@wordpress/i18n';
import { ICONS, emphasise } from './EmbedShared';

/**
 * The email destination, as its own view.
 *
 * A separate file rather than a branch inside EmbedModal: it is a full screen with
 * its own back affordance, snippet and image-URL fallback, and it shared nothing
 * with the main view except the icon set and the emphasiser — both of which now
 * live in EmbedShared.
 *
 * @param {Object}   props
 * @param {string}   props.heading     Modal heading for this view.
 * @param {string}   props.emailSnippet The HTML snippet a person pastes.
 * @param {string}   props.imageURL    Direct badge-image URL, the fallback route.
 *                                     Empty when no PNG can be produced — the
 *                                     server gates it on a real render.
 * @param {string}   [props.emailBlocked] Why the route is unavailable, when it is:
 *                                     'imagick' (host cannot rasterise) or
 *                                     'render'. Empty when available.
 * @param {string}   props.previewHtml Rendered badge, for the visual stage.
 * @param {Object}   props.headingRef  Focus target, owned by EmbedModal so a view
 *                                     change moves focus the same way in both.
 * @param {Function} props.onBack      Return to the main view.
 * @param {Function} props.copy        ( text, message ) => void.
 * @param {Function} props.copyForSignature Copies the badge for an email signature.
 * @return {JSX.Element} The email view.
 */
const EmailEmbedView = ( {
    heading,
    emailSnippet,
    imageURL,
    emailBlocked = '',
    previewHtml,
    headingRef,
    onBack,
    copy,
    copyForSignature,
} ) => (
        <div className="sb-embed-modal">
            <div className="sb-embed-leaf">
                { /* The way back: without it the email view can only be left by
                     closing the modal, which loses the other three routes. */ }
                <button
                    type="button"
                    className="sb-embed-back"
                    onClick={ onBack }
                >
                    { /* This file's chevron, turned round: ICONS has no
                         chevronLeft, and a second path would have to be kept in
                         step with the first. */ }
                    <span className="sb-embed-back-icon" style={ { transform: 'rotate(180deg)', display: 'inline-flex' } }>
                        { ICONS.chevron }
                    </span>
                    { __( 'Back', 'reviews-feed' ) }
                </button>

                <h4
                    className="sb-h4 sb-modal-view-heading"
                    tabIndex={ -1 }
                    ref={ headingRef }
                >
                    { heading }
                </h4>

                { /* The badge markup, from SBR_Badge_Renderer through our own
                     nonce- and capability-gated preview endpoint. Every dynamic
                     field is escaped at the output sink — esc_attr on the
                     attributes and esc_html on the labels in
                     templates/frontend/badges/, esc_url on footer_url in
                     tb-footer.php — and no review author or business name
                     reaches badge markup at all. */ }
                { /* Enforced by tests/Unit/Badges/BadgeOutputEscapingTest.php in the plugin, which drives the renderer AND each template in templates/frontend/badges/ with hostile values and asserts structurally (DOMXPath: no script element, no on* attribute, no executable scheme). Mutation set .claude/qa/mutations/sbr-163-badge-output-escaping.json removes each escape in turn; all 5 fail a test. */ }
                { /* nosemgrep: react-dangerouslysetinnerhtml -- Safe: markup from SBR_Badge_Renderer, every dynamic field escaped at output */ }
                <div className="sb-embed-stage" dangerouslySetInnerHTML={ { __html: previewHtml || '' } } />

                <div className="sb-embed-primary">
                    { /* aria-disabled, not `disabled`, and never without a reason
                         beside it: a dead button tells the person nothing, and a
                         disabled one is not even reachable by keyboard to hear the
                         explanation. */ }
                    <button
                        type="button"
                        className="sb-embed-cta"
                        onClick={ () => imageURL && copyForSignature() }
                        aria-disabled={ imageURL ? undefined : 'true' }
                        aria-describedby={ imageURL ? undefined : 'sb-embed-email-blocked' }
                    >
                        { ICONS.copy }
                        <span className="lb">{ __( 'Copy badge for your signature', 'reviews-feed' ) }</span>
                    </button>
                </div>

                { /* The image is an Imagick job — GD cannot rasterise SVG — so on a
                     host without it the whole email route is impossible. Saying so
                     beats a greyed button the person reads as their own mistake. */ }
                { ! imageURL && (
                    <div className="sb-embed-info">
                        { ICONS.info }
                        { /* The id is on the TEXT, not the wrapper: aria-describedby
                             should resolve to the sentence, not to a box that also
                             contains a decorative icon. */ }
                        <div id="sb-embed-email-blocked">
                            { emailBlocked === 'imagick'
                                ? __( 'The email badge needs the ImageMagick PHP extension, which this server does not have. Ask your host to enable it, then reload this page. Every other way of showing the badge still works.', 'reviews-feed' )
                                : __( 'The badge image could not be generated on this server, so the email route is unavailable. Every other way of showing the badge still works.', 'reviews-feed' ) }
                        </div>
                    </div>
                ) }

                { /* Not "updates whenever your rating changes": mail clients
                     cache images, so already-sent mail can lag. "Every new
                     email" is the part that is always true. */ }
                <div className="sb-embed-info">
                    { ICONS.info }
                    <div>{ __( 'An image served from your site. Every new email you send shows your current rating.', 'reviews-feed' ) }</div>
                </div>

                <details className="sb-embed-fallback">
                    <summary>
                        { __( 'Badge did not paste correctly?', 'reviews-feed' ) }
                        { ICONS.chevronDown }
                    </summary>
                    <div className="sb-embed-rungs">
                        <div className="sb-embed-rung">
                            <span className="k">
                                { emphasise(
                                    __( 'If the badge pasted in as visible code, or your editor has a %s, paste this markup instead.', 'reviews-feed' ),
                                    __( 'source view', 'reviews-feed' )
                                ) }
                            </span>
                            <div className="sb-embed-row">
                                <code className="sb-embed-code">{ emailSnippet }</code>
                                { /* Guarded like the button above: unguarded it
                                     copies "undefined" and reports success. */ }
                                <button type="button" className="sb-embed-mini sb-embed-copy"
                                    disabled={ ! emailSnippet }
                                    onClick={ () => emailSnippet && copy( emailSnippet, __( 'HTML snippet copied', 'reviews-feed' ) ) }
                                    aria-label={ __( 'Copy the HTML snippet', 'reviews-feed' ) }>
                                    { ICONS.copy }
                                </button>
                            </div>
                        </div>
                        <div className="sb-embed-rung">
                            <span className="k">
                                { emphasise(
                                    __( 'If your tool only accepts an %s, give it this.', 'reviews-feed' ),
                                    __( 'image URL', 'reviews-feed' )
                                ) }
                            </span>
                            <div className="sb-embed-row">
                                <code className="sb-embed-code">{ imageURL }</code>
                                <button type="button" className="sb-embed-mini sb-embed-copy"
                                    disabled={ ! imageURL }
                                    onClick={ () => imageURL && copy( imageURL, __( 'Image URL copied', 'reviews-feed' ) ) }
                                    aria-label={ __( 'Copy the image URL', 'reviews-feed' ) }>
                                    { ICONS.copy }
                                </button>
                            </div>
                        </div>
                    </div>
                </details>
            </div>
        </div>
);

export default EmailEmbedView;
