import { __ } from "@wordpress/i18n";
import { useContext, useState } from "react";
import SbUtils from "../../../Utils/SbUtils";
import { buildWizardURL, shortcodeFor, createPageAction } from "../../../Utils/EmbedContract";
import Button from "../../Common/Button";
import Input from "../../Common/Input";
import FeedEditorContext from "../../Context/FeedEditorContext";
import EmbedModal from "../../Common/EmbedModal/EmbedModal";
import PopupEmbedModal from "../../Modals/PopupEmbedModal";
import ModalContainer from "../ModalContainer";


/**
 * CustomizerHeader Component
 *
 * Reusable header for all customizer screens (feeds, popups, etc.)
 * Can be used with context (default) or with props for flexibility.
 *
 * Props-based usage (for review alerts, etc.):
 * - editorTopLoader: loader state
 * - itemName: string - the name to display/edit
 * - onNameChange: function(newName) - callback when name changes
 * - onSave: function(exit) - callback to save
 * - onBack: function() - callback for back/close button
 * - hasChanges: boolean - whether there are unsaved changes
 * - editorConfirmDialog: confirm dialog state
 * - sbCustomizer: window.sb_customizer reference
 * - editorNotification: notification state
 * - embedData: object - data for embed modal { id, type: 'feed'|'popup' }
 * - hideEmbed: boolean - hide the embed button
 *
 * Publish/Draft workflow (for review alerts):
 * - status: 'active' | 'inactive' - current publish status
 * - onPublish: function() - callback to publish (activate)
 * - onUnpublish: function() - callback to revert to draft (deactivate)
 */
const CustomizerHeader = ( props ) => {
    // Always call useContext (React hooks rules)
    // Will be null/undefined if not within FeedEditorContext provider
    const contextData = useContext( FeedEditorContext );

    // Determine if using props or context
    // Use props mode when explicit props are provided OR when context is not available
    const useProps = props.itemName !== undefined || props.onSave !== undefined || !contextData;

    // Get values from props or context
    const sbCustomizer = props.sbCustomizer || contextData?.sbCustomizer || window.sb_customizer;
    const editorTopLoader = props.editorTopLoader;
    const editorNotification = props.editorNotification || contextData?.editorNotification;
    const editorConfirmDialog = props.editorConfirmDialog || contextData?.editorConfirmDialog;
    const headerClasses = props.headerClasses || contextData?.headerClasses || { headerCustomClasses: [], setHeaderCustomClasses: () => {} };

    // For context-based usage (feeds)
    const editorActiveViews = contextData?.editorActiveViews;
    const feedDataInitial = contextData?.feedDataInitial;
    const editorFeedData = contextData?.editorFeedData;
    const editorFeedSettings = contextData?.editorFeedSettings;
    const editorFeedStyling = contextData?.editorFeedStyling;

    // Local state for name editing (props mode)
    const [ isEditingName, setIsEditingName ] = useState( false );
    const [ embedModal, setEmbedModal ] = useState( false );

    // Get item name - from props or context
    const getItemName = () => {
        if ( useProps ) {
            return props.itemName || '';
        }
        return editorFeedData?.feedData?.feed_info?.feed_name || '';
    };

    // Check if currently editing name
    const isNameEditing = () => {
        if ( useProps ) {
            return isEditingName;
        }
        return editorActiveViews?.activeViews?.headerInput || false;
    };

    // Toggle name editing
    const toggleNameEditing = () => {
        if ( useProps ) {
            setIsEditingName( !isEditingName );
        } else if ( editorActiveViews ) {
            editorActiveViews.setActiveViews( {
                ...editorActiveViews.activeViews,
                headerInput: !editorActiveViews.activeViews?.headerInput
            } );
        }
    };

    // Handle name change
    const handleNameChange = ( event ) => {
        const newName = event.currentTarget.value;
        if ( useProps && props.onNameChange ) {
            props.onNameChange( newName );
        } else if ( editorFeedData ) {
            editorFeedData.setFeedData( {
                ...editorFeedData.feedData,
                feed_info: {
                    ...editorFeedData.feedData.feed_info,
                    feed_name: newName
                }
            } );
        }
    };

    // Save handler
    const saveUpdateHeader = ( exit = false ) => {
        if ( useProps && props.onSave ) {
            props.onSave( exit );
        } else {
            SbUtils.saveFeedData( editorFeedData, editorFeedStyling, editorFeedSettings, sbCustomizer, editorTopLoader, editorNotification, exit );
        }
    };

    // Check for unsaved changes
    const hasUnsavedChanges = () => {
        if ( useProps ) {
            // Support both function and boolean for hasChanges prop
            if ( typeof props.hasChanges === 'function' ) {
                return props.hasChanges();
            }
            return props.hasChanges || false;
        }
        return JSON.stringify( feedDataInitial?.settings ) !== JSON.stringify( editorFeedSettings?.feedSettings );
    };

    // Back button click handler
    const backButtonClick = () => {
        if ( hasUnsavedChanges() ) {
            const confirmDialogInfo = {
                active: true,
                heading: __( 'Are you Sure?', 'sb-customizer' ),
                description: __( 'Are you sure you want to leave this page, all unsaved settings will be lost, please make sure to save before leaving.', 'sb-customizer' ),
                confirm: {
                    text: __( 'Save and Exit', 'sb-customizer' ),
                    type: 'primary'
                },
                cancel: {
                    text: __( 'Exit without Saving', 'sb-customizer' ),
                    type: 'destructive'
                }
            };

            confirmDialogInfo.confirm.onConfirm = () => {
                saveUpdateHeader( true );
            };

            confirmDialogInfo.cancel.onCancel = () => {
                if ( useProps && props.onBack ) {
                    props.onBack();
                } else {
                    window.location.href = sbCustomizer.builderUrl;
                }
            };

            editorConfirmDialog?.setConfirmDialog( confirmDialogInfo );
        } else {
            if ( useProps && props.onBack ) {
                props.onBack();
            } else {
                window.location.href = sbCustomizer.builderUrl;
            }
        }
    };

    // Handle embed button click
    /**
     * Open the chosen target with our block preselected.
     *
     * Named, alongside saveUpdateHeader/backButtonClick/handleEmbedClick, rather
     * than defined inline in the JSX — the embed block had grown to two full flows
     * written as anonymous props, which is a lot of orchestration to read past to
     * find the markup.
     */
    const embedIntoTarget = ( target ) => {
        // A new tab, as the shipped modal does (CustomizerEmbedModal.js:148):
        // window.location walks past the hasChanges guard with unsaved edits.
        window.open(
            buildWizardURL( {
                adminPostURL: sbCustomizer?.adminPostURL,
                targetId: target.id,
                kind: embedType,
                embeddedId,
            } ),
            '_blank',
            'noopener,noreferrer'
        );
    };

    /**
     * Create a draft page carrying this embed and open it.
     *
     * The tab is opened synchronously on the click and only then filled in, because
     * a window.open() from an async callback is outside the user-gesture stack and
     * popup blockers suppress it.
     */
    const createPageWithEmbed = ( title ) => {
        // Opened synchronously, inside the click. A window.open() from the AJAX
        // callback is outside the user-gesture stack, so popup blockers suppress it and
        // "Create Page and Go" appears to do nothing. Without 'noopener' deliberately:
        // with it the call returns null by spec and there is no handle to point at the
        // new page, so opener is severed by hand instead.
        const draftTab = window.open( '', '_blank' );

        if ( draftTab ) {
            draftTab.opener = null;
        }

        // A route, not a URL flag: the page is a WRITE, so it needs the nonce ajaxPost
        // sends. The old `sbr_create_page` arg would have created posts from a GET.
        SbUtils.ajaxPost(
            sbCustomizer.ajaxHandler,
            {
                action: createPageAction(),
                nonce: sbCustomizer.nonce,
                id: embeddedId,
                title,
            },
            ( data ) => {
                if ( ! data?.data?.editURL ) {
                    // Was a bare return, so a permission, nonce or insert failure
                    // looked like a button that does nothing.
                    draftTab?.close();

                    editorNotification && SbUtils.applyNotification( {
                        type: 'error',
                        icon: 'info',
                        text: data?.data?.message
                            || data?.message
                            || __( 'The page could not be created. Please try again.', 'reviews-feed' ) }, editorNotification );

                    return;
                }

                if ( draftTab ) {
                    draftTab.location = data.data.editURL;
                } else {
                    // Blocked anyway, or opened in a context that refuses it: fall back
                    // rather than lose the page that was just created.
                    window.open( data.data.editURL, '_blank', 'noopener,noreferrer' );
                }
            },
            editorTopLoader,
            editorNotification,
            {
                error: {
                    // This callback raises its own message on a missing editURL,
                    // which includes a refusal — without opting out, ajaxPost adds a
                    // second generic toast on top of it.
                    handledLocally: true,
                    icon: 'info',
                    text: __( 'The page could not be created. Please try again.', 'reviews-feed' ),
                },
            }
        );
    };

    const handleEmbedClick = () => {
        saveUpdateHeader();
        if ( headerClasses?.setHeaderCustomClasses ) {
            headerClasses.setHeaderCustomClasses( [ ...( headerClasses.headerCustomClasses || [] ), 'sb-header-zindex' ] );
        }
        setEmbedModal( true );
    };

    // Close embed modal
    const closeEmbedModal = () => {
        setEmbedModal( false );
        if ( headerClasses?.setHeaderCustomClasses ) {
            const cHeaderC = [ ...( headerClasses.headerCustomClasses || [] ) ];
            const indexOfHeader = cHeaderC.indexOf( 'sb-header-zindex' );
            if ( indexOfHeader > -1 ) {
                cHeaderC.splice( indexOfHeader, 1 );
            }
            headerClasses.setHeaderCustomClasses( [ ...cHeaderC ] );
        }
    };

    // Determine embed modal type
    const embedType = props.embedData?.type || 'feed';

    // Whichever id this screen actually has. Badges hand it over in embedData;
    // feeds keep theirs in the editor context.
    const embeddedId = props.embedData?.id
        || editorFeedData?.feedData?.feed_info?.id
        || editorFeedData?.feedData?.id
        || '';
    const showEmbed = props.hideEmbed !== true;

    const itemName = getItemName();

    return (
        <>
            <Button
                type='secondary'
                size='medium'
                icon='close'
                text={ __( 'Close Editor', 'sb-customizer' ) }
                customClass='sb-close-btn'
                onClick={ backButtonClick }
            />

            <div className='sb-header-feedname-ctn' data-edit={ isNameEditing() }>
                { isNameEditing() && (
                    <Input
                        type='text'
                        size='medium'
                        customClass='sb-header-feedname-input'
                        ariaLabel={ __( 'Feed name', 'sb-customizer' ) }
                        value={ itemName }
                        onChange={ handleNameChange }
                        style={ { width: ( ( itemName.length + 2 ) * 7 ) + 'px' } }
                    />
                ) }
                { !isNameEditing() && (
                    <span className="sb-bold sb-standard-p">{ itemName }</span>
                ) }
                <Button
                    type='secondary'
                    size='small'
                    icon={ isNameEditing() ? 'success' : 'pen' }
                    boxshadow={ false }
                    ariaLabel={ isNameEditing() ? __( 'Save name', 'sb-customizer' ) : __( 'Rename', 'sb-customizer' ) }
                    customClass='sb-header-edit-btn'
                    onClick={ toggleNameEditing }
                />
            </div>

            <div className='sb-header-action-btns'>
                <Button
                    type='secondary'
                    size='medium'
                    icon='help'
                    text={ __( 'Help', 'sb-customizer' ) }
                    link='?page=sbr-support'
                    target='_self'
                />
                { showEmbed && (
                    <Button
                        type='secondary'
                        size='medium'
                        icon='code'
                        text={ __( 'Embed', 'sb-customizer' ) }
                        onClick={ handleEmbedClick }
                    />
                ) }
                { /* Publish/Draft workflow for popups */ }
                { props.status !== undefined ? (
                    props.status === 'inactive' ? (
                        <>
                            { /* Draft state: Save Draft + Publish */ }
                            <Button
                                type='secondary'
                                size='medium'
                                icon='success'
                                iconPosition='left'
                                onClick={ () => saveUpdateHeader() }
                                text={ __( 'Save Draft', 'sb-customizer' ) }
                            />
                            <Button
                                type='primary'
                                size='medium'
                                icon='arrow-top'
                                iconPosition='left'
                                onClick={ props.onPublish }
                                text={ __( 'Publish', 'sb-customizer' ) }
                            />
                        </>
                    ) : (
                        <>
                            { /* Published state: Revert to Draft + Save */ }
                            <Button
                                type='secondary'
                                size='medium'
                                icon='reset'
                                iconPosition='left'
                                onClick={ props.onUnpublish }
                                text={ __( 'Revert to Draft', 'sb-customizer' ) }
                            />
                            <Button
                                type='primary'
                                size='medium'
                                icon='success'
                                iconPosition='left'
                                onClick={ () => saveUpdateHeader() }
                                text={ __( 'Save', 'sb-customizer' ) }
                            />
                        </>
                    )
                ) : (
                    <Button
                        type='primary'
                        size='medium'
                        icon='success'
                        iconPosition='left'
                        onClick={ () => saveUpdateHeader() }
                        text={ __( 'Save', 'sb-customizer' ) }
                    />
                ) }
            </div>

            { embedModal && (
                <ModalContainer
                    size='small'
                    /* The design's frame is 663px — between the shipped small
                       (460) and medium (876), so neither token fits and the
                       width is stated on this class instead. */
                    className={ embedType === 'popup' ? undefined : 'sb-embed-modal-frame' }
                    closebutton={ true }
                    /* `type` styles, `ariaLabel` names. A non-empty `title` would
                       render a visible .sb-modal-title heading each of these modals
                       already draws itself, and `type` alone would announce its
                       untranslated slug. */
                    type={ embedType === 'popup'
                        ? 'embed-review-alert'
                        : ( embedType === 'badge' ? 'embed-trust-badge' : 'embed-feed' ) }
                    ariaLabel={ embedType === 'popup'
                        ? __( 'Embed review alert', 'reviews-feed' )
                        : ( embedType === 'badge'
                            ? __( 'Embed trust badge', 'reviews-feed' )
                            : __( 'Embed feed', 'reviews-feed' ) ) }
                    onClose={ closeEmbedModal }
                >
                    { embedType === 'popup' && (
                        <PopupEmbedModal
                            popupId={ props.embedData?.id }
                            popupName={ itemName }
                            editorNotification={ editorNotification }
                            sbCustomizer={ sbCustomizer }
                            onClose={ closeEmbedModal }
                        />
                    ) }

                    { /* Feeds and badges share one modal; only the section list and
                         the shortcode differ. Email and image are badge-only. */ }
                    { embedType !== 'popup' && (
                        <EmbedModal
                            kind={ embedType === 'badge' ? 'badge' : 'feed' }
                            /* Falls back to the shipped key: only Reviews Feed
                               localises `embedTargets`, so without this the picker
                               renders empty in every other plugin vendoring this
                               package. `wordpressPageLists` is a subset shape and
                               only needs the type the pills key on. */
                            targets={
                                sbCustomizer?.embedTargets
                                || ( sbCustomizer?.wordpressPageLists || [] ).map( ( page ) => ( {
                                    ...page,
                                    type: page.type || 'page',
                                } ) )
                            }
                            /* The feed customizer keeps its id in
                               FeedEditorContext, not embedData — reading only
                               embedData calls every saved feed unsaved. */
                            saved={ !! embeddedId }
                            shortcode={ shortcodeFor( embedType, embeddedId ) }
                            onEmbedToTarget={ embedIntoTarget }
                            /* Badges only. The route creates a draft page carrying the
                               badge block; there is no feed equivalent yet, and an
                               offered control that does nothing is worse than none. */
                            allowCreate={ embedType === 'badge' && !! embeddedId }
                            onCreatePage={ createPageWithEmbed }
                            /* The feed rail's "Add to a Widget" route, which the
                               shipped modal offers on any widget-capable theme
                               (CustomizerEmbedModal.js:93-102). Classic themes have
                               no Site Editor either, so dropping it lost them both
                               routes. */
                            widgetsPageURL={
                                sbCustomizer?.themeSupportsWidgets
                                    ? sbCustomizer?.widgetsPageURL
                                    : ''
                            }
                            /* Block themes only; the section hides itself when this
                               is absent. */
                            siteEditorURL={ sbCustomizer?.siteEditorURL }
                            /* The editor's copy first: the global is PHP's page-load
                               snapshot and goes stale on the first edit. `??`, not
                               `||` — an empty string is the renderer refusing, and
                               must not fall back to a badge the site no longer
                               publishes. ajax_save() returns a fresh emailSnippet, so
                               its declared dimensions follow a style change. */
                            imageURL={ props.embedPreview?.imageURL ?? sbCustomizer?.trustBadges?.imageURL }
                            emailSnippet={ props.embedPreview?.emailSnippet ?? sbCustomizer?.trustBadges?.emailSnippet }
                            emailBlocked={ props.embedPreview?.emailBlocked ?? sbCustomizer?.trustBadges?.emailBlocked }
                            previewHtml={ props.embedPreview?.previewHtml ?? sbCustomizer?.trustBadges?.previewHtml }
                            siteURL={ sbCustomizer?.trustBadges?.siteURL }
                            badgeName={ itemName }
                            blockTitle={ embedType === 'badge'
                                ? __( 'Trust Badge', 'reviews-feed' )
                                : __( 'Reviews Feed', 'reviews-feed' ) }
                            /* Through applyNotification, which schedules the
                               `active: false` (SbUtils.js:154). Notification has no
                               self-dismiss, so setting state directly pins the
                               toast open. */
                            onCopy={ ( text ) => editorNotification && SbUtils.applyNotification(
                                { icon: 'success', text },
                                editorNotification
                            ) }
                            onCopyFailed={ () => editorNotification && SbUtils.applyNotification( {
                                type: 'error',
                                icon: 'info',
                                text: __( 'Could not copy — select the text and copy it manually.', 'reviews-feed' ) }, editorNotification ) }
                        />
                    ) }
                </ModalContainer>
            ) }
        </>
    );
};

export default CustomizerHeader;